L["A green sliver on the health bar for heals on their way, as the unit frames show them."] = "生命条上用一小段绿色显示即将到来的治疗，与单位框体的显示方式相同。"
L["A kill or item for a quest shows for a moment at the top of the screen, small, with a progress bar. Turn it off to see the game's yellow line instead. Move it in unlock mode."] = "任务的击杀或物品进度会在屏幕顶部以小字短暂显示，并带有进度条。关闭后改为显示游戏自带的黄色文字。可在解锁模式中移动。"
L["A line on enemy health bars where your finishing moves start to work. The bar's end up to it lights up in your accent color once the enemy is that low. Your class: warriors (Execute) and paladins (Hammer of Wrath)."] = "在敌人生命条上标出你的斩杀技能开始生效的位置。敌人生命值低于此线时，条末端到此线的部分会以强调色亮起。适用职业：战士（斩杀）和圣骑士（愤怒之锤）。"
L["A mana, rage or energy bar under the health. When off, the frame is all health."] = "在生命条下方显示法力值、怒气或能量条。关闭时框体全部为生命条。"
L["A mark just left of the bar of anything your quests still need. Not inside instances."] = "在你的任务仍需要的目标的条左侧显示标记。副本内不显示。"
L["A member's border turns red while something is attacking them."] = "成员受到攻击时，其边框变为红色。"
L["A member's ring (or name tab without a portrait) turns red while something is attacking them."] = "成员受到攻击时，其头像环（无头像时为名字标签）变为红色。"
L["A name for the new group:"] = "新分组的名称："
L["A name for the new profile (a copy of %s):"] = "新配置文件的名称（%s的副本）："
L["A new profession"] = "新的专业"
L["A new profile, made from %s with your picks."] = "按你的选择从%s生成的新配置文件。"
L["A new zone's name rises in at the top of the screen with a thin line under it, then the subzone and PvP status; a subzone shows just its name, small. It replaces the game's zone text. Follows Motion effects (General > Appearance)."] = "新地区的名字会在屏幕顶部浮现，下方有一条细线，然后是子区域和PvP状态；子区域只以小字显示名字。替代游戏自带的地区文字。遵循动画效果设置（综合 > 外观）。"
L["A note for %s:"] = "给%s的备注："
L["A pale sliver on the health bar for an absorb shield, as the unit frames show them."] = "生命条上用一小段浅色显示吸收护盾，与单位框体的显示方式相同。"
L["A panel behind the whole bar, so its buttons sit on one strip."] = "在整条动作条后面加一块面板，让按钮排在同一条上。"
L["A panel behind the whole bar."] = "在整条后面加一块面板。"
L["A player's <guild> under their name, smaller."] = "在玩家名字下方以较小字体显示<公会>。"
L["A player's casts in their class color, or their class's gradient with a two-color fill. Creatures' casts keep the fill style. Not with the Daylight gradient."] = "玩家的施法使用其职业颜色，双色填充时使用其职业渐变。生物的施法保持原填充样式。使用Daylight渐变时无效。"
L["A player's name in their class color; other units in their reaction's color."] = "玩家名字使用职业颜色；其他单位使用其阵营关系颜色。"
L["A pressed button's icon sinks in a little and springs back as you let go."] = "按下按钮时图标会微微下沉，松开时弹回。"
L["A pulsing border while the spell's proc alert is up."] = "法术触发提示出现时，显示闪动的边框。"
L["A quest ready to hand in shows its title alone. A timed quest never folds."] = "可交付的任务只显示标题。限时任务永远不会折叠。"
L["A quest you've failed, like a timed one that ran out."] = "你已失败的任务，比如超时的限时任务。"
L["A ring over the outer end. Class icons show for players; NPCs show their face. Needs a frame at least 20 tall."] = "在外侧末端显示一个圆环。玩家显示职业图标；NPC显示其头像。框体高度至少需要20。"
L["A round badge with their portrait, or a slim bar with the portrait beside it and the name above."] = "带头像的圆形徽章，或旁边有头像、上方有名字的细条。"
L["A second damage meter in its own window, for two lists at once: healing beside damage, say. Hover it for the same buttons."] = "在单独窗口中显示第二个伤害统计，可同时看两份列表：比如治疗和伤害并排。悬停可看到相同的按钮。"
L["A set already has that name."] = "已有同名的套装。"
L["A shield: the bar empties as it soaks damage, with the amount left on it. Or by its time, like any buff."] = "护盾：条随吸收伤害而减少，并显示剩余量。或者像其他增益一样按时间显示。"
L["A skill going up shows its new rank, out of its cap: Tailoring 152 / 225. More skill-ups move the same line on."] = "技能提升时显示新等级和上限：裁缝 152 / 225。继续提升时更新同一行。"
L["A slash ( / )"] = "斜杠（ / ）"
L["A slim bar under the tooltip of a player or creature."] = "在玩家或生物的鼠标提示下方显示一条细条。"
L["A slot at or under this much durability gets an amber dot and says Repair soon."] = "耐久度等于或低于此值的部位会显示一个琥珀色圆点，并提示“需要尽快修理”。"
L["A small BoE (binds when equipped) or BoU (binds when used) in the top left corner of bank items, until the item is bound to you."] = "在银行物品左上角显示小号的BoE（装备后绑定）或BoU（使用后绑定），直到物品与你绑定。"
L["A small BoE (binds when equipped) or BoU (binds when used) in the top left corner, until the item is bound to you."] = "在左上角显示小号的BoE（装备后绑定）或BoU（使用后绑定），直到物品与你绑定。"
L["A small BoE (binds when equipped) or BoU (binds when used) in the top left corner, until the item is bound."] = "在左上角显示小号的BoE（装备后绑定）或BoU（使用后绑定），直到物品被绑定。"
L["A small Copy button at the top-right of the chat. It opens the tab's text so you can select it and press Ctrl+C. /dui copy does the same."] = "聊天框右上角的一个小复制按钮。它会打开该标签的文字，供你选择后按Ctrl+C复制。/dui copy 效果相同。"
L["A small badge at the foot of the portrait (or the frame's corner without one), colored by how hard the unit is for you."] = "在头像底部（无头像时为框体角落）显示一个小徽章，颜色表示该单位对你的难度。"
L["A small badge at the foot of the portrait, colored by how hard the unit is for you. Needs the portrait or the name tab."] = "在头像底部显示一个小徽章，颜色表示该单位对你的难度。需要头像或名字标签。"
L["A small bar beside each party member who has a pet out. Your own pet keeps its own frame."] = "在每个召出宠物的小队成员旁显示一个小条。你自己的宠物保留其独立框体。"
L["A small crown on the raid leader's tile."] = "在团队领袖的方块上显示一顶小王冠。"
L["A small crown tab beside your party or raid frames while you lead the group or assist in a raid. It opens ready check, role check, a pull timer, target and world markers, and Everyone is assist. When off, these are only in the game's slash commands."] = "当你是队伍领袖或团队助理时，在小队或团队框体旁显示一个小王冠标签。可打开就位确认、职责确认、开怪倒计时、目标与世界标记，以及全员助理。关闭时只能使用游戏的斜杠命令。"
L["A small dot in the top right corner on bank items that are part of one of your equipment sets."] = "属于你某个装备方案的银行物品，右上角显示一个小圆点。"
L["A small dot in the top right corner on items that are part of one of your equipment sets."] = "属于你某个装备方案的物品，右上角显示一个小圆点。"
L["A small gray line at the bottom of spell and item tooltips with its ID: handy for macros, other addons and bug reports. Buff and debuff icons use the game's own tooltip, which can't show it."] = "在法术和物品的鼠标提示底部用一行灰色小字显示其ID：方便编写宏、使用其他插件和报告错误。增益和减益图标使用游戏自带的鼠标提示，无法显示ID。"
L["A small icon in a corner for a debuff you can remove, edged in its type's color."] = "在角落用小图标显示你可以驱散的减益，边框为其类型颜色。"
L["A small mana, rage or energy number on the power bar."] = "在能量条上用小字显示法力值、怒气或能量数值。"
L["A small pet bar beside each party member whose pet is out."] = "在每个召出宠物的小队成员旁显示一个小宠物条。"
L["A small skull on the portrait once your damage over time is enough to finish the target."] = "当你的持续伤害足以杀死目标时，在头像上显示一个小骷髅。"
L["A small skull past the bar's end once your damage over time is enough to finish that enemy."] = "当你的持续伤害足以杀死该敌人时，在条末端外显示一个小骷髅。"
L["A small soft drop shadow under text."] = "文字下方的一层柔和小阴影。"
L["A small square left of the frame: red while your pet is unhappy, yellow while content, green while happy. Hover for its damage, loyalty and diet."] = "框体左侧的小方块：宠物不高兴时为红色，满足时为黄色，快乐时为绿色。悬停可查看其伤害、忠诚度和食性。"
L["A small tag after an elite, dungeon, raid or PvP quest's title, here and in the quest log on the map."] = "在精英、地下城、团队或PvP任务的标题后显示一个小标签，此处和地图上的任务日志都会显示。"
L["A small time at the bottom of the map. Hover it for both local and server time."] = "在地图底部用小字显示时间。悬停可查看本地时间和服务器时间。"
L["A small zone name over each group of quests, the zone you're in first."] = "在每组任务上方用小字显示地区名，当前所在地区排在最前。"
L["A soft glow in the threat color around the health bar."] = "生命条周围显示威胁颜色的柔和光晕。"
L["A soft light behind the arrow, in its color."] = "箭头后方与其同色的柔和光芒。"
L["A soft light in the line's color runs across it as it comes in or adds up."] = "该行出现或累加时，一道与其同色的柔光会扫过它。"
L["A soft light round the frame in the debuff's type color."] = "框体周围显示减益类型颜色的柔光。"
L["A soft light round the tile in the debuff's type color."] = "方块周围显示减益类型颜色的柔光。"
L["A soft shadow round each button."] = "每个按钮周围的柔和阴影。"
L["A soft, minimal interface."] = "柔和、简约的界面。"
L["A soft, warm chime when a tracked quest is ready to hand in."] = "追踪的任务可交付时，发出一声柔和温暖的提示音。"
L["A space"] = "空格"
L["A spell that just lit up, like Overpower or Execute."] = "刚刚亮起的法术，比如压制或斩杀。"
L["A spell with charges: the bar is cut into one piece per charge."] = "有充能次数的法术：条按每次充能分成若干段。"
L["A spell's icon pops and lights up once when it comes off a real cooldown (never for the global cooldown). Needs Motion effects (General > Appearance)."] = "法术真正的冷却结束时（公共冷却不算），图标会弹一下并亮起。需要开启动画效果（综合 > 外观）。"
L["A spell's icon turns gray while it's on cooldown. The global cooldown doesn't count."] = "法术冷却中时图标变灰。公共冷却不算。"
L["A square minimap in the panel. Scroll to zoom."] = "面板中的方形微缩地图。滚动鼠标滚轮缩放。"
L["A stun, fear, polymorph and the like, as a bigger icon beside the bar's end."] = "昏迷、恐惧、变形术之类的效果，在条末端旁以较大图标显示。"
L["A symbol on the world map at each boat dock and zeppelin tower. Hover it to see where it goes."] = "在世界地图上每个码头和飞艇塔处显示一个标志。悬停可查看目的地。"
L["A symbol on the world map at each dungeon and raid entrance. Hover it for the name."] = "在世界地图上每个地下城和团队副本入口处显示一个标志。悬停可查看名称。"
L["A thin bar under the name."] = "名字下方的一条细条。"
L["A thin line across the bars where your threat would pull it: 110% of the tank's in melee, 130% at range. Not shown on a boss, whose numbers the game keeps hidden."] = "在条上用细线标出你的威胁值会引起仇恨的位置：近战为坦克的110%，远程为130%。首领不显示，因为游戏隐藏了其数值。"
L["A thin mana strip along the bottom of the power bar while a form hides your mana."] = "当形态隐藏了你的法力值时，在能量条底部显示一条细法力条。"
L["A thin mana, rage or energy bar at the foot of each tile."] = "在每个方块底部显示一条细的法力值、怒气或能量条。"
L["A thin outline on chat text."] = "聊天文字的细轮廓线。"
L["A thin power bar under each pet's health."] = "在每个宠物的生命条下方显示一条细能量条。"
L["A thin strip under the minimap: gold, gear, bag space, friends online. Hover one for details, click it to open its window."] = "微缩地图下方的一条细栏：金币、装备、背包空间、在线好友。悬停查看详情，点击打开对应窗口。"
L["A thinner outline leaves more of each pip for the color. Set to 0 for none."] = "轮廓越细，每个点的颜色部分越多。设为0则无轮廓。"
L["A tooltip for something in the world (a creature, a player, a mailbox) fades away slowly after the mouse leaves it, as the game does. When off, it's gone at once."] = "世界中事物（生物、玩家、邮箱）的鼠标提示在鼠标移开后会慢慢淡出，与游戏一致。关闭时立即消失。"
L["A trail of small diamonds from your feet to the marker, drifting toward it. Like the marker, it fades away once you're in the quest's area on the map."] = "从你脚下到标记处的一串小菱形，朝标记飘去。和标记一样，你进入地图上的任务区域后会淡出。"
L["A two-minute tour of everything DaylightUI does, picking as you go. Nothing is saved until you finish."] = "两分钟浏览DaylightUI的全部功能，边看边选。完成之前不会保存任何内容。"
L["A warm line of light spreads across the top of the screen, your new level rolls in and what you gained fades in under it, in place of the game's banner. Follows Motion effects (General > Appearance)."] = "一道温暖的光线在屏幕顶部展开，新等级随之滚入，下方淡入你获得的内容，代替游戏自带的横幅。遵循动画效果设置（综合 > 外观）。"
L["A warning when your health or mana drops low."] = "生命值或法力值过低时发出警告。"
L["A word when a fight starts and ends."] = "战斗开始和结束时显示提示文字。"
L["AFK"] = "离开"
L["AVOIDABLE"] = "可躲避"
L["AWAY"] = "离开"
L["Abandon"] = "放弃"
L["Abandon \"%s\"?"] = "放弃“%s”？"
L["Abandon?"] = "放弃？"
L["About 1 in %d of your attacks hits for double damage."] = "你的攻击大约每%d次有1次造成双倍伤害。"
L["About 1 in %d of your shots hits for double damage."] = "你的射击大约每%d次有1次造成双倍伤害。"
L["About 1 in %d of your spells lands a critical hit for half again as much."] = "你的法术大约每%d次有1次爆击，多造成一半伤害。"
L["Above"] = "上方"
L["Above or below the frame, the bar is as wide as the frame. Off: the Width below."] = "在框体上方或下方时，条与框体同宽。关闭：使用下方的宽度。"
L["Above or below the frame: moves the bar sideways from the middle."] = "在框体上方或下方时：将条从中间左右移动。"
L["Above or below the frame: moves the bar up or down."] = "在框体上方或下方时：将条上下移动。"
L["Above the frame"] = "框体上方"
L["Above the health bar"] = "生命条上方"
L["Above the name tab by default, running inward. Yours come first."] = "默认在名字标签上方，向内排列。你施放的排在最前。"
L["Above your debuffs, from the right."] = "在你的减益上方，从右侧开始。"
L["Absorb shields"] = "吸收护盾"
L["Absorbs"] = "吸收"
L["Accent"] = "强调色"
L["Accent color"] = "强调色"
L["Accent follows Appearance, including the Daylight gradient."] = "强调色跟随外观设置，包括Daylight渐变。"
L["Accent follows the accent you picked on the General page, gradient and all."] = "强调色跟随你在综合页面选择的强调色，包括渐变。"
L["Accent follows your accent color (General > Appearance), or pick your own."] = "强调色跟随你的强调色（综合 > 外观），也可以自选。"
L["Accept"] = "接受"
L["Accept key"] = "接受键"
L["Accept quests automatically"] = "自动接受任务"
L["Account"] = "账号"
L["Achievement announcements."] = "成就通告。"
L["Achievement color"] = "成就颜色"
L["Achievements"] = "成就"
L["Across"] = "横向"
L["Across the bar"] = "条内横向"
L["Across the bar keeps it inside. Any other spot puts it there, on or round the frame, so a long name has room. You can also drag it in Design mode."] = "条内横向会让它留在条内。其他位置会把它放在框体上或周围，让长名字有足够空间。也可以在设计模式中拖动。"
L["Across the bar keeps the alignment below. Beside the tile needs space between tiles."] = "条内横向会保持下方的对齐方式。放在方块旁需要方块之间留有空隙。"
L["Across, you shown, by role, icons in corners"] = "横向、显示自己、按职责排序、图标在角落"
L["Action Bar 1"] = "动作条1"
L["Action Bar 2"] = "动作条2"
L["Action Bar 3"] = "动作条3"
L["Action Bar 4"] = "动作条4"
L["Action Bar 5"] = "动作条5"
L["Action Bar 6"] = "动作条6"
L["Action Bar 7"] = "动作条7"
L["Action Bar 8"] = "动作条8"
L["Action Bars"] = "动作条"
L["Action bars"] = "动作条"
L["Action bars, short"] = "动作条"
L["Activate"] = "启用"
L["Activate this set first."] = "请先启用此方案。"
L["Active spell"] = "激活的法术"
L["Active spell color"] = "激活法术颜色"
L["Active spell opacity"] = "激活法术不透明度"
L["Add"] = "添加"
L["Add a friend: a BattleTag (Name#1234) or a character's name."] = "添加好友：输入战网昵称（Name#1234）或角色名字。"
L["Add a group"] = "添加分组"
L["Add friend"] = "添加好友"
L["Add to favorites"] = "加为亲密好友"
L["AddOns"] = "插件"
L["Added with Add piece in Design mode. Drag it on the preview to move it. Up to three parts in one line, each in its own color."] = "在设计模式中用“添加组件”添加。在预览上拖动来移动它。一行最多三部分，每部分颜色各异。"
L["Added with Add piece in Design mode: one more row of auras, with its own filter."] = "在设计模式中用“添加组件”添加：多一行光环，带有自己的过滤器。"
L["Addon button drawer"] = "插件按钮收纳栏"
L["Addon options (Ace3)"] = "插件设置（Ace3）"
L["Addons' minimap buttons and the game's addon menu are gathered into one drawer. The button in the map's bottom-right corner opens it."] = "插件的微缩地图按钮和游戏的插件菜单会收纳到一个收纳栏中。点击地图右下角的按钮打开。"
L["Adds a warm band inside the black outline, lit along the top. When off, the border is a plain dark line."] = "在黑色轮廓内加一条暖色带，顶部有高光。关闭时边框为一条普通的深色线。"
L["Adds about %.0f damage per second to your melee attacks."] = "使你的近战攻击每秒伤害提高约%.0f。"
L["Adds about %.0f damage per second to your shots."] = "使你的射击每秒伤害提高约%.0f。"
L["Adds up to %.0f to your heals."] = "使你的治疗效果最多提高%.0f。"
L["Adds up to %.0f to your spells' damage."] = "使你的法术伤害最多提高%.0f。"
L["Adventure"] = "冒险"
L["Affliction"] = "痛苦"
L["After /reload, the last messages in each chat tab come back, above a gray line."] = "/reload后，每个聊天标签的最后几条消息会恢复显示，位于一条灰线上方。"
L["After a login or /reload the UI starts invisible and glides in. Anything set to fade ends faded."] = "登录或/reload后，界面先隐藏再平滑淡入。设为淡出的部分最终保持淡出。"
L["After a player's guild name."] = "在玩家的公会名之后。"
L["After combat"] = "战斗结束后"
L["After the fight"] = "战斗结束后"
L["Aggro"] = "仇恨"
L["Aggro color"] = "仇恨颜色"
L["Aggro colors"] = "仇恨颜色"
