L["Ah, a fresh face. Goldshire isn't what it was, with kobolds in every mine. Still, a man has to keep his shop."] = "啊，新面孔。闪金镇已经今非昔比了，每座矿洞里都是狗头人。不过，人总得把店开下去。"
