L["Cuts both ends of each line at an angle. When off, the ends are straight."] = "将每一行的两端切成斜角。关闭时两端为直角。"
L["Cuts each tile's right end at an angle, like your own frame; the bars follow it."] = "将每个方块的右端切成斜角，与你自己的框体一样；条也随之变化。"
L["Cuts one end of each pet bar at an angle. When off, the ends are straight."] = "将每个宠物条的一端切成斜角。关闭时末端为直角。"
L["Cuts the end of the bar at an angle. When off, the end is straight."] = "将条的末端切成斜角。关闭时末端为直角。"
L["Cuts the end of your focus's cast bar at an angle. When off, its end is straight. Not while it sits inside the frame."] = "将焦点施法条的末端切成斜角。关闭时末端为直角。位于框体内时无效。"
L["Cuts the end of your target's cast bar at an angle. When off, its end is straight. Not while it sits inside the frame."] = "将目标施法条的末端切成斜角。关闭时末端为直角。位于框体内时无效。"
L["Cuts the frame's inner end at an angle; the bars follow it."] = "将框体内侧末端切成斜角；条也随之变化。"
L["Cuts the left end at an angle; the bars follow it."] = "将左端切成斜角；条也随之变化。"
L["Cuts the right end of each bar at an angle. When off, the ends are square."] = "将每条的右端切成斜角。关闭时末端为直角。"
L["Cuts the right end at an angle; the bars and an attached cast bar follow it."] = "将右端切成斜角；条和附着的施法条也随之变化。"
L["Cuts the right end at an angle; the bars follow it."] = "将右端切成斜角；条也随之变化。"
L["Cutscenes and intro movies end at once. Hold Shift as one starts to watch it."] = "过场动画和开场影片立即结束。开始播放时按住Shift即可观看。"
L["DAMAGE"] = "伤害"
L["DEAD"] = "死亡"
