L["DISPELS"] = "驱散"
L["DND"] = "忙碌"
L["DPS / Tank"] = "DPS / 坦克"
L["DPS / Tank (as it comes)"] = "DPS / 坦克（默认）"
L["DPS/Tank made calm for questing: your action bars and your own frame fade a while after a fight (back under the mouse, in a fight or when you're hurt), the damage meter starts folded (one click on the panel's tab brings it out), the minimap is a little smaller and the XP bar shows its percent. Nothing fades in dungeons, raids, battlegrounds or arenas (General > Appearance, Fade only in the open world). Choose it above to use it. If the profile you're on has moved action bars, offers to bring them along."] = "适合做任务的平静版DPS/坦克：战斗结束一段时间后，你的动作条和自己的框体会淡出（鼠标悬停、进入战斗或受伤时恢复显示），伤害统计默认折叠（点击面板标签一次即可展开），微缩地图稍小，经验条显示百分比。地下城、团队副本、战场和竞技场中不会淡出（综合 > 外观，仅在野外淡出）。在上方选择即可使用。如果当前配置文件移动过动作条，会询问是否一并带上。"
L["DPS/Tank with your party and raid as square tiles under you (you included, missing health on them, dispels easy to see), and your frame and your target's raised a little. Everything it sets is on the Party and Raid pages; move any of them in unlock mode. Choose it above to use it. If the profile you're on has moved action bars, offers to bring them along."] = "DPS/坦克，小队和团队以方块形式显示在你下方（包括你自己，显示损失生命值，易于看清可驱散效果），你和目标的框体略微上移。所有相关设置都在小队和团队页面中；可在解锁模式中移动任何一个。在上方选择即可使用。如果当前配置文件移动过动作条，会询问是否一并带上。"
