L["Daylight UI couldn't skin %s %s: it's left as it is."] = "Daylight UI无法美化%s %s：保持原样。"
L["Daylight gradient"] = "Daylight渐变"
L["Daylight is the warm band inside a dark outline, Flat a plain outline. With None the icon fills the whole button."] = "Daylight为深色轮廓内的暖色带，平面为普通轮廓。选择无时图标填满整个按钮。"
L["Daylight: the frame with its name in a tab above it and the power bar inside. Ribbon: a slim bar with the name and health floating above it and the power as a thin line under it. Default uses the style set for every frame (Extras > Frame style). Each style keeps its own heights."] = "Daylight：名字在上方标签中、能量条在框体内的框体。缎带：一条细条，名字和生命值浮在上方，能量为下方的一条细线。默认使用为所有框体设置的样式（额外 > 框体样式）。每种样式保留各自的高度。"
L["Daylight: the frame with its name in a tab above it and the power bar inside. Ribbon: a slim bar with the name and health floating above it and the power as a thin line under it. Each frame can pick its own on its page."] = "Daylight：名字在上方标签中、能量条在框体内的框体。缎带：一条细条，名字和生命值浮在上方，能量为下方的一条细线。每个框体都可以在自己的页面中单独选择。"
