L["DaylightUI Discord"] = "DaylightUI Discord"
L["DaylightUI has a new setup guide. Take the tour to see everything it can do, or keep your setup as it is."] = "DaylightUI有了新的设置向导。浏览一遍了解它的全部功能，或保持你现有的设置。"
L["DaylightUI is set up on this character. Reload to put it in place?"] = "DaylightUI已在此角色上设置完毕。重载界面以应用吗？"
L["DaylightUI look for speech bubbles (say, yell, party). Instances keep the game's bubbles, since addons can't change them there."] = "为对话泡泡（说、大喊、小队）使用DaylightUI外观。副本中保留游戏自带的泡泡，因为插件无法在副本中更改它们。"
L["DaylightUI moved the quest tracker to fit the panel. Reload to put it in place?"] = "DaylightUI移动了任务追踪器以适应面板。重载界面以应用吗？"
L["DaylightUI put this profile's Edit Mode layout in place. Reload to use it?"] = "DaylightUI已应用此配置文件的编辑模式布局。重载界面以使用吗？"
L["DaylightUI replaces your frames, bars, bags, chat and more with a soft, minimal look. Let's set this character up."] = "DaylightUI以柔和、简约的外观替换你的框体、动作条、背包、聊天等。来为这个角色进行设置吧。"
L["DaylightUI saved the loot window's position. Reload to put it in place?"] = "DaylightUI已保存拾取窗口的位置。重载界面以应用吗？"
