L["Drag a piece to move it. Click it for its settings; the arrow keys then nudge it."] = "拖动一个部件来移动它。点击它查看其设置；之后可用方向键微调。"
L["Drag it to an action bar."] = "将它拖到动作条上。"
L["Drag the pieces of the preview to move them: each stays where you let go, or catches on a dot right beside it. Click one, and the arrow keys nudge it (Shift for bigger steps). Every move changes the same settings as the cards below."] = "拖动预览中的部件来移动它们：每个部件会停在你松开的位置，或吸附到紧邻的点。点击一个部件后，可用方向键微调（按住 Shift 步幅更大）。每次移动都会改变下方卡片中相同的设置。"
L["Drag to move it, or click for its settings."] = "拖动以移动，或点击查看其设置。"
L["Drag to move. Drop it beside another piece to hook it on, drag it away to free it. Delete removes it."] = "拖动以移动。放在另一个部件旁边即可挂靠上去，拖开即可解除。删除会将其移除。"
