L["During a ready check, a tick, a cross or a question mark on each member: ready, not ready, or no answer yet. They stay a few seconds after the check ends."] = "就位确认期间，每位成员身上会显示勾、叉或问号：已就位、未就位或尚未回应。确认结束后它们还会保留几秒。"
L["ENEMY TAKEN"] = "敌方承受"
L["Each bar in its player's class color, or all in one color."] = "每条按其玩家的职业颜色显示，或全部使用同一种颜色。"
L["Each bar's hand (or the queued attack) and the time to the next swing, written on the bar."] = "每条的武器手（或排队中的攻击）以及距离下次挥击的时间，显示在条上。"
L["Each bar's shape and when it shows. Changes apply at once. Move bars in unlock mode."] = "每条的形状和显示时机。更改立即生效。在解锁模式中移动动作条。"
L["Each bar's size, shape and when it shows. Pick the bar with Settings for."] = "每条的尺寸、形状和显示时机。在“设置对象”中选择要调整的条。"
L["Each character uses a profile (one per talent set, with dual spec). Everything on every page changes the profile in use."] = "每个角色使用一个配置文件（启用双天赋时每套天赋各一个）。每个页面上的所有设置都会更改当前使用的配置文件。"
L["Each character's bags are saved when you log out, and its bank each time you visit a banker. See them anywhere with the chest button in your bags, or /dui bank. When off, the button goes away and nothing new is saved."] = "每个角色的背包会在你登出时保存，银行会在你每次访问银行职员时保存。可通过背包中的宝箱按钮或 /dui bank 随时查看。关闭时，按钮会消失，也不会再保存新的内容。"
L["Each combo point you build on your target."] = "你在目标身上积攒的每个连击点数。"
L["Each icon darkens like a clock as its time runs out."] = "每个图标会随时间流逝像时钟一样变暗。"
L["Each icon's width and height."] = "每个图标的宽度和高度。"
L["Each item's name and item level next to its icon. When off, only the icons show, with the item level in each corner and more room for the model."] = "在图标旁显示每件物品的名称和物品等级。关闭时只显示图标，物品等级显示在各自角落，模型也有更多空间。"
L["Each its own"] = "各自独立"
L["Each main-hand swing hits for %.0f to %.0f before armor."] = "每次主手攻击造成%.0f到%.0f点伤害（护甲减免前）。"
L["Each member's health written on their tile."] = "在每位成员的方块上显示其生命值。"
L["Each member's name on their tile."] = "在每位成员的方块上显示其名字。"
L["Each objective line under a quest."] = "任务下方的每一行目标。"
L["Each person who whispers you gets a tab next to the others, and the whisper shows in your main tab as well. When off, whispers only show in the main tab."] = "每个向你发送悄悄话的人都会在其他标签旁获得一个标签，该悄悄话也会显示在你的主标签中。关闭时，悄悄话只显示在主标签中。"
L["Each pip leans like the frames' angled ends. When off, their ends are straight."] = "每个点都像框体的斜角末端一样倾斜。关闭时，末端是直的。"
L["Each pip's end cut at an angle, like the health bar's."] = "每个点的末端切成斜角，与生命条相同。"
L["Each quest's level in front of its title, like [15]."] = "在每个任务的标题前显示其等级，如[15]。"
L["Each quest's title in the tracker."] = "追踪器中每个任务的标题。"
L["Each shot hits for %.0f to %.0f before armor."] = "每次射击造成%.0f到%.0f点伤害（护甲减免前）。"
L["Each square darkens like a clock as your spell runs out."] = "每个方块会随你的法术即将结束像时钟一样变暗。"
L["Each talent set has its own layout. Edit layout and Copy from work on this one."] = "每套天赋都有自己的布局。“编辑布局”和“复制自”作用于当前这套。"
L["Each text updates as it changes. Hover for details: gold on every character, each piece of gear, each bag, who's online."] = "每项文字会随变化实时更新。悬停查看详情：每个角色的金币、每件装备、每个背包、谁在线。"
L["Each threat bar in its player's class color, or all in one color."] = "每条威胁条按其玩家的职业颜色显示，或全部使用同一种颜色。"
