L["Enter says yes when someone asks you something: a group invite, a shared quest, a summon, a resurrect. Never on anything that binds, rolls or costs, and never in combat. Making an inn your home takes your Accept key too."] = "有人向你询问时按回车即表示同意：组队邀请、共享任务、召唤、复活。绝不会作用于任何绑定、掷骰或需要花费的事项，战斗中也不会。将旅店设为你的家时，接受键同样有效。"
