L["Every hand's bar in your class color, or your class's gradient with a two-color fill. A queued attack keeps its own color. Not with the Daylight gradient."] = "每个武器手的条使用你的职业颜色，或使用你职业的双色渐变填充。排队中的攻击保留其自身颜色。不适用于Daylight渐变。"
