L["Every item you dragged onto a group, or moved with Alt-right-click, goes back to its own group."] = "你拖到某个分组上的物品，或用Alt+右键移动的物品，都会回到其原本的分组。"
L["Every line in the tooltips. General uses the font on General > Appearance."] = "鼠标提示中的所有文字。“常规”使用“常规 > 外观”中的字体。"
L["Every line stays until the newest one's time is up, then they all go. When off, each line leaves on its own."] = "每行都会保留到最新一行的时间结束，然后一起消失。关闭时，每行会各自消失。"
L["Every other row on a faint stripe, in the stats and the long lists, so lines are easier to follow."] = "在属性和长列表中隔行加上淡淡的条纹，让各行更容易辨认。"
L["Every part of DaylightUI and what it does. Switch off any you don't want; that applies when you reload."] = "DaylightUI的每个部分及其作用。关闭任何你不需要的部分；重载后生效。"
L["Every part's fade in one place. Each is the same setting as on that part's own page."] = "所有部分的淡出设置集中在一处。每一项都与该部分自身页面上的设置相同。"
