L["Fade out of combat"] = "战斗外淡出"
L["Fade out of combat: fades a while after a fight and comes back in one. Fade in combat: fades a while into a fight and comes back after. Fade until mouseover: stays faded until your mouse is over it. Only when something changes: gone out of a fight, back in one, and back for a moment when it changes (a buff gained or lost, your health, quest progress, XP)."] = "战斗外淡出：战斗结束一段时间后淡出，进入战斗时恢复。战斗中淡出：进入战斗一段时间后淡出，战斗结束后恢复。淡出至鼠标悬停：保持淡出，直到鼠标移到其上。仅在变化时：战斗外隐藏，战斗中显示，发生变化时（获得或失去增益、你的生命值、任务进度、经验）短暂显示。"
L["Fade out of combat: fades a while after a fight and comes back in one. Fade in combat: fades a while into a fight and comes back after. Fade until mouseover: stays faded until your mouse is over it. Only when something changes: gone out of a fight, back in one, and back for a moment when it changes (a buff gained or lost, your health, quest progress, XP). Hidden (in combat, out of combat or always): gone, and its buttons can't be clicked."] = "战斗外淡出：战斗结束一段时间后淡出，进入战斗时恢复。战斗中淡出：进入战斗一段时间后淡出，战斗结束后恢复。淡出至鼠标悬停：保持淡出，直到鼠标移到其上。仅在变化时：战斗外隐藏，战斗中显示，发生变化时（获得或失去增益、你的生命值、任务进度、经验）短暂显示。隐藏（战斗中、战斗外或总是）：完全隐藏，且其按钮无法点击。"
