L["Fade when out of range"] = "超出距离时淡出"
L["Faded opacity"] = "淡出后的不透明度"
L["Fades only while your health is full; comes back as soon as it drops. Show on mouseover still works."] = "仅在你生命值全满时淡出；生命值一下降就会恢复。“鼠标悬停时显示”仍然有效。"
L["Fades only while your pet's health is full; comes back as soon as it drops. Show on mouseover still works."] = "仅在你宠物生命值全满时淡出；生命值一下降就会恢复。“鼠标悬停时显示”仍然有效。"
