L["Hide shows the spell only while it's on cooldown. Only when usable shows it once you can cast it: Riposte after a parry, Overpower after a dodge, Execute on a low target. Both keep the gap: the other spells don't move."] = "“隐藏”仅在法术冷却中时显示它。“仅在可用时”在你可以施放时才显示它：招架后的还击，躲闪后的压制，对低血量目标的斩杀。两者都保留空位：其他法术不会移动。"
