L["Hides the red text and voice line from pressing a button too soon: not enough rage, mana or energy, not ready yet, out of range, no target. The useful ones still show: bags full, interrupted, line of sight, quest messages."] = "隐藏过早按下按钮时的红色文字和语音：怒气、法力值或能量不足，尚未就绪，超出范围，没有目标。有用的仍会显示：背包已满、被打断、视线受阻、任务信息。"
