L["Hover it for buttons: the fight (overall, current, and earlier fights by name), the mode, and reset."] = "悬停时显示按钮：战斗（总体、当前，以及按名称列出的之前的战斗）、模式和重置。"
L["Hovering a quest in the quest log shows its tooltip beside the log, as the game's own log does. Off shows it at the mouse."] = "在任务日志中悬停任务时，在日志旁显示其鼠标提示，与游戏自身的日志相同。关闭则显示在鼠标处。"
