L["How dark the shadow around DaylightUI's frames and windows is."] = "DaylightUI框体和窗口周围阴影的深度。"
L["How each hand's bar is filled: one color each, the Daylight gradient (the logo's blue to orange), or a two-color gradient per hand, set right here. A queued attack always keeps its own color."] = "每个武器手的条如何填充：各自单一颜色、Daylight渐变（标志的蓝到橙），或在此处为每只手设置的双色渐变。排队中的攻击始终保留其自身颜色。"
L["How every cast bar (yours, target's, focus's) is filled: one color each, the Daylight gradient (the logo's blue to orange), or a two-color gradient per kind of cast, set right here."] = "每个施法条（你的、目标的、焦点的）如何填充：各自单一颜色、Daylight渐变（标志的蓝到橙），或在此处为每种施法设置的双色渐变。"
L["How far above the cursor the tooltip's corner sits (below zero: lower down)."] = "鼠标提示的角位于光标上方多远（小于零：更低）。"
L["How far along that quest objective is (4/10, or 45%), small, beside the !."] = "该任务目标的完成进度（4/10或45%），以小字显示在!旁边。"
L["How far away plates show, in yards. 60 is the most the game allows."] = "姓名板在多远处显示，以码为单位。60是游戏允许的最大值。"
L["How far away the spot is."] = "该地点有多远。"
L["How far from the target the numbers start."] = "数字从距离目标多远处开始。"
L["How far it fades. At 0 it disappears fully. Never more than Opacity."] = "淡出的程度。为0时完全消失。不会超过“不透明度”。"
L["How far past the name and bar a click still selects the unit."] = "在名字和条之外多远点击仍可选中该单位。"
L["How far right of the cursor the tooltip's corner sits (below zero: to the left)."] = "鼠标提示的角位于光标右侧多远（小于零：向左）。"
L["How far the camera can zoom out. 100% is the game's normal limit; the far right end is as far as this client allows. At 100% the game's own setting is left alone."] = "镜头可以拉远多少。100%为游戏正常上限；最右端为此客户端允许的最远距离。为100%时不改动游戏自身的设置。"
L["How far the frames' angled ends lean, on every unit frame and cast bar. 21% is the usual look."] = "所有单位框体和施法条上框体斜角末端的倾斜程度。21%为常规外观。"
L["How far the name tab's shadow spreads. 0 leaves no shadow."] = "名字标签阴影的扩散范围。0为无阴影。"
L["How far the numbers fly out to the sides. At 0 they go straight up, the game's own way."] = "数字向两侧飞出多远。为0时直线上升，即游戏自身的方式。"
L["How far the panel reaches past the buttons on every side."] = "面板在每一侧超出按钮多远。"
L["How far the soft shadow around DaylightUI's frames and windows reaches."] = "DaylightUI框体和窗口周围柔和阴影的范围。"
L["How far this frame's shadow spreads. 0 leaves no shadow."] = "此框体阴影的扩散范围。0为无阴影。"
L["How far through the level you are, e.g. 24%. With the numbers on too, it sits between them and the rested XP."] = "你在当前等级中的进度，例如24%。同时显示数值时，它位于数值和精力充沛经验之间。"
L["How health and power numbers are written on unit frames, extra texts and nameplates. Percents stay as they are."] = "单位框体、额外文字和姓名板上生命值和能量数值的写法。百分比保持不变。"
L["How long a line stays on screen before it fades away."] = "一行在屏幕上停留多久后淡出。"
L["How long a new item stays in Recent before it goes to its own group."] = "新物品在“最近”中停留多久后进入其自身分组。"
L["How long each buff and debuff has left, on the top edge of its icon."] = "每个增益和减益效果剩余的时间，显示在其图标顶部边缘。"
L["How long each line stays after your last loot of it."] = "每行在你最后一次拾取该物品后停留多久。"
L["How long it stays before fading, unless the buffs land first."] = "在淡出前停留多久，除非增益先到。"
L["How low the enemy's health has to be."] = "敌人生命值需要低到多少。"
L["How many bars sit on your screen. Each one can be changed on its own later."] = "屏幕上有多少条动作条。之后每条都可以单独更改。"
L["How many buttons this bar shows."] = "此动作条显示多少个按钮。"
L["How many data texts share the strip. Pick what each shows under Slots."] = "共享此栏的数据文字数量。在“栏位”下选择每项显示的内容。"
L["How many of the newest messages per chat tab come back after /reload."] = "/reload 后每个聊天标签恢复多少条最新消息。"
L["How many rows the buttons wrap into (columns when the bar is vertical)."] = "按钮换行成几行（动作条竖直时为几列）。"
L["How many slots fit in each row of the bag. More columns make it wider and shorter."] = "背包每行放多少个栏位。列数越多，背包越宽越矮。"
L["How many yards away it is."] = "它在多少码之外。"
L["How much a block, absorb or resist saved you."] = "格挡、吸收或抵抗为你挡下了多少。"
L["How much color the empty part of a bar keeps."] = "条的空白部分保留多少颜色。"
L["How much of the health bar's width the row spans, centered."] = "该行占生命条宽度的多少，居中。"
L["How much the shield can still soak, at the bar's right end."] = "护盾还能吸收多少，显示在条的右端。"
L["How much the shield can still soak, on the icon in place of its time. Its size and color are the cooldown numbers'."] = "护盾还能吸收多少，显示在图标上替代其时间。其大小和颜色与冷却数字相同。"
L["How objective lines show their progress: in the colors below, green once done, or shading from red to green as the count fills."] = "目标行如何显示进度：使用下方颜色、完成后变绿，或随计数增加从红渐变到绿。"
L["How round the name tab's corners are. 0 keeps them sharp."] = "名字标签圆角的程度。0保持直角。"
L["How round this frame's corners are. 0 keeps them sharp."] = "此框体圆角的程度。0保持直角。"
L["How see-through a frame gets while its unit is out of range."] = "单位超出距离时框体的透明程度。"
L["How see-through a spell set to Fade gets, ready or on cooldown."] = "设为“淡化”的法术的透明程度，无论就绪或冷却中。"
L["How see-through a spell's icon is while it's on cooldown. The global cooldown doesn't count."] = "法术图标在冷却中的透明程度。公共冷却不计入。"
L["How see-through every window and panel is: bags, character, spellbook, NPC, group finder, the game's windows we restyle, and chat, the info panel, the quest box and the buff bars unless they have a separate one on their pages."] = "每个窗口和面板的透明程度：背包、角色、法术书、NPC、队伍查找器、DaylightUI重新设计样式的游戏窗口，以及聊天、信息面板、任务框和增益条（除非它们在自己的页面上有单独设置）。"
L["How see-through it is while shown, whatever the fade does."] = "显示时的透明程度，无论淡出如何设置。"
L["How see-through it is, when it fades and how far. Unlocked, in test mode or with this page open, it shows at its opacity."] = "它的透明程度、何时淡出以及淡出多少。解锁、测试模式或打开此页面时，它以其不透明度显示。"
L["How see-through party and raid frames get while a member is out of range."] = "成员超出距离时小队和团队框体的透明程度。"
L["How see-through the borders around DaylightUI's frames and windows are."] = "DaylightUI框体和窗口周围边框的透明程度。"
L["How see-through the info panel's boxes and the meters' own windows are."] = "信息面板方框和统计自身窗口的透明程度。"
L["How see-through the other plates get while you have a target."] = "你有目标时其他姓名板的透明程度。"
L["How see-through the world map's symbols are. Lower it to see more of the map under them."] = "世界地图上符号的透明程度。调低可看到符号下更多的地图。"
L["How should it look?"] = "你希望它看起来怎样？"
L["How solid its background is: 0 is fully see-through."] = "背景的不透明程度：0为完全透明。"
L["How solid the ribbon behind each loot feed line is: 0 is fully see-through."] = "每行拾取提示背后色带的不透明程度：0为完全透明。"
L["How solid the dark background is."] = "深色背景的不透明程度。"
L["How strong the highlight on an active spell is."] = "正在生效的法术高亮的强度。"
L["How strong the mouseover color over the icon is."] = "图标上鼠标悬停颜色的强度。"
L["How strong the pressed color over the icon is."] = "图标上按下颜色的强度。"
L["How strongly it lights up once the enemy is in range."] = "敌人进入范围后它亮起的强度。"
L["How strongly the debuff's color tints the health bar. Only for a Tint or Both highlight."] = "减益效果的颜色对生命条染色的强度。仅适用于“染色”或“同时显示”高亮。"
L["How strongly the spell cost shows on your power bar."] = "法术消耗在你的能量条上显示的强度。"
L["How tall a friendly plate's health bar is."] = "友方姓名板生命条的高度。"
L["How tall each enemy plate's health bar is."] = "每个敌方姓名板生命条的高度。"
L["How tall each line of text over you is. The game's own is 25."] = "你头顶每行文字的高度。游戏默认值为25。"
L["How tall each of the threat meter's bars is."] = "威胁统计每条的高度。"
L["How tall each of this meter's bars is."] = "此统计每条的高度。"
L["How tall each pet bar is."] = "每个宠物条的高度。"
L["How tall each raid tile is."] = "每个团队方块的高度。"
L["How tall each swing timer bar is."] = "每个挥击计时条的高度。"
L["How tall each tile's power bar is."] = "每个方块能量条的高度。"
L["How tall every other plate's health bar is while you have a target, as a share of Health bar height."] = "你有目标时其他每个姓名板生命条的高度，以“生命条高度”的比例表示。"
L["How tall the cast bar under an enemy plate is."] = "敌方姓名板下方施法条的高度。"
L["How tall the experience bar is."] = "经验条的高度。"
L["How tall the health bar is."] = "生命条的高度。"
L["How tall the health bar under the tooltip is."] = "鼠标提示下方生命条的高度。"
L["How tall the meter's own window is."] = "统计自身窗口的高度。"
L["How tall the pets' power bars are."] = "宠物能量条的高度。"
L["How tall the power bar is."] = "能量条的高度。"
L["How tall the second meter's window is."] = "第二个统计窗口的高度。"
L["How tall the tab holding the name above the frame is."] = "框体上方容纳名字的标签的高度。"
L["How tall this frame is."] = "此框体的高度。"
L["How tall your cast bar is."] = "你施法条的高度。"
L["How tall your focus's cast bar is. Not inside the frame, where it takes the power bar's place."] = "你焦点施法条的高度。在框体内时不适用，此时它替代能量条的位置。"
L["How tall your target's cast bar is. Not inside the frame, where it takes the power bar's place."] = "你目标施法条的高度。在框体内时不适用，此时它替代能量条的位置。"
L["How tall your target's health bar is, as a share of Health bar height."] = "你目标生命条的高度，以“生命条高度”的比例表示。"
L["How the health text on friendly plates reads: a percent, the health itself, health out of max, both, or what's missing."] = "友方姓名板上生命值文字的显示方式：百分比、生命值本身、生命值/最大值、两者兼有，或缺失的生命值。"
L["How the health text reads: a percent, the health itself, health out of max, both, or what's missing."] = "生命值文字的显示方式：百分比、生命值本身、生命值/最大值、两者兼有，或缺失的生命值。"
L["How the pets' health text is written."] = "宠物生命值文字的写法。"
L["How the power text is written."] = "能量文字的写法。"
L["How the tiles' health text is written. Missing health shows nothing while the member is at full."] = "方块生命值文字的写法。成员满血时“缺失”不显示任何内容。"
L["How thick the border around each button is."] = "每个按钮周围边框的粗细。"
L["How thick the name tab's outline is. 0 leaves none."] = "名字标签轮廓的粗细。0为无轮廓。"
L["How this category's buffs are edged: one color or a gradient. Click to change."] = "此类增益的边缘样式：单一颜色或渐变。点击更改。"
L["How this extra text writes the health."] = "此额外文字如何显示生命值。"
L["How this extra text writes the power."] = "此额外文字如何显示能量。"
L["How wide a friendly plate's health bar is."] = "友方姓名板生命条的宽度。"
L["How wide each combo point pip is. Not while the pips match the frame's width."] = "每个连击点的宽度。点与框体等宽时不适用。"
L["How wide each enemy plate's health bar is."] = "每个敌方姓名板生命条的宽度。"
L["How wide each pet bar is."] = "每个宠物条的宽度。"
L["How wide each raid tile is."] = "每个团队方块的宽度。"
L["How wide every other plate is while you have a target, as a share of Width."] = "你有目标时其他每个姓名板的宽度，以“宽度”的比例表示。"
L["How wide the bars are."] = "条的宽度。"
L["How wide the damage meter is, in the panel or in its own window."] = "伤害统计的宽度，在面板中或在其自身窗口中。"
L["How wide the list is."] = "列表的宽度。"
L["How wide the name tab is when Name tab width is Fixed width."] = "当“名字标签宽度”为“固定宽度”时名字标签的宽度。"
L["How wide the second meter's window is. Dragging its corner in unlock mode sets this too."] = "第二个统计窗口的宽度。在解锁模式中拖动其角落也会设置此项。"
L["How wide the separate experience bar is. Dragging its corner in unlock mode sets this too."] = "独立经验条的宽度。在解锁模式中拖动其角落也会设置此项。"
L["How wide the threat meter is."] = "威胁统计的宽度。"
L["How wide this frame is."] = "此框体的宽度。"
L["How wide your focus's cast bar is. Not inside the frame, or while it matches the frame's width."] = "你焦点施法条的宽度。在框体内时或与框体等宽时不适用。"
L["How wide your target's cast bar is. Not inside the frame, or while it matches the frame's width."] = "你目标施法条的宽度。在框体内时或与框体等宽时不适用。"
L["How wide your target's plate is, as a share of Width."] = "你目标姓名板的宽度，以“宽度”的比例表示。"
L["How you find your way to quests, and how they show in the tracker."] = "你如何寻找任务，以及任务在追踪器中如何显示。"
L["How your target's plate stands out from the rest."] = "你目标的姓名板如何从其他姓名板中突出。"
L["Hunter"] = "猎人"
L["Hunters: a line on the ranged bar where Auto Shot's wind-up starts, adjusted for haste and your ping. Moving past it holds the shot back, so the bar stays full and says Stop moving until you stand still."] = "猎人：远程条上的一条线，标示自动射击开始蓄力的位置，已按急速和你的延迟调整。越过该线后移动会阻止射击，此时条保持满格并显示“停止移动”，直到你站定。"
L["I'd like to train."] = "我想接受训练。"
L["INTERRUPTS"] = "打断"
L["Icon"] = "图标"
L["Icon (the game's)"] = "图标（游戏的）"
L["Icon look"] = "图标外观"
L["Icon per class"] = "每职业图标"
L["Icon positions and sizes"] = "图标位置和尺寸"
L["Icon size"] = "图标尺寸"
L["Icon style"] = "图标样式"
L["Icon zoom"] = "图标缩放"
L["Icons fill from the bar's right edge leftward, toward the middle of the screen."] = "图标从条的右边缘向左填充，朝向屏幕中央。"
L["Icons left / right"] = "图标 左/右"
L["Icons on a row before it wraps to the next."] = "换到下一行前每行的图标数。"
L["Icons on bars"] = "条上的图标"
L["Icons per row"] = "每行图标数"
L["Icons up / down"] = "图标 上/下"
L["Idle time (seconds)"] = "空闲时间（秒）"
L["Ignore"] = "屏蔽"
L["Ignored"] = "已屏蔽"
L["Import"] = "导入"
L["Import profile"] = "导入配置文件"
L["Imported the profile %s."] = "已导入配置文件%s。"
L["In a group or with a pet, a small tag on the frame's top inner corner: your threat on it, where 100% means it turns on you. Orange as you get close, red once it's on you."] = "在队伍中或带宠物时，框体顶部内角的小标签：你对它的威胁，100%表示它会转向你。接近时为橙色，转向你后为红色。"
L["In a group, colors a mob by who it's attacking; solo plates never change. As a tank: red when it's attacking someone else, orange when you're about to lose it, normal while you hold it. As damage or healer: orange when you're close to pulling it, red once it's attacking you."] = "在队伍中，根据怪物攻击的对象为其着色；单人时姓名板不会变化。作为坦克：它攻击他人时为红色，你即将失去仇恨时为橙色，你稳住仇恨时为正常。作为伤害输出或治疗者：你即将拉到仇恨时为橙色，它攻击你后为红色。"
L["In a group or with a pet, the target's ring (and threat tag) turns this color as you get close to pulling it."] = "在队伍中或带宠物时，当你即将拉到目标的仇恨时，目标的环（和威胁标签）会变为此颜色。"
L["In a raid, only the leader and assists can use the leader tools."] = "在团队中，只有领袖和助理可以使用领袖工具。"
L["In a row above the bar."] = "在条上方排成一行。"
L["In categories"] = "按分类"
L["In columns"] = "按列"
L["In combat"] = "战斗中"
L["In combat in a group or with a pet"] = "在队伍中或带宠物战斗时"
L["In combat, when I'm the tank"] = "战斗中，当我是坦克时"
L["In dungeons, raids, battlegrounds and arenas, everything set to fade stays shown, as if its fade were Never. It fades again once you're back outside."] = "在地下城、团队副本、战场和竞技场中，所有设为淡出的内容都会保持显示，如同其淡出设为“从不”。回到外面后会再次淡出。"
L["In fights"] = "战斗中"
L["In fights and when idle"] = "战斗中和空闲时"
L["In fights: the panel and tabs float away and the messages stay over the world. When idle: the whole chat also fades when nothing new has come in for a while. Always: no panel or tabs while you play, only messages. The mouse over the chat or pressing Enter brings it back."] = "战斗中：面板和标签会淡去，消息停留在游戏画面上。空闲时：一段时间没有新消息时，整个聊天也会淡出。总是：游戏时没有面板或标签，只有消息。鼠标移到聊天上或按回车即可恢复。"
L["In progress"] = "进行中"
L["In rows"] = "按行"
L["In screen pixels, so it stays sharp at any UI scale. Heavy border needs 3 or more."] = "以屏幕像素为单位，因此在任何界面缩放下都保持清晰。粗边框需要3或以上。"
L["In the chat box, Up and Down step through what you sent. Alt+Up and Alt+Down still work as before. While the box is open, the arrow keys don't turn your character."] = "在聊天输入框中，上下方向键可以浏览你发送过的内容。Alt+上和Alt+下仍和以前一样。输入框打开时，方向键不会转动你的角色。"
L["In the group"] = "在队伍中"
L["In the info panel"] = "在信息面板中"
L["In use"] = "使用中"
L["In use: %s"] = "使用中：%s"
L["In your accent color (Appearance), following it when it changes. When off, uses the color below."] = "使用你的强调色（外观），并随其改变。关闭时使用下方的颜色。"
L["In your layout: click to pick it."] = "在你的布局中：点击以选择它。"
L["Inactive"] = "非活跃"
L["Inbox"] = "收件箱"
L["Incoming heals"] = "即将到来的治疗"
L["Info"] = "信息"
L["Info Panel"] = "信息面板"
L["Info panel"] = "信息面板"
L["Info panel background opacity"] = "信息面板背景不透明度"
L["Inner end"] = "内侧末端"
L["Inside the frame"] = "框体内"
L["Inside the frame it covers the power bar, as wide as it (in the Ribbon style it sits below the frame instead). Above, below or on its own it's a bar you size here; on its own you move it in unlock mode."] = "在框体内时，它覆盖能量条并与其等宽（在缎带样式中则位于框体下方）。在上方、下方或独立时，它是一个你在此设置尺寸的条；独立时在解锁模式中移动它。"
L["Inspect"] = "观察"
L["Inspecting a player opens DaylightUI's window, with their gear and talents. Turn it off to use the game's window."] = "观察玩家时打开DaylightUI的窗口，显示其装备和天赋。关闭此项以使用游戏的窗口。"
L["Install the Jiberish Fabled Icons addon to unlock more class icon styles."] = "安装 Jiberish Fabled Icons 插件以解锁更多职业图标样式。"
L["Instance"] = "副本"
L["Instance chat, used in battlegrounds and groups made by the group finder."] = "副本聊天，用于战场和通过队伍查找器组建的队伍。"
