L["Item level line"] = "物品等级行"
L["Item names beside icons"] = "图标旁显示物品名称"
L["Item names in their quality color, or all white. The icon's edge keeps the quality color."] = "物品名称使用其品质颜色，或全部为白色。图标边缘保留品质颜色。"
