L["Items below this quality don't show, like gray junk."] = "低于此品质的物品不显示，例如灰色垃圾。"
L["Items sorted into groups by type. To move an item to another group, drag it onto that group's heading or Alt-right-click it. Click a heading to collapse it. Alt-right-click also locks an item so it's never sold or disenchanted."] = "物品按类型分组。要将物品移到另一组，将其拖到该组的标题上或按Alt+右键点击。点击标题可折叠。Alt+右键点击还会锁定物品，使其永不被出售或分解。"
L["Items that are uncommon or better get a border in their quality color."] = "优秀或更高品质的物品会有其品质颜色的边框。"
L["Items you loot, create, buy or get from a quest."] = "你拾取、制造、购买或从任务获得的物品。"
L["Items your class, level or skills can't use yet, or that you already know, get a red icon, as at a vendor."] = "你的职业、等级或技能尚无法使用，或你已学会的物品，会显示红色图标，与商人处相同。"
L["Itim"] = "Itim"
L["Its buff or debuff"] = "它的增益或减益效果"
L["Its cooldown"] = "它的冷却"
L["Its options and My Journey windows, and its quest objective icons on the maps, each quest in its own color."] = "它的设置和 My Journey 窗口，以及地图上的任务目标图标，每个任务一种颜色。"
L["Its own fade, apart from the panel's. With this page open it shows a sample group."] = "有独立于面板的淡出设置。打开此页面时显示一个示例队伍。"
L["Its own window"] = "独立窗口"
L["Its own window, in the bottom-right corner to start. Move it in unlock mode (/dui unlock) and drag its corner to size it."] = "独立窗口，初始位于右下角。在解锁模式（/dui unlock）中移动它，拖动其角落调整大小。"
L["Its owner's class"] = "其主人的职业"
L["Its owner's class tells at a glance whose pet it is."] = "通过其主人的职业一眼就能看出是谁的宠物。"
L["Its timer bars in your font, bar texture and border. Sizes, colors and spots stay DBM's."] = "其计时条使用你的字体、条材质和边框。尺寸、颜色和位置保留DBM自身的设置。"
L["BigWigs and LittleWigs"] = "BigWigs和LittleWigs"
L["Their timer bars in your font, bar texture and border, on BigWigs' Default bar style. Sizes, colors and spots stay BigWigs'."] = "其计时条使用你的字体、条材质和边框（BigWigs的Default条样式下）。尺寸、颜色和位置保留BigWigs自身设置。"
L["Its window, and each attunement chain drawn like the talent trees."] = "其窗口，以及像天赋树一样绘制的每条进门任务链。"
L["Jiberish Fabled Icons is installed. Pick an icon for each class below, any style or one of its specs. The first icon on each line follows the Icon style."] = "已安装 Jiberish Fabled Icons。在下方为每个职业选择图标，可选任意样式或其专精之一。每行第一个图标遵循“图标样式”。"
L["Join a group to use the leader tools, or try them with /dui leader test."] = "加入队伍以使用领袖工具，或用 /dui leader test 试用。"
L["Join the DaylightUI Discord: press Ctrl+C to copy the link, then paste it in your browser."] = "加入DaylightUI的Discord：按Ctrl+C复制链接，然后粘贴到浏览器中。"
L["Junk"] = "垃圾"
L["Just left of the panel, level with its top, following it as the minimap or damage meter changes size. Turn it off to move the bar yourself in unlock mode."] = "位于面板左侧，与其顶部平齐，随微缩地图或伤害统计的尺寸变化而跟随。关闭此项可在解锁模式中自行移动该条。"
L["Just left of the panel, the first row resting on its bottom edge, following it as the minimap or damage meter changes size. Turn it off to move the bar yourself in unlock mode."] = "位于面板左侧，第一行紧贴其底边，随微缩地图或伤害统计的尺寸变化而跟随。关闭此项可在解锁模式中自行移动该条。"
