L["Lootable quest objects sparkle, and so do quest givers (the game has no setting for one alone). The game only sparkles with its outline around what you point at off, so this keeps that outline off. Turning this off puts the outline back; the sparkle may stay until you restart the game."] = "可拾取的任务物品会闪光，任务给予者也会（游戏没有单独设置其中之一的选项）。游戏只有在关闭你所指物体的轮廓时才会闪光，因此此项会保持轮廓关闭。关闭此项会恢复轮廓；闪光可能会保留到你重启游戏。"
