L["One color"] = "单色"
L["One color on every pip; colors shading from Combo point color to Full color along the row; your class color; or two-color pairs from the Gradients page (Combo points), one for all pips or one each. Your nameplates' combo points use the same colors."] = "每个点同一颜色；沿这一排从连击点颜色渐变到满点颜色；你的职业颜色；或渐变页面中的双色组合（连击点数），所有点共用一组或每点各一组。你的姓名板连击点数使用相同颜色。"
L["One custom color, your class color, or your class's two colors as a gradient (from the Gradients page)."] = "一种自定义颜色、你的职业颜色，或你职业的双色渐变（来自渐变页面）。"
L["One gradient (Gradients page)"] = "一组渐变（渐变页面）"
L["One more thing at the end of the same line, after the second part."] = "在同一行末尾、第二部分之后再加一项内容。"
L["One row per group member and your pet on your target's threat list, highest first, with you always in it. The percent is of the pull: at 100% it turns on you."] = "你目标的仇恨列表上每名队伍成员和你的宠物各一行，从高到低，且总包含你自己。百分比是相对于开怪阈值：到100%时它会转向你。"
L["One switch per part of the game's windows."] = "游戏窗口的每个部分各有一个开关。"
L["One tile with the count"] = "一个带计数的格子"
L["One tile: each section of the bank shows a single empty slot with the free count on it. Drop an item on it to put it there."] = "一个格子：银行的每个分区只显示一个空栏位，上面标有空余数量。把物品拖到上面即可放入。"
L["One tile: each section shows a single empty slot with the free count on it."] = "一个格子：每个分区只显示一个空栏位，上面标有空余数量。"
L["One tile: each section shows a single empty slot with the free count on it. Drop an item on it to put it there."] = "一个格子：每个分区只显示一个空栏位，上面标有空余数量。把物品拖到上面即可放入。"
L["Ones that matter in a fight"] = "战斗中重要的"
L["Online"] = "在线"
L["Only at full health"] = "仅在满生命值时"
L["Only clears this list. Moved buffs stay in their new categories."] = "只清空此列表。已移动的增益会保留在新分类中。"
L["Only debuffs I can dispel"] = "只显示我能驱散的减益"
L["Only in a group"] = "仅在队伍中"
L["Only in combat"] = "仅在战斗中"
L["Only mine"] = "只显示我的"
L["Only ones I can dispel"] = "只显示我能驱散的"
L["Only spells you cast can be bound."] = "只能绑定你施放的法术。"
L["Only the chat's messages stay over the world, each fading after a while, like Floating chat (Chat > Floating). It stays even with Fade everything at the campfire on."] = "只有聊天消息留在世界画面上，每条过一段时间后淡出，就像浮动聊天（聊天 > 浮动）。即使开启了“营火旁全部淡出”也会保留。"
L["Only the debuffs you put on it, or yours first and then everyone else's."] = "只显示你施加的减益，或先显示你的再显示其他人的。"
L["Only under a minute"] = "仅少于一分钟时"
L["Only when detached."] = "仅在分离时。"
L["Only when detached. Main hand at the bottom, the others above it."] = "仅在分离时。主手在最下方，其他在其上方。"
L["Only when detached. When attached, the bars match the cast bar's width."] = "仅在分离时。附着时，这些条与施法条宽度一致。"
L["Only when something changes"] = "仅在有变化时"
L["When not usable"] = "不可用时"
L["Only while the power bar is on its own."] = "仅在能量条独立时。"
L["Only while the power bar is on its own. When off, both ends are straight."] = "仅在能量条独立时。关闭时两端都是平直的。"
L["Only with a target"] = "仅在有目标时"
L["Only your group's leader can change the listing."] = "只有队长才能更改队伍登记。"
L["Only your group's leader can list the group."] = "只有队长才能登记队伍。"
L["Opacity"] = "不透明"
L["Opacity & fade"] = "不透明度和淡出"
L["Opacity on cooldown"] = "冷却时的不透明度"
L["Open DaylightUI options"] = "打开DaylightUI设置"
L["Open a chat box first to link it."] = "请先打开聊天输入框再链接。"
L["Open spot"] = "空位"
L["Open stat groups"] = "展开的属性分组"
L["Open this page at these settings."] = "以这些设置打开此页面。"
L["Open world only"] = "仅限野外"
L["Opening a mailbox shows DaylightUI's window: your letters, sending, and a ledger of your gold. Turn it off to use the game's window. The ledger keeps counting either way."] = "打开邮箱时显示DaylightUI的窗口：你的信件、寄信，以及金币账本。关闭后使用游戏自带窗口。账本在两种情况下都会继续记录。"
L["Opening a profession shows DaylightUI's window: your recipes on the left, the one you picked on the right. In a fight the game's own window opens. Turn it off to use the game's window."] = "打开专业时显示DaylightUI的窗口：左侧是你的配方，右侧是你选中的配方。战斗中会打开游戏自带窗口。关闭后使用游戏自带窗口。"
L["Opening a vendor sells everything in the Junk group: gray items, and anything you've moved to Junk yourself. Chat shows how much you got."] = "打开商人时出售“垃圾”分组中的所有物品：灰色物品，以及你自己移到“垃圾”中的物品。聊天中会显示获得的金额。"
L["Opening a vendor that repairs fixes all your gear, and chat shows the cost. Not in combat."] = "打开可修理的商人时修理你的所有装备，聊天中会显示花费。战斗中不会进行。"
L["Opening and closing windows: bags, character, spellbook, quest log, the game menu and DaylightUI's own windows."] = "打开和关闭窗口：背包、角色、法术书、任务日志、游戏菜单以及DaylightUI自己的窗口。"
L["Opening the group finder shows DaylightUI's window: groups to join, listing yourself, and who's about. In a fight the game's own window opens. Turn it off to use the game's window."] = "打开队伍查找器时显示DaylightUI的窗口：可加入的队伍、登记自己，以及附近的玩家。战斗中会打开游戏自带窗口。关闭后使用游戏自带窗口。"
L["Opening your bag fills up part stacks of the same item (15 and 5 Linen Cloth become 20), so no slot is wasted. Not in combat, or while you trade or have the mailbox or auction house open."] = "打开背包时会把同一物品的零散堆叠合并（15和5个亚麻布合成20个），不浪费栏位。战斗中、交易时或打开邮箱、拍卖行时不会进行。"
L["Opens the Gradients page, where the Combo points pairs are."] = "打开渐变页面，那里有连击点数的颜色组合。"
L["Opens the layout editor right on your screen: pull spells up from the tray, drag them where you want them, hook them together, click one to change it. Type /cdm to open it any time. Out of combat only."] = "直接在屏幕上打开布局编辑器：从托盘中拉出法术，拖到你想要的位置，把它们连接起来，点击一个即可更改。随时输入 /cdm 打开。仅限非战斗中。"
L["Opens your spellbook with Click-cast switched on: click a spell with the mouse button you want. Close the spellbook when you're done and this page comes back."] = "打开法术书并开启点击施法：用你想要的鼠标按键点击一个法术。完成后关闭法术书，此页面会回来。"
L["Option toggles"] = "选项开关"
L["Options"] = "设置选项"
L["Options (%s): %s"] = "设置选项（%s）：%s"
L["Options windows of addons built on Ace3, in the game's settings and their own windows: Questie, RestedXP and many more."] = "基于Ace3的插件的设置窗口，包括游戏设置中的和它们自己的窗口：Questie、RestedXP等等。"
L["Or drag the badge in Design mode."] = "或在设计模式下拖动徽章。"
