L["Press 1 to 9 to pick a line or a reward, Space for the next step (accept, continue, complete), Escape to back out. Space never jumps while you talk. Other keys still go to the game, and in combat every key is the game's."] = "按1到9选择一行或一个奖励，按空格进行下一步（接受、继续、完成），按Esc返回。交谈时空格不会跳过。其他按键仍交给游戏，战斗中所有按键都归游戏使用。"
L["Press Bind in spellbook (or open %s and switch on Click-cast at its top), then click a spell with the mouse button you want (hold Shift, Ctrl or Alt for more). That click on any of your unit frames then casts it on that unit. Close the spellbook when you're done: this page comes back. Left-click still targets and right-click opens the menu unless you bind them."] = "在法术书中按“绑定”（或打开%s并开启顶部的点击施法），然后用你想要的鼠标按键点击一个法术（按住Shift、Ctrl或Alt可绑定更多）。之后在你任意单位框体上这样点击，就会对该单位施放此法术。完成后关闭法术书：此页面会回来。除非你绑定了它们，左键点击仍会选中目标，右键点击仍会打开菜单。"
