L["Shows a grid while frames are unlocked, and snaps them to it."] = "框体解锁时显示网格，并将框体吸附到网格上。"
L["Shows a handle on every frame. Drag to move it; right-click a handle to reset that frame."] = "在每个框体上显示一个拖动点。拖动即可移动；右键点击拖动点可重置该框体。"
L["Shows a macro's name on its button. When off, macros show their icon only."] = "在按钮上显示宏的名称。关闭时宏只显示图标。"
L["Shows a sample of just this frame while you edit it, and every change as you make it. Stays on across pages until you switch it off; combat ends it."] = "编辑时只显示此框体的示例，并即时显示每处更改。切换页面后仍保持开启，直到你关闭；进入战斗会结束它。"
L["Shows a sample of the line where it sits."] = "在所在位置显示这一行的示例。"
L["Shows buffs icons on each member."] = "在每个成员上显示增益图标。"
L["Shows crowd control icons on each member."] = "在每个成员上显示控制效果图标。"
L["Shows debuffs icons on each member."] = "在每个成员上显示减益图标。"
L["Shows each button's key on the button. When off, the keys still work, you just don't see them."] = "在每个按钮上显示其按键。关闭时按键仍然有效，只是看不到。"
L["Shows each pet's health as text."] = "以文字显示每个宠物的生命值。"
L["Shows each pet's name."] = "显示每个宠物的名字。"
L["Shows only while the buff is up, like Power Word: Shield."] = "仅在增益存在时显示，比如真言术：盾。"
L["Shows or hides the row of bag buttons. Your bag keys still open your bags when it's hidden."] = "显示或隐藏一排背包按钮。隐藏时背包按键仍能打开背包。"
L["Shows or hides the row of small buttons that open your character, spellbook, talents and other windows. Their keys still work when it's hidden."] = "显示或隐藏一排打开角色、法术书、天赋等窗口的小按钮。隐藏时它们的按键仍然有效。"
L["Shows server time instead of your local time."] = "显示服务器时间而不是本地时间。"
L["Shows target, focus, pet, target of target and the party with sample units, and both cast bars mid-cast, so you can style and move them without a real target. Ends when combat starts."] = "用示例单位显示目标、焦点、宠物、目标的目标和小队，并让两个施法条都处于施法中，这样你无需真实目标也能调整外观和位置。进入战斗时结束。"
L["Shows the AFK screen now. Click or press any key to close it. Also /dui afk."] = "立即显示离开画面。点击或按任意键关闭。也可用 /dui afk。"
L["Shows the calendar and tracking buttons on the map's right edge while the mouse is over the map."] = "鼠标位于地图上时，在地图右边缘显示日历和追踪按钮。"
L["Shows the game's countdown on buttons that are on cooldown."] = "在冷却中的按钮上显示游戏自带的倒计时。"
L["Shows the game's small gold coin on gray items in the bank, like the default bags."] = "像默认背包一样，在银行中的灰色物品上显示游戏的小金币图标。"
L["Shows the game's small gold coin on gray items, like the default bags."] = "像默认背包一样，在灰色物品上显示游戏的小金币图标。"
L["Shows the healer's name next to a heal on you."] = "在你身上的治疗旁显示治疗者的名字。"
L["Shows the health text large and white in the frame's inner corner (in Ribbon, at the inner end of the row above the bar)."] = "在框体内角以白色大字显示生命值文字（缎带样式中，位于条上方那一行的内端）。"
L["Shows the unit's name on this frame."] = "在此框体上显示单位名字。"
L["Shows these raid frames in a party too, in place of the party frames."] = "在小队中也显示这些团队框体，代替小队框体。"
L["Shows this square on each member while its spell is on them."] = "当此法术作用在成员身上时，在其上显示这个方块。"
L["Shows where the range is before the enemy gets there, faintly."] = "在敌人进入范围之前，淡淡地显示范围所在。"
