L["Slot size, spacing, scale, how items are arranged, empty slots and item icon marks follow your Bags page. Turn it off to set them for the bank alone: their rows show below."] = "栏位尺寸、间距、缩放、物品排列方式、空栏位和物品图标标记都跟随你的背包页面。关闭后可单独为银行设置：相关选项会显示在下方。"
