L["Small colored squares on each member for your heals over time and shields, like Renew or Power Word: Shield. Each square shows while your spell is on them."] = "在每个成员身上显示你的持续治疗和护盾的彩色小方块，比如恢复或真言术：盾。你的法术作用在他们身上时显示对应方块。"
