L["Small tiles for a raid of up to 10: one column per group, left to right. Show, fade, textures and fonts here count for every raid size; your party has its own page."] = "最多10人团队的小格子：每个小组一列，从左到右。这里的显示、淡出、材质和字体设置适用于所有团队规模；小队有单独的页面。"
