L["The Legacy button shows DaylightUI's window: how far the next reward is, the challenges and the Legacy trees. Turn it off to use the game's window."] = "经典旧世按钮会打开DaylightUI的窗口：下一个奖励还差多少、挑战和经典旧世天赋树。关闭后使用游戏自带的窗口。"
