L["The Quests header stays when nothing is tracked, so you can see where the tracker is."] = "没有追踪任何任务时，任务标题仍会保留，让你看到追踪器的位置。"
L["The accent"] = "强调色"
L["The aggro color when Aggro color is Custom color."] = "仇恨颜色设为自定义颜色时使用的仇恨颜色。"
