L["The bank in the same look as your bags. Groups and moved items are shared with your bags."] = "与背包外观相同的银行。分组和移动过的物品与背包共享。"
L["The bar shades from dark to bright instead of one flat color. Reputation gets one per standing, editable on the Gradients page."] = "计量条由暗渐变到亮，而不是单一纯色。声望每个关系等级各有一种，可在渐变页面编辑。"
L["The bar's color for dead and offline players and tapped NPCs, and for NPCs by how they feel about you."] = "死亡和离线玩家、已被攻击的NPC，以及按对你态度区分的NPC所使用的计量条颜色。"
L["The bar's color while the cast can't be interrupted, whatever the fill style."] = "施法无法被打断时计量条的颜色，无论填充样式如何。"
L["The bar's color while the cast can't be interrupted."] = "施法无法被打断时计量条的颜色。"
L["The bars over enemies' heads: how big they are, and what they show."] = "敌人头顶的计量条：它们的大小和显示内容。"
L["The bars shade from dark to bright instead of one flat color. The color pairs are on General > Gradients."] = "计量条由暗渐变到亮，而不是单一纯色。颜色组合在综合 > 渐变中。"
L["The bars that hang off the end of the health for incoming heals and absorb shields. An overshield (a shield bigger than the health missing) follows the shield."] = "生命值末端延伸出的计量条，用于即将到来的治疗和吸收护盾。超额护盾（护盾大于已损失的生命值）会跟随护盾显示。"
L["The bars' and names' colors on every unit frame."] = "所有单位框体上计量条和名字的颜色。"
L["The bars' color when Bar color is One color."] = "计量条颜色设为单一颜色时计量条的颜色。"
L["The border color of every loot feed line while Loot feed border color is set to Custom."] = "战利品提示边框颜色设为自定义时，每条战利品提示的边框颜色。"
L["The border color when Border color is set to Your own color."] = "边框颜色设为你自己的颜色时的边框颜色。"
L["The border in the same color as the name."] = "边框与名字颜色相同。"
L["The border of a debuff you can dispel, and the raid tile's dispel icon. Debuffs already on screen change after /reload."] = "你可以驱散的减益效果的边框，以及团队格子的驱散图标。屏幕上已有的减益效果在/reload后改变。"
L["The boxes behind the experience bar, minimap and damage meter, and the meters' and threat meter's own windows. At 0 opacity the boxes disappear; the minimap and bars still show."] = "经验条、微缩地图和伤害统计后面的背景框，以及统计和威胁统计自己的窗口。不透明度为0时背景框消失；微缩地图和计量条仍会显示。"
L["The buffs wrap onto up to this many rows."] = "增益效果最多换行到这么多行。"
L["The button's border lights up while the mouse is over it."] = "鼠标悬停时按钮边框会亮起。"
L["The button's border lights up while you press it."] = "按下时按钮边框会亮起。"
L["The cast bar's color when Fill style is One color."] = "填充样式设为单一颜色时施法条的颜色。"
L["The character window and its tabs (reputation, skills, PvP, currency, statistics), inspecting others."] = "角色窗口及其标签页（声望、技能、PvP、货币、统计），以及观察他人。"
L["The chat menu, channel, voice and social buttons next to chat. When off, they're gone; their slash commands still work."] = "聊天旁边的聊天菜单、频道、语音和社交按钮。关闭后它们会消失；其斜杠命令仍然可用。"
L["The chat window's text and the chat bubbles. General uses the font on General > Appearance."] = "聊天窗口的文字和聊天泡泡。选择“综合”时使用综合 > 外观中的字体。"
L["The clock reads 18:30 instead of 6:30 PM."] = "时钟显示18:30而不是6:30 PM。"
L["The color of a Curse debuff's border and dispel icon."] = "诅咒类减益效果的边框和驱散图标颜色。"
L["The color of a Disease debuff's border and dispel icon."] = "疾病类减益效果的边框和驱散图标颜色。"
L["The color of a Magic debuff's border and dispel icon."] = "魔法类减益效果的边框和驱散图标颜色。"
L["The color of a Poison debuff's border and dispel icon."] = "中毒类减益效果的边框和驱散图标颜色。"
L["The color of the glow around your target's bar."] = "你目标计量条周围发光的颜色。"
L["The color of the last pip, or the whole row at max points, and the end of Color to full color."] = "最后一个点的颜色，或满点数时整行的颜色，也是“渐变到满点颜色”的终点颜色。"
L["The color of the names on the threat meter."] = "威胁统计上名字的颜色。"
L["The color of the names on this meter's bars."] = "此统计计量条上名字的颜色。"
L["The color of the outline around your target's bar."] = "你目标计量条周围轮廓的颜色。"
L["The color of the pull line across the threat bars."] = "威胁计量条上仇恨线的颜色。"
L["The color of the shaded spell cost on your power bar."] = "你能量条上法术消耗阴影的颜色。"
L["The color of the stretch for damage shields."] = "伤害护盾延伸部分的颜色。"
L["The color of the stretch past the health for heals on their way."] = "超出生命值的即将到来治疗延伸部分的颜色。"
L["The color the border lights up in while the mouse is over a button."] = "鼠标悬停在按钮上时边框亮起的颜色。"
L["The color the border lights up in while you press a button."] = "按下按钮时边框亮起的颜色。"
L["The color the execute range lights up in."] = "斩杀范围亮起的颜色。"
L["The color used while the menu above is set to Custom."] = "上方菜单设为自定义时使用的颜色。"
L["The colored sweep over the icon while its buff is up. When off, only the timer shows."] = "增益存在时图标上的彩色扫过效果。关闭后只显示计时。"
L["The colors below"] = "下方的颜色"
L["The colors, font and textures used everywhere. The screen changes as you pick."] = "各处使用的颜色、字体和材质。选择时画面会随之改变。"
L["The cooldown edge's color when Cooldown edge is set to Your own color."] = "冷却边缘设为你自己的颜色时冷却边缘的颜色。"
L["The cooldown layout can't be edited during combat."] = "战斗中无法编辑冷却布局。"
L["The cooldown manager's layout."] = "冷却管理器的布局。"
L["The countdown icons for your totems, above the player frame. Move them in unlock mode."] = "你图腾的倒计时图标，位于玩家框体上方。在解锁模式中移动它们。"
L["The currencies you're tracking (as the game's own backpack list shows them), with their icon and count, beside your money."] = "你正在追踪的货币（与游戏自带行囊列表中的显示一致），带有图标和数量，显示在你的金钱旁边。"
L["The dark part shrinks away instead of filling in."] = "暗色部分逐渐缩小，而不是填满。"
L["The dark ribbon behind each line. When off, only the icon and text show."] = "每行背后的暗色条带。关闭后只显示图标和文字。"
L["The data texts, and the clock and framerate on the minimap. General uses the font on General > Appearance."] = "信息文字，以及微缩地图上的时钟和帧数。选择“综合”时使用综合 > 外观中的字体。"
L["The debuffs wrap onto up to this many rows."] = "减益效果最多换行到这么多行。"
L["The dim line under each item's name. Repair warnings still show when it's off."] = "每个物品名字下方的暗色行。关闭后仍会显示修理警告。"
L["The dungeon journal, its favorites and settings windows; each dungeon's picture kept."] = "地下城手册、其收藏和设置窗口；保留每个地下城的图片。"
L["The edge round each button. A proc still lights it up."] = "每个按钮的边缘。触发时仍会亮起。"
L["The elite dragon wraps your own portrait too."] = "精英龙纹也会环绕你自己的头像。"
L["The empty bar pulses while the buff is down."] = "增益消失时空计量条会脉动。"
L["The empty part behind every bar's fill, tinted in the bar's color, except where a frame's own page picks another."] = "每个计量条填充后面的空白部分，以计量条的颜色着色，除非某个框体自己的页面另有选择。"
L["The empty part behind the bars in DaylightUI's windows. General uses the bar background above."] = "DaylightUI窗口中计量条后面的空白部分。选择“综合”时使用上方的计量条背景。"
L["The empty part of every bar in the group. A spell's own background, above, wins."] = "组内每个计量条的空白部分。法术自己的背景（上方）优先。"
L["The empty part of every health bar: a dimmed copy of the bar's own color, or one you pick."] = "每个生命条的空白部分：计量条自身颜色的暗化版本，或你选择的颜色。"
L["The empty part of the Cooldown Manager's bars, behind the fill. General uses the bar background on General > Appearance."] = "冷却管理器计量条填充后面的空白部分。选择“综合”时使用综合 > 外观中的计量条背景。"
L["The empty part of the cast bar on every nameplate, behind the fill. General uses the bar background on General > Appearance."] = "每个姓名板上施法条填充后面的空白部分。选择“综合”时使用综合 > 外观中的计量条背景。"
L["The empty part of the combo points on your target's nameplate, behind the fill. General uses the bar background on General > Appearance."] = "你目标姓名板上连击点数填充后面的空白部分。选择“综合”时使用综合 > 外观中的计量条背景。"
L["The empty part of the combo points, behind the fill. General uses the bar background on General > Appearance."] = "连击点数填充后面的空白部分。选择“综合”时使用综合 > 外观中的计量条背景。"
L["The empty part of the damage, healing and threat meters' bars, behind the fill. General uses the bar background on General > Appearance."] = "伤害、治疗和威胁统计计量条填充后面的空白部分。选择“综合”时使用综合 > 外观中的计量条背景。"
L["The empty part of the experience and reputation bar, behind the fill. General uses the bar background on General > Appearance."] = "经验和声望条填充后面的空白部分。选择“综合”时使用综合 > 外观中的计量条背景。"
L["The empty part of the health bar on every nameplate, behind the fill. General uses the bar background on General > Appearance."] = "每个姓名板上生命条填充后面的空白部分。选择“综合”时使用综合 > 外观中的计量条背景。"
L["The empty part of the health bar under a unit's tooltip, behind the fill. General uses the bar background on General > Appearance."] = "单位鼠标提示下方生命条填充后面的空白部分。选择“综合”时使用综合 > 外观中的计量条背景。"
L["The empty part of the pets' health bars, behind the fill. General uses the bar background on General > Appearance."] = "宠物生命条填充后面的空白部分。选择“综合”时使用综合 > 外观中的计量条背景。"
L["The empty part of the pets' power bars, behind the fill. General uses the bar background on General > Appearance."] = "宠物能量条填充后面的空白部分。选择“综合”时使用综合 > 外观中的计量条背景。"
L["The empty part of the progress bars in the tracker and the pop-up, behind the fill. General uses the bar background on General > Appearance."] = "追踪器和弹出框中进度条填充后面的空白部分。选择“综合”时使用综合 > 外观中的计量条背景。"
L["The empty part of the raid tiles' health bars, behind the fill. General uses the bar background on General > Appearance."] = "团队格子生命条填充后面的空白部分。选择“综合”时使用综合 > 外观中的计量条背景。"
L["The empty part of the raid tiles' power bars, behind the fill. General uses the bar background on General > Appearance."] = "团队格子能量条填充后面的空白部分。选择“综合”时使用综合 > 外观中的计量条背景。"
L["The empty part of the swing timer, behind the fill. General uses the bar background on General > Appearance."] = "攻击计时条填充后面的空白部分。选择“综合”时使用综合 > 外观中的计量条背景。"
L["The empty part of this frame's health bar, behind the fill. General uses the bar background on General > Appearance."] = "此框体生命条填充后面的空白部分。选择“综合”时使用综合 > 外观中的计量条背景。"
L["The empty part of this frame's power bar, behind the fill. General uses the bar background on General > Appearance."] = "此框体能量条填充后面的空白部分。选择“综合”时使用综合 > 外观中的计量条背景。"
L["The empty part of your cast bar, behind the fill. General uses the bar background on General > Appearance."] = "你施法条填充后面的空白部分。选择“综合”时使用综合 > 外观中的计量条背景。"
L["The empty part of your focus's cast bar, behind the fill. General uses the bar background on General > Appearance."] = "你焦点施法条填充后面的空白部分。选择“综合”时使用综合 > 外观中的计量条背景。"
L["The empty part of your target's cast bar, behind the fill. General uses the bar background on General > Appearance."] = "你目标施法条填充后面的空白部分。选择“综合”时使用综合 > 外观中的计量条背景。"
L["The empty part's color when Missing health color is Custom color."] = "损失生命值颜色设为自定义颜色时空白部分的颜色。"
L["The experience bar on top of the panel, or reputation at the level cap."] = "面板顶部的经验条，满级时显示声望。"
L["The experience bar's text and its +XP. General uses the font on General > Appearance."] = "经验条的文字及其+XP。选择“综合”时使用综合 > 外观中的字体。"
L["The experience bar, damage meter and minimap fade together (and the separate meter window, if used)."] = "经验条、伤害统计和微缩地图一起渐隐（如果使用了独立统计窗口，也包括它）。"
L["The fifth chat channel you joined, often a custom one."] = "你加入的第五个聊天频道，通常是自定义频道。"
L["The fifth pip fills in Full color (red to start with), so a full row stands out at a glance."] = "第五个点以满点颜色（默认为红色）填充，让满行一眼就能看出。"
L["The fill of every bar: health, power, cast bars, swing timers, experience, the damage meter, nameplates and more, except where a frame's own page picks another. Textures other addons share (SharedMedia) are listed after ours."] = "每个计量条的填充：生命值、能量、施法条、攻击计时条、经验、伤害统计、姓名板等，除非某个框体自己的页面另有选择。其他插件共享的材质（SharedMedia）列在我们的之后。"
L["The fill of the Cooldown Manager's bars. General uses the bar texture on General > Appearance."] = "冷却管理器计量条的填充。选择“综合”时使用综合 > 外观中的计量条材质。"
L["The fill of the bars in DaylightUI's windows: reputation, skills, professions, pet experience, quest objectives. They keep their round shape. General uses the bar texture above."] = "DaylightUI窗口中计量条的填充：声望、技能、专业、宠物经验、任务目标。它们保持圆角形状。选择“综合”时使用上方的计量条材质。"
L["The fill of the cast bar on every nameplate. General uses the bar texture on General > Appearance."] = "每个姓名板上施法条的填充。选择“综合”时使用综合 > 外观中的计量条材质。"
L["The fill of the combo points on your target's nameplate. General uses the bar texture on General > Appearance."] = "你目标姓名板上连击点数的填充。选择“综合”时使用综合 > 外观中的计量条材质。"
L["The fill of the combo points. General uses the bar texture on General > Appearance."] = "连击点数的填充。选择“综合”时使用综合 > 外观中的计量条材质。"
L["The fill of the damage, healing and threat meters' bars. General uses the bar texture on General > Appearance."] = "伤害、治疗和威胁统计计量条的填充。选择“综合”时使用综合 > 外观中的计量条材质。"
L["The fill of the experience and reputation bar. General uses the bar texture on General > Appearance."] = "经验和声望条的填充。选择“综合”时使用综合 > 外观中的计量条材质。"
L["The fill of the health bar on every nameplate. General uses the bar texture on General > Appearance."] = "每个姓名板上生命条的填充。选择“综合”时使用综合 > 外观中的计量条材质。"
L["The fill of the health bar under a unit's tooltip. General uses the bar texture on General > Appearance."] = "单位鼠标提示下方生命条的填充。选择“综合”时使用综合 > 外观中的计量条材质。"
L["The fill of the pets' health bars. General uses the bar texture on General > Appearance."] = "宠物生命条的填充。选择“综合”时使用综合 > 外观中的计量条材质。"
L["The fill of the pets' power bars. General uses the bar texture on General > Appearance."] = "宠物能量条的填充。选择“综合”时使用综合 > 外观中的计量条材质。"
L["The fill of the progress bars in the tracker and the pop-up. General uses the bar texture on General > Appearance."] = "追踪器和弹出框中进度条的填充。选择“综合”时使用综合 > 外观中的计量条材质。"
L["The fill of the raid tiles' health bars. General uses the bar texture on General > Appearance."] = "团队格子生命条的填充。选择“综合”时使用综合 > 外观中的计量条材质。"
L["The fill of the raid tiles' power bars. General uses the bar texture on General > Appearance."] = "团队格子能量条的填充。选择“综合”时使用综合 > 外观中的计量条材质。"
L["The fill of the swing timer. General uses the bar texture on General > Appearance."] = "攻击计时条的填充。选择“综合”时使用综合 > 外观中的计量条材质。"
L["The fill of this frame's health bar. General uses the bar texture on General > Appearance."] = "此框体生命条的填充。选择“综合”时使用综合 > 外观中的计量条材质。"
L["The fill of this frame's power bar. General uses the bar texture on General > Appearance."] = "此框体能量条的填充。选择“综合”时使用综合 > 外观中的计量条材质。"
L["The fill of your cast bar. General uses the bar texture on General > Appearance."] = "你施法条的填充。选择“综合”时使用综合 > 外观中的计量条材质。"
L["The fill of your focus's cast bar. General uses the bar texture on General > Appearance."] = "你焦点施法条的填充。选择“综合”时使用综合 > 外观中的计量条材质。"
L["The fill of your target's cast bar. General uses the bar texture on General > Appearance."] = "你目标施法条的填充。选择“综合”时使用综合 > 外观中的计量条材质。"
L["The font above shows everywhere at once, except where a frame's own page or the window font below picks another. This puts every one of those back on the font above."] = "上方字体会同时显示在所有地方，除非某个框体自己的页面或下方的窗口字体另有选择。此操作会将这些全部恢复为上方字体。"
L["The friendly health bar's color when Bar color is One color."] = "计量条颜色设为单一颜色时友方生命条的颜色。"
L["A marker over the quest you picked and breadcrumbs on the ground leading to it. With the QuestieDB addon, an arrow to the nearest objective too."] = "在你选中的任务上方显示标记，并在地面上留下通往它的路径点。装有QuestieDB插件时，还有指向最近任务目标的箭头。"
L["The game menu, addon list, macros, clock, loot, socketing, upgrading, the scrapper, the auction house, the world map's frame, the breath bar."] = "游戏菜单、插件列表、宏命令、时钟、战利品、镶嵌、升级、拆解机、拍卖行、世界地图边框、呼吸条。"
L["The game only reports range for your group; anyone else stays at full opacity."] = "游戏只报告你队伍成员的距离；其他人保持完全不透明。"
L["The game shows it as a bar."] = "游戏将其显示为计量条。"
L["The game shows it as an icon."] = "游戏将其显示为图标。"
L["The game's chat in the DaylightUI look, in the bottom-left corner. Chat itself works as normal."] = "DaylightUI外观的游戏聊天，位于左下角。聊天本身照常工作。"
L["The game's new-player tips (the game setting 'Tutorials'). When off, they're turned off."] = "游戏的新手提示（游戏设置“教程”）。关闭后它们会被关掉。"
L["The game's numbers that pop off what you hit, and the scrolling combat text over you."] = "从你击中的目标身上弹出的游戏数字，以及你头顶的滚动战斗信息。"
L["The game's own"] = "游戏自带"
L["The game's own buff frames show beside DaylightUI's bars. When off, our bars replace them (they still show while Edit Mode is open)."] = "游戏自带的增益框体显示在DaylightUI的计量条旁边。关闭后由我们的计量条取代它们（编辑模式打开时仍会显示）。"
L["The game's own messages: logins, /played, errors and the like."] = "游戏自己的信息：登录、/played、错误之类。"
L["The game's own setting: a quest you accept goes straight into the tracker."] = "游戏自带设置：你接受的任务会直接加入追踪器。"
L["The game's own setting: the map turns with you, so the way you face is always up. When off, north is always up."] = "游戏自带设置：地图随你转动，你面朝的方向始终朝上。关闭后北方始终朝上。"
L["The game's own settings for how the numbers leave the target."] = "游戏自带的数字离开目标方式的设置。"
L["The game's own switches."] = "游戏自带的开关。"
L["The game's own windows in DaylightUI style: the info panel's background, DaylightUI borders, font, controls and scroll bars."] = "DaylightUI风格的游戏窗口：信息面板的背景、DaylightUI边框、字体、控件和滚动条。"
L["The game's own windows in the DaylightUI look."] = "DaylightUI外观的游戏窗口。"
L["The game's quest tracker, placed under the panel."] = "游戏的任务追踪器，放在面板下方。"
L["The game's scrolling text over your own character: hits you take, heals, procs and more."] = "你自己角色头顶的游戏滚动文字：你受到的攻击、治疗、触发等。"
L["The game's tooltips in the DaylightUI look."] = "DaylightUI外观的游戏鼠标提示。"
L["The game's tooltips."] = "游戏的鼠标提示。"
L["The gap between buff icons."] = "增益图标之间的间距。"
L["The gap between combo point pips."] = "连击点数之间的间距。"
L["The gap between combo points."] = "连击点数之间的间距。"
L["The gap between debuff icons."] = "减益图标之间的间距。"
L["The gap between icons."] = "图标之间的间距。"
L["The gap between lines, when there's more than one."] = "多于一行时行与行之间的间距。"
L["The gap between one party frame and the next."] = "小队框体之间的间距。"
L["The gap between this bar's buttons."] = "此动作条按钮之间的间距。"
L["The gap between this bar's icons."] = "此计量条图标之间的间距。"
L["The glow behind your character in this color."] = "你角色身后的此颜色光晕。"
L["The glowing border on a button when its spell procs."] = "法术触发时按钮上的发光边框。"
L["The gold at the bottom of the bag counts up or down to its new amount. Needs Motion effects (General > Appearance)."] = "背包底部的金币会递增或递减到新数额。需要动态效果（综合 > 外观）。"
L["The green numbers over who you heal."] = "你治疗的目标头顶的绿色数字。"
L["The guide that set this character up: a quick setup, a tour of everything DaylightUI does, or another profile."] = "为此角色进行设置的向导：快速设置、DaylightUI全部功能导览，或另一个配置。"
L["The guide window (old and new), its steps and its item and target boxes."] = "任务指引窗口（新旧版本）、其步骤及其物品和目标框。"
L["The hand and time on each bar. Attached under the cast bar, it's kept small enough for the bar."] = "每个计量条上的指针和时间。附在施法条下方时，会保持足够小以适应计量条。"
L["The health and level numbers on the nameplates. General uses the font on General > Appearance."] = "姓名板上的生命值和等级数字。选择“综合”时使用综合 > 外观中的字体。"
L["The health bar fills bottom to top instead of across."] = "生命条由下向上填充，而不是横向。"
L["The health bar fills from the opposite side."] = "生命条从另一侧开始填充。"
L["The health bar's color for a dead unit."] = "死亡单位的生命条颜色。"
L["The health bar's color for a friendly NPC."] = "友方NPC的生命条颜色。"
L["The health bar's color for a player who went offline."] = "已离线玩家的生命条颜色。"
L["The health bar's color for an NPC someone else tagged first."] = "被他人先攻击的NPC的生命条颜色。"
L["The health bar's color for an NPC that attacks you."] = "会攻击你的NPC的生命条颜色。"
L["The health bar's color for an NPC that leaves you alone until you hit it."] = "你不攻击就不会主动攻击你的NPC的生命条颜色。"
L["The health bar's color when Health bar color is One color."] = "生命条颜色设为单一颜色时生命条的颜色。"
L["The health text shows at full health too. When off, it disappears while the unit is at full."] = "满生命值时也显示生命值文字。关闭后单位满血时文字消失。"
L["The health text's color when Health text color is Custom."] = "生命值文字颜色设为自定义时生命值文字的颜色。"
L["The highest rank"] = "最高等级"
L["The highlight color: Daylight's own quiet tone, the Daylight gradient, your class's color or its gradient (from the Gradients page), or one of your own."] = "高亮颜色：Daylight自己的柔和色调、Daylight渐变、你的职业颜色或其渐变（来自渐变页面），或你自己的颜色。"
L["The highlight's color when Active spell is set to Your own color."] = "当前法术设为你自己的颜色时高亮的颜色。"
L["The icon of the quest the minimap arrow points to (click a quest's icon to pick it), and the light behind an icon under the mouse."] = "微缩地图箭头指向的任务图标（点击任务图标来选择），以及鼠标下图标背后的光。"
L["The info panel, meter, map and tracker."] = "信息面板、统计、地图和追踪器。"
L["The item level at the bottom in your gear's quality color, durability green to yellow to red. When off, both are plain gray."] = "底部的物品等级以你装备的品质颜色显示，耐久度由绿到黄到红。关闭后两者都显示为普通颜色。"
L["The item level of weapons and armor in the bank, in the bottom left corner."] = "银行中武器和护甲的物品等级，显示在左下角。"
L["The item level of weapons and armor in the bottom left corner."] = "武器和护甲的物品等级，显示在左下角。"
L["The kobolds in the mine carry candles on their heads to see in the dark. Bring me eight of them and I'll make it worth your while."] = "矿洞里的狗头人头上顶着蜡烛在黑暗中照明。给我带八根来，我不会亏待你的。"
L["The leader tools are off: Unit Frames > Raid > Leader tools."] = "团队领袖工具已关闭：单位框体 > 团队 > 领袖工具。"
L["The leader tools open after the fight."] = "领袖工具将在战斗后打开。"
L["The leader tools sit beside Daylight UI's party or raid frames, which are off."] = "领袖工具位于Daylight UI的小队或团队框体旁边，而它们已关闭。"
L["The leader's crown stays in a fight. When off, it hides while you're fighting."] = "战斗中保留领袖皇冠。关闭后战斗时隐藏。"
L["The line under the open tab at the top (Character, Reputation, Skills...)."] = "顶部当前标签页下方的线（角色、声望、技能……）。"
L["The line under the open tab in this color."] = "当前标签页下方此颜色的线。"
L["The line where the range starts. 0 hides it."] = "范围开始处的线。0为隐藏。"
L["The lines in the middle of the screen (interrupted, bags full, a new area found) in your font, errors in a soft red, easing in and out. Move them with /dui unlock. Turn it off to see the game's own red and yellow text."] = "屏幕中央的信息（被打断、背包已满、发现新区域）使用你的字体，错误显示为柔和的红色，渐入渐出。用/dui unlock移动它们。关闭后显示游戏自带的红色和黄色文字。"
L["The lines under the headers in this color."] = "标题下方此颜色的线。"
L["The list grows up from its handle instead of down. For a tracker placed low on the screen."] = "列表从其把手向上增长，而不是向下。适合放在屏幕下方的追踪器。"
L["The look shared by everything DaylightUI draws."] = "DaylightUI绘制的所有内容共享的外观。"
L["The loot browser's window, its lists, buttons and dialogs; its icons and maps kept."] = "战利品浏览器的窗口、列表、按钮和对话框；保留其图标和地图。"
L["The loot window's spot is kept by the game's Edit Mode, and you're on an Edit Mode layout of your own: move it there (Esc > Edit Mode)."] = "战利品窗口的位置由游戏的编辑模式保存，而你正在使用自己的编辑模式布局：请在那里移动它（Esc > 编辑模式）。"
L["The lower ranks of each spell sit under the highest, so you can cast an older rank for less mana. When off, the spellbook lists only the highest rank. The spellbook page has the same switch (Hide ranks)."] = "每个法术的低等级排在最高等级下方，这样你可以施放旧等级来节省法力。关闭后法术书只列出最高等级。法术书页面也有同样的开关（隐藏等级）。"
L["The main hand bar's color."] = "主手计量条的颜色。"
L["The mark shows what the quest wants from it, the way the map does: a sword to kill, a bag to loot, a cog to use, an eye to explore, in the quest's color. Needs the Quests module; without it, the !."] = "标记会像地图一样显示任务需要什么：剑表示击杀，袋子表示拾取，齿轮表示使用，眼睛表示探索，使用任务的颜色。需要任务模块；没有它时显示!。"
L["The marker and the arrow fade back while you're in combat, so they're never in the way."] = "战斗中标记和箭头会淡出，绝不碍事。"
L["The marker in the world that leads you to your quest."] = "世界中引导你前往任务的标记。"
L["The marker over the spot of the quest you picked (click its icon in the tracker) in DaylightUI style, with the distance. It fades away once you're in the quest's area on the map. Turn it off to see the game's own marker."] = "你选中的任务（在追踪器中点击其图标）地点上方的DaylightUI风格标记，带有距离。进入地图上的任务区域后会淡出。关闭后显示游戏自带的标记。"
L["The melee bars' color while Heroic Strike, Cleave or Maul waits for your next swing."] = "英勇打击、顺劈斩或槌击等待你下一次挥击时近战计量条的颜色。"
L["The meter hides while you play solo."] = "单人游戏时隐藏统计。"
L["The most buff icons at once."] = "同时显示的增益图标上限。"
L["The most buffs you can purge or steal one plate shows."] = "一个姓名板显示的可净化或偷取增益的上限。"
L["The most debuff icons at once."] = "同时显示的减益图标上限。"
L["The most debuffs from other players, shown after yours. Only with Mine first, then others."] = "其他玩家施放的减益效果上限，显示在你的之后。仅限“我的优先，然后其他”。"
L["The most group members the threat meter lists at once, under the damage meter."] = "伤害统计下方威胁统计同时列出的队伍成员上限。"
L["The most group members the threat meter lists at once."] = "威胁统计同时列出的队伍成员上限。"
L["The most icons this group shows at once."] = "此组同时显示的图标上限。"
L["The most of your buffs one friendly plate shows."] = "一个友方姓名板显示你的增益效果的上限。"
L["The most of your debuffs one plate shows."] = "一个姓名板显示你的减益效果的上限。"
L["The most of your own debuffs shown at once."] = "同时显示你自己减益效果的上限。"
L["The mouseover border's color when Mouseover border color is set to Your own color."] = "鼠标悬停边框颜色设为你自己的颜色时悬停边框的颜色。"
L["The name floats above the bar, at its outer end. Long names are cut short."] = "名字悬浮在计量条上方的外侧末端。过长的名字会被截断。"
L["The name of a buff or debuff as it lands on you."] = "增益或减益效果作用在你身上时的名称。"
L["The name sits in a small tab above the frame. Long names are cut short."] = "名字位于框体上方的小标签中。过长的名字会被截断。"
L["The name's color when Name color is Custom."] = "名字颜色设为自定义时名字的颜色。"
L["The names on every unit frame, unless a frame picks its own. Class and reaction: players by class color, others by friendly, neutral or hostile."] = "所有单位框体上的名字，除非某个框体另有选择。职业和阵营关系：玩家按职业颜色，其他按友方、中立或敌对。"
L["The names' color when Name color is Custom."] = "名字颜色设为自定义时名字的颜色。"
L["The newest first. Click one to move it again."] = "最新的在前。点击一个可再次移动它。"
L["The note box shows after the fight."] = "备注框将在战斗后显示。"
L["The number on an icon showing how many stacks it has."] = "图标上显示其层数的数字。"
L["The numbers change color for the last seconds of the cooldown."] = "冷却最后几秒时数字会变色。"
L["The numbers in objectives, like 3/8."] = "任务目标中的数字，例如3/8。"
L["The numbers on the bar, e.g. 1,200 / 5,000 (+800), where +800 is your rested XP."] = "计量条上的数字，例如1,200 / 5,000 (+800)，其中+800是你的精力充沛经验值。"
L["The numbers over what you hit."] = "你击中目标头顶的数字。"
L["The off hand bar's color."] = "副手计量条的颜色。"
L["The outline every button is cut to. The icon, border and cooldown shade all follow it."] = "每个按钮被裁切成的轮廓。图标、边框和冷却阴影都会跟随它。"
L["The outline or glow in your accent color (Appearance), following it when it changes. When off, uses the colors below."] = "使用你强调色（外观）的轮廓或发光，强调色改变时随之改变。关闭后使用下方的颜色。"
L["The outline's color when Target outline color is Custom color."] = "目标轮廓颜色设为自定义颜色时轮廓的颜色。"
L["The panel behind the chat, with its border. When off, only the chat text shows."] = "聊天背后的面板及其边框。关闭后只显示聊天文字。"
L["The panel's framed box behind the list, as tall as what's shown."] = "列表背后面板的边框盒，高度与显示内容一致。"
L["The pet's health bar takes the mood color instead: red unhappy, yellow content, green happy. Turn the square off to have only this."] = "宠物生命条改为显示心情颜色：红色为不高兴，黄色为满足，绿色为高兴。关闭方块即可只保留这一项。"
L["The pets' health text. General uses the font on General > Appearance."] = "宠物的生命值文字。选择“综合”时使用综合 > 外观中的字体。"
L["The pets' names. General uses the font on General > Appearance."] = "宠物的名字。选择“综合”时使用综合 > 外观中的字体。"
L["The piece of the bar you just earned flashes and \"+XP\" rises; a sweep on a level up. Needs Motion effects (General > Appearance)."] = "刚获得的那段计量条会闪烁，并升起“+XP”；升级时有扫光效果。需要动态效果（综合 > 外观）。"
L["The pips widen to span the whole frame, so the row reads like a bar."] = "点会加宽以横跨整个框体，让这一行看起来像计量条。"
L["The pips' color with One color, or the color they start from with Color to full color."] = "单一颜色时点的颜色，或“渐变到满点颜色”时的起始颜色。"
L["The players who keep DaylightUI going. Thank you."] = "让DaylightUI持续前进的玩家们。谢谢你们。"
L["The power bar's color when Power bar color is One color."] = "能量条颜色设为单一颜色时能量条的颜色。"
L["The power text shows while mana, rage or energy is full too. When off, it disappears at full."] = "法力值、怒气或能量满时也显示能量文字。关闭后满时消失。"
L["The pressed border's color when Pressed border color is set to Your own color."] = "按下边框颜色设为你自己的颜色时按下边框的颜色。"
L["The priority quest's color while Priority quest color is set to Custom."] = "优先任务颜色设为自定义时优先任务的颜色。"
L["The proc border's color when Proc border is set to Your own color."] = "触发边框设为你自己的颜色时触发边框的颜色。"
L["The profile %s is ready. Choose it for this character (or a talent set) to use it."] = "配置%s已就绪。为此角色（或某个天赋组）选择它即可使用。"
L["The profile %s: its settings, frame positions and Edit Mode layout. Ctrl+C to copy, then share it."] = "配置%s：其设置、框体位置和编辑模式布局。按Ctrl+C复制，然后分享。"
L["The profile for your first talent set. Changing it asks to reload."] = "你第一个天赋组的配置。更改时会要求重载。"
L["The profile for your second talent set; swapping talents asks to switch."] = "你第二个天赋组的配置；切换天赋时会询问是否切换。"
L["The profile in use as text to copy and share."] = "当前使用的配置，以文本形式复制和分享。"
L["The profile is ready. Reload to use it."] = "配置已就绪。重载即可使用。"
L["The profile is used as it is; nothing in it changes."] = "配置按原样使用；其中任何内容都不会改变。"
L["The profile this character uses. Changing it asks to reload."] = "此角色使用的配置。更改时会要求重载。"
L["The profile's Edit Mode layout will be set after the reload (%s)."] = "配置的编辑模式布局将在重载后设置（%s）。"
L["The progress bars' color while Progress bar color is set to Custom."] = "进度条颜色设为自定义时进度条的颜色。"
L["The quest log on the world map."] = "世界地图上的任务日志。"
L["The quest under the mouse stays bright, the others ease dimmer."] = "鼠标下的任务保持明亮，其他任务逐渐变暗。"
L["The raid frames for 11 to 20 players. Show, fade, textures and fonts are on the Raid 10 page."] = "11至20人的团队框体。显示、渐隐、材质和字体在团队10页面中。"
L["The raid frames for 21 to 40 players. Show, fade, textures and fonts are on the Raid 10 page."] = "21至40人的团队框体。显示、渐隐、材质和字体在团队10页面中。"
L["The raid tiles' health text. General uses the font on General > Appearance."] = "团队格子的生命值文字。选择“综合”时使用综合 > 外观中的字体。"
L["The raid tiles' names. General uses the font on General > Appearance."] = "团队格子的名字。选择“综合”时使用综合 > 外观中的字体。"
L["The raid tiles' own name color. Same as the Colors page follows the name color every frame shares."] = "团队格子自己的名字颜色。“与颜色页面相同”会跟随所有框体共享的名字颜色。"
L["The ranged bar shows how far your target is instead of its name: Melee, Dead zone, 10 to 35 yd, Max range or Out of range."] = "远程计量条显示你目标的距离而不是名字：近战、死区、10至35码、最大距离或超出范围。"
L["The ranged bar's color."] = "远程计量条的颜色。"
L["The red of a ring, name tab or raid tile while something is attacking the unit, or a color you pick."] = "有东西攻击该单位时环、名字标签或团队格子的红色，或你选择的颜色。"
L["The ring (or name tab, or raid tile) that turns red while something is attacking the unit; an elite's dragon keeps its color, its eyes catch fire."] = "有东西攻击该单位时变红的环（或名字标签、团队格子）；精英的龙纹保持原色，其眼睛会燃起火焰。"
L["The role icon stays in a fight. When off, it hides while you're fighting."] = "战斗中保留职责图标。关闭后战斗时隐藏。"
L["The row above the bar that holds the name and the health number."] = "计量条上方放置名字和生命值数字的一行。"
L["The same click again removes it."] = "再次同样点击即可移除。"
L["The same colors as in the game's chat settings: a change shows in every chat tab."] = "与游戏聊天设置中的颜色相同：更改会显示在每个聊天标签页中。"
L["The same size as the top-right panel with its damage meter out."] = "与右上面板（伤害统计移出后）尺寸相同。"
L["The search failed. Try Refresh."] = "搜索失败。请尝试刷新。"
L["The shade over the health your damage over time spells will still take, on the target and on enemy nameplates."] = "你的持续伤害法术仍将造成的生命值部分上的阴影，显示在目标和敌方姓名板上。"
L["The shade that sweeps over a button while it's on cooldown."] = "按钮冷却时扫过的阴影。"
L["The size of the entrance, flight master, boat and zeppelin symbols on the world map. They keep this size as you zoom."] = "世界地图上入口、飞行管理员、船只和飞艇符号的尺寸。缩放地图时保持这个尺寸。"
L["The skull, star and other raid markers just left of the bar."] = "计量条左侧的骷髅、星星等团队标记。"
L["The slim health bar. The name, the health number and the power line sit outside it."] = "纤细的生命条。名字、生命值数字和能量线位于其外侧。"
L["The small tab on the meter's left edge (it shows while the mouse is near) slides it out or back by hand."] = "统计左边缘的小标签（鼠标靠近时显示），可手动将其滑出或收回。"
L["The small tab that holds the name above the frame: its own border, corners, shadow, place and width."] = "框体上方放置名字的小标签：其自己的边框、圆角、阴影、位置和宽度。"
L["The small zone names over each group of quests."] = "每组任务上方的小地区名。"
L["The soft light behind the model on the Character page."] = "角色页面中模型背后的柔光。"
L["The soft light behind the model on the Character page. When off, only the window's background shows."] = "角色页面中模型背后的柔光。关闭后只显示窗口背景。"
L["The sound when someone whispers you. The first five are gentle chimes made for DaylightUI; picking one plays it once."] = "有人对你发送悄悄话时的声音。前五种是为DaylightUI制作的柔和铃声；选择一种会播放一次。"
L["The space between the health bar and the power line under it."] = "生命条与其下方能量线之间的间距。"
L["The spell an enemy is casting, under its health bar."] = "敌人正在施放的法术，位于其生命条下方。"
L["The spell being cast, as a small icon left of the cast bar."] = "正在施放的法术，作为小图标显示在施法条左侧。"
L["The spell name and time on the cast bars. General uses the font on General > Appearance."] = "施法条上的法术名和时间。选择“综合”时使用综合 > 外观中的字体。"
L["The spell name and time on your cast bar."] = "你施法条上的法术名和时间。"
L["The spell name and time on your cast bar. General uses the font on General > Appearance."] = "你施法条上的法术名和时间。选择“综合”时使用综合 > 外观中的字体。"
L["The spell name and time on your focus's cast bar. General uses the font on General > Appearance."] = "你焦点施法条上的法术名和时间。选择“综合”时使用综合 > 外观中的字体。"
L["The spell name and time on your focus's cast bar. Inside the frame it's kept small enough for the power bar."] = "你焦点施法条上的法术名和时间。在框体内时会保持足够小以适应能量条。"
L["The spell name and time on your target's cast bar. General uses the font on General > Appearance."] = "你目标施法条上的法术名和时间。选择“综合”时使用综合 > 外观中的字体。"
L["The spell name and time on your target's cast bar. Inside the frame it's kept small enough for the power bar, unless Text size inside the frame is set."] = "你目标施法条上的法术名和时间。在框体内时会保持足够小以适应能量条，除非设置了框体内文字大小。"
L["The spell name and timer on the target's cast bar."] = "目标施法条上的法术名和计时。"
L["The spell name and timer while the bar sits inside the target frame, even past the power bar's height. 0 uses Target cast bar text size, kept small enough for the power bar."] = "计量条位于目标框体内时的法术名和计时，可超过能量条高度。0为使用目标施法条文字大小，并保持足够小以适应能量条。"
L["The spell's icon at the end of your focus's cast bar. Not while it sits inside the frame."] = "你焦点施法条末端的法术图标。在框体内时不显示。"
L["The spell's icon at the end of your target's cast bar. Not while it sits inside the frame."] = "你目标施法条末端的法术图标。在框体内时不显示。"
L["The spell's name on every cast bar."] = "每个施法条上的法术名。"
L["The spell's own"] = "法术自带"
L["The spell's own color (Renew green, a shield blue), or one you pick."] = "法术自己的颜色（恢复为绿色，护盾为蓝色），或你选择的颜色。"
L["The spellbook and talent keys open DaylightUI's window. In a fight the game's own book opens, so you can still drag spells to your bars. Turn it off to always use the game's window."] = "法术书和天赋按键会打开DaylightUI的窗口。战斗中会打开游戏自带的法术书，这样你仍能将法术拖到动作条上。关闭后始终使用游戏的窗口。"
L["The spellbook and talents, the profession windows, the professions book, the stable."] = "法术书和天赋、专业窗口、专业书、兽栏。"
L["The square minimap in the panel."] = "面板中的方形微缩地图。"
L["The square's color when Heal indicator color is Custom color."] = "治疗指示颜色设为自定义颜色时方块的颜色。"
L["The stat group headers and the headers on the other pages. Each its own: a color per stat group, used in turn on the other pages."] = "属性组标题以及其他页面上的标题。各有各的：每个属性组一种颜色，在其他页面上轮流使用。"
L["The sweep can't start in combat."] = "战斗中无法开始扫光。"
L["The swing timer's hand and time. General uses the font on General > Appearance."] = "攻击计时条的指针和时间。选择“综合”时使用综合 > 外观中的字体。"
L["The tag after a PvP quest's title."] = "PvP任务标题后的标签。"
L["The tag after a dungeon quest's title."] = "地下城任务标题后的标签。"
L["The tag after a raid quest's title."] = "团队任务标题后的标签。"
L["The tag after an elite quest's title."] = "精英任务标题后的标签。"
L["The talents you're using now."] = "你当前使用的天赋。"
L["The target and focus cast bars' color for a moment after their cast is interrupted."] = "目标和焦点施法被打断后片刻内施法条的颜色。"
L["The target and focus cast bars' color while they cast."] = "目标和焦点施法时施法条的颜色。"
L["The target and focus cast bars' color while they channel."] = "目标和焦点引导时施法条的颜色。"
L["The target's and target of target's class and power gradients run the other way, so they mirror yours. Only for a horizontal gradient."] = "目标和目标的目标的职业与能量渐变反向延伸，与你的形成镜像。仅适用于水平渐变。"
L["The text in DaylightUI's windows (character, spellbook, professions, bags, quest journal) and the game's windows it restyles. General uses the font above."] = "DaylightUI窗口（角色、法术书、专业、背包、任务日志）以及它重新设计的游戏窗口中的文字。选择“综合”时使用上方字体。"
L["The textures above show on every bar at once, except where a frame's own page or the window bars below pick another. This puts every one of those back on the textures above."] = "上方材质会同时显示在所有计量条上，除非某个框体自己的页面或下方的窗口计量条另有选择。此操作会将这些全部恢复为上方材质。"
L["The thin line under each header. Like the tab underline: whatever Tab underline below is set to. Class gradient uses your class's colors from the Gradients page."] = "每个标题下方的细线。与标签页下划线一样：跟随下方标签页下划线的设置。职业渐变使用渐变页面中你职业的颜色。"
L["The thin power bar under the health bar."] = "生命条下方的细能量条。"
L["The thin strip under the minimap with gold, gear, bag space and more."] = "微缩地图下方的细条，显示金币、装备、背包空间等。"
L["The threat bars' color when Bar color is One color."] = "计量条颜色设为单一颜色时威胁计量条的颜色。"
L["The threat colors slowly brighten and dim, quicker when a mob is about to switch. Needs the health bar, border or glow above."] = "威胁颜色缓慢明暗变化，怪物即将转换目标时更快。需要上方的生命条、边框或发光。"
L["The tick next to a finished objective."] = "已完成任务目标旁的勾。"
L["The time at the bottom of the minimap."] = "微缩地图底部的时间。"
L["The time before each message (the game's own setting)."] = "每条信息前的时间（游戏自带设置）。"
L["The time left as a number on each icon."] = "每个图标上以数字显示的剩余时间。"
L["The time left on a timed quest once it's under a minute."] = "限时任务不足一分钟时的剩余时间。"
L["The time left on a timed quest."] = "限时任务的剩余时间。"
L["The time on every cast bar: what's left, what's left out of the whole cast, or nothing."] = "每个施法条上的时间：剩余时间、剩余/总时间，或不显示。"
L["The tint on a button while your target is out of range, when Out of range is set to Tint the icon."] = "你的目标超出范围且超出范围设为图标着色时按钮上的着色。"
L["The tooltip text; titles are a little larger."] = "鼠标提示文字；标题稍大一些。"
L["The top-right panel: experience bar on top, damage meter and minimap below. Move it in unlock mode."] = "右上面板：顶部是经验条，下方是伤害统计和微缩地图。在解锁模式中移动它。"
L["The two ends of the bar's gradient. With Gradient off, the bar takes the bright end."] = "计量条渐变的两端。关闭渐变时计量条使用亮的一端。"
L["The two-color fills bars use when set to a gradient (Class gradient on unit frames and nameplates, power bars)."] = "计量条设为渐变时使用的双色填充（单位框体和姓名板上的职业渐变、能量条）。"
L["The unit you set as focus."] = "你设为焦点的单位。"
L["The unit's health as text at the right end of the bar. Pick the format under Health text."] = "单位的生命值以文字显示在计量条右端。在生命值文字下选择格式。"
L["The unit's health written on this frame."] = "在此框体上显示的单位生命值。"
L["The unit's level at the left end of the bar, in the game's difficulty color; ?? for one far above you, + for an elite."] = "单位的等级显示在计量条左端，使用游戏的难度颜色；远高于你的显示??，精英显示+。"
L["The whole Bank and alts window, slots, text and buttons together."] = "整个银行和小号窗口，栏位、文字和按钮一起。"
L["The whole bag window, slots, text and buttons together."] = "整个背包窗口，栏位、文字和按钮一起。"
L["The whole bank window, slots, text and buttons together."] = "整个银行窗口，栏位、文字和按钮一起。"
L["The whole bar, icons, text and background together."] = "整个计量条，图标、文字和背景一起。"
L["The whole feed. Also the mouse wheel over its handle in /dui unlock."] = "整个提示列表。也可在/dui unlock中对其把手滚动鼠标滚轮。"
L["The whole group shows only during a fight."] = "整组仅在战斗中显示。"
L["The whole group shows only in a party or raid."] = "整组仅在小队或团队中显示。"
L["The whole pop-up, text and bar together."] = "整个弹出框，文字和计量条一起。"
L["The window's title shows the player's last name after their first name."] = "窗口标题在玩家的名字后显示其姓氏。"
L["The world map's quest list and quest pages in DaylightUI style, with Track, Share and Abandon on each quest. Turn it off to use the game's own."] = "DaylightUI风格的世界地图任务列表和任务页面，每个任务都有追踪、分享和放弃。关闭后使用游戏自带的。"
L["The zone or area you're in, at the top of the map (above the coordinates)."] = "你所在的地区或区域，显示在地图顶部（坐标上方）。"
L["The zone or area you're in, at the top of the minimap."] = "你所在的地区或区域，显示在微缩地图顶部。"
L["Their health as text at the right end of the bar."] = "他们的生命值以文字显示在计量条右端。"
L["Their keybinds work even when hidden. Move them in unlock mode."] = "隐藏时它们的快捷键依然有效。在解锁模式中移动它们。"
L["Their level at the left end of the bar."] = "他们的等级显示在计量条左端。"
L["These are for talent set %s; each talent set keeps its own."] = "这些属于天赋组%s；每个天赋组各自保存。"
L["These talents use the profile %s. Switch to it?"] = "这些天赋使用配置%s。切换到它吗？"
L["Thick"] = "粗"
L["Thin"] = "纤细"
L["Thin lines split the bar into 20 parts, like the classic bar: each one is 5% of a level."] = "细线将计量条分成20段，就像经典计量条：每段是一级的5%。"
L["This Legacy tree isn't available yet."] = "此经典旧世天赋树暂不可用。"
L["This bar's own name size. Text size, under Whole group, sizes every bar's."] = "此计量条自己的名字尺寸。整组下的文本大小设置所有计量条的。"
L["This character"] = "此角色"
L["This character hasn't finished the setup guide, so moved frames go back when you log out. Type /dui install to finish it."] = "此角色尚未完成设置向导，因此登出后移动过的框体会恢复原位。输入/dui install完成它。"
L["This character hasn't finished the setup guide, so what you change or move is lost when you log out. Finish the guide first, then make your changes."] = "此角色尚未完成设置向导，因此登出后你的更改或移动都会丢失。请先完成向导，再进行更改。"
L["This character's, for the talent set in use. Covers your player, target, target of target, pet, focus, party and raid frames."] = "此角色的，用于当前天赋组。包括你的玩家、目标、目标的目标、宠物、焦点、小队和团队框体。"
L["This client has no aura container; target auras are off."] = "此客户端没有光环容器；目标光环已关闭。"
L["This fight"] = "本场战斗"
L["This frame's health text and large number. General uses the font on General > Appearance."] = "此框体的生命值文字和大数字。选择“综合”时使用综合 > 外观中的字体。"
L["This frame's names, and its level badge. General uses the font on General > Appearance."] = "此框体的名字及其等级徽章。选择“综合”时使用综合 > 外观中的字体。"
L["This frame's own health color, so it can look unlike the others. Same as the Colors page follows the color every frame shares."] = "此框体自己的生命颜色，可以与其他框体不同。“与颜色页面相同”会跟随所有框体共享的颜色。"
L["This frame's own name color. Same as the Colors page follows the name color every frame shares."] = "此框体自己的名字颜色。“与颜色页面相同”会跟随所有框体共享的名字颜色。"
L["This frame's own outline, corners and shadow, so it can stand apart from the rest of your UI."] = "此框体自己的轮廓、圆角和阴影，可以与界面其余部分区分开。"
L["This frame's own power color. Same as the Colors page follows the color every frame shares."] = "此框体自己的能量颜色。“与颜色页面相同”会跟随所有框体共享的颜色。"
L["This frame's power text. General uses the font on General > Appearance."] = "此框体的能量文字。选择“综合”时使用综合 > 外观中的字体。"
L["This group's header. The other pages use the six colors in turn."] = "此组的标题。其他页面轮流使用这六种颜色。"
L["This icon's own size. Whole group, below, sizes every icon in the group."] = "此图标自己的尺寸。下方的整组设置组内每个图标的尺寸。"
L["This level"] = "此等级"
L["This session"] = "本次登录"
L["This set hasn't been used yet. Activate it to spend its points."] = "此天赋组尚未使用。启用它以分配点数。"
L["This setting"] = "此设置"
L["This zone"] = "此地区"
