L["Those quiet errors play one soft, low tick in place of the voice line, never in a burst. Follows Soft UI sounds (General > Sound)."] = "那些轻微错误会以一声柔和低沉的滴答声代替语音，绝不连续响起。跟随柔和界面音效（综合 > 声音）。"
