L["Under its owner"] = "在其主人下方"
L["Under the action bars"] = "在动作条下方"
L["Under the bar (the cast bar moves down) or over it (the name moves up)."] = "在计量条下方（施法条下移）或上方（名字上移）。"
L["Under the cast bar"] = "在施法条下方"
L["Under the frame (slides out)"] = "在框体下方（滑出）"
L["Under the frame it continues the frame's angle and slides out as you cast. Above the frame or on its own it has its own size."] = "在框体下方时它延续框体的斜角，并在施法时滑出。在框体上方或独立时有自己的尺寸。"
L["Under the frame, it continues the frame's angle. When off, its end is straight."] = "在框体下方时它延续框体的斜角。关闭后其末端为直的。"
L["Under the frame, or over it, clear of the name. The target's buffs or debuffs on that side move out of the way."] = "在框体下方或上方，避开名字。目标在该侧的增益或减益效果会让开。"
L["Under the meter"] = "在统计下方"
L["Under the meter it rises out of the damage meter's bottom inside the panel, as wide as the meter, and the meter's rows make room. Docked (left or under), it shows only while the damage meter is open. Its own window goes anywhere: move it in unlock mode (/dui unlock) and drag its corner to size it."] = "在统计下方时，它从面板内伤害统计的底部升起，与统计等宽，统计的行会让出空间。停靠（左侧或下方）时，只在伤害统计打开时显示。独立窗口可放在任何地方：在解锁模式（/dui unlock）中移动它，拖动其角落调整大小。"
L["Under the meter it's part of the panel, with no window of its own."] = "在统计下方时它是面板的一部分，没有自己的窗口。"
