L["Unlock"] = "解锁"
L["Unlock frames"] = "解锁框体"
L["Unlocked. Drag to move, scroll to resize, right-click to put back, /dui lock when done."] = "已解锁。拖动以移动，滚动以调整大小，右键点击以复位，完成后输入/dui lock。"
L["Unpin"] = "取消标记"
L["Untrack"] = "取消追踪"
L["Untrack all"] = "取消追踪所有"
L["Up"] = "向上"
L["Up and Down scroll the text in a straight line. Arc bursts it out to the side and curves it up."] = "上和下让文字沿直线滚动。弧形让文字向侧面迸出并向上弯曲。"
L["Up early. Even the murlocs are still asleep."] = "起得真早。连鱼人都还在睡觉呢。"
L["Up to three, at the debuffs' size, with a countdown. They only appear when a boss uses them. With the game's buff frames shown, the game shows them there instead."] = "最多三个，与减益效果同尺寸，带有倒计时。只在首领使用时出现。显示游戏的增益框体时，游戏会在那里显示它们。"
L["Up to two big icons in the middle, with a sweep for the time left. They only appear when a boss uses them."] = "最多两个中间的大图标，带有剩余时间扫过效果。只在首领使用时出现。"
L["Up: newest at the bottom"] = "向上：最新的在底部"
L["Update"] = "更新"
L["Usable glow color"] = "可用发光颜色"
L["Usable"] = "可用"
L["Usage: /dui buffs toggle <category name>"] = "用法：/dui buffs toggle <category name>"
L["Use"] = "使用"
L["Use DaylightUI's"] = "使用DaylightUI的"
L["Use DaylightUI's Cooldown Manager"] = "使用DaylightUI的冷却管理器"
L["Use DaylightUI's quest tracker"] = "使用DaylightUI的任务追踪器"
L["Use a setup I have"] = "使用我已有的设置"
L["Use accent color"] = "使用强调色"
L["Use guild money first"] = "优先使用公会资金"
L["Use my language's font"] = "使用我所用语言的字体"
L["Use my layout on this character"] = "在此角色上使用我的布局"
L["Use raid frames in a party"] = "在小队中使用团队框体"
L["Use this"] = "使用这个"
L["Use this font for the game's text"] = "将此字体用于游戏文字"
L["Use this heal indicator"] = "使用此治疗指示"
L["Used by all DaylightUI text, except where a frame's own page picks another font. Game font is the client's own, including a font you've replaced it with. Fonts other addons share (SharedMedia) are listed after ours."] = "所有DaylightUI文字都使用它，除非某个框体自己的页面另有选择。游戏字体是客户端自带的字体，包括你替换过的字体。其他插件共享的字体（SharedMedia）列在我们的之后。"
L["Used when Unit Frames > Extras > Combo points > Colors is a gradient: All points fills every pip with one pair, Point 1 to 5 give each pip its own."] = "当单位框体 > 额外 > 连击点数 > 颜色设为渐变时使用：所有点数让每个点使用同一组颜色，点1至5则让每个点各有自己的颜色。"
L["Uses the Raid 10 frames, and the rows below are grayed out. Turn it off to give this raid size its own, starting from a copy of Raid 10."] = "使用团队10框体，下方各行显示为灰色。关闭后为此团队规模单独设置，从团队10的副本开始。"
L["Uses the game's own font in place of DaylightUI's fonts, which only have Latin letters. The options window changes after /reload."] = "使用游戏自带字体代替DaylightUI的字体（后者只有拉丁字母）。设置窗口在/reload后改变。"
L["Usually General."] = "通常是综合。"
L["Usually Local Defense."] = "通常是本地防务。"
L["Usually Looking for Group."] = "通常是寻求组队。"
L["Usually Trade."] = "通常是交易。"
L["Usually a skill point"] = "通常是一个技能点"
L["Varela Round"] = "Varela Round"
L["Vendor window"] = "商人窗口"
L["Vendors"] = "正在购买物品"
L["Vendors open in the NPC window too, with their goods on a shelf. Turn it off to use the game's vendor window."] = "商人也在NPC窗口中打开，其商品陈列在货架上。关闭后使用游戏的商人窗口。"
L["Version %s."] = "版本%s。"
L["Vertical (light on top)"] = "垂直（亮在上）"
L["Vertical bar"] = "垂直计量条"
L["View distance (yards)"] = "视野距离（码）"
L["Visibility"] = "可见性"
L["Visible"] = "可见"
L["Waist"] = "腰部"
L["Wait for the talents being applied."] = "请等待天赋应用完成。"
L["Walking Boots"] = "行者之靴"
L["Warmed by the fire"] = "篝火暖身"
L["Warlock"] = "术士"
L["Warm bell"] = "温暖铃声"
L["Warns you when a mob is about to change target, or has."] = "当怪物即将或已经改变目标时提醒你。"
L["Warrior"] = "战士"
L["Weapon"] = "武器"
L["Weapon Enchant"] = "武器附魔"
L["Weapon icon"] = "武器图标"
L["Weapon master"] = "武器大师"
L["Weapons"] = "武器"
L["Wearing it"] = "正在穿戴"
L["Web addresses in messages become links; click one to copy it."] = "信息中的网址会变成链接；点击即可复制。"
L["Website: %s"] = "网站：%s"
L["Welcome"] = "欢迎"
L["Went out"] = "已出"
L["What Alt-click on a quest in the tracker does."] = "在追踪器中Alt+点击任务的作用。"
L["What a button does while your target is out of range. Not enough mana, rage or energy does the same (blue when tinted)."] = "你的目标超出范围时按钮的表现。法力值、怒气或能量不足时也一样（着色时为蓝色）。"
L["What a click on a quest in the tracker does. Clicking its icon always makes it your priority, and right-click opens its menu."] = "在追踪器中点击任务的作用。点击其图标总是将其设为优先任务，右键点击打开其菜单。"
L["What a friendly NPC does (Innkeeper, Flight Master...) under its name, smaller."] = "友方NPC的职能（旅店老板、飞行管理员……），以较小字体显示在其名字下方。"
L["What an NPC does (Skinner, Flight Master...) under its name, smaller. Not inside instances."] = "NPC的职能（剥皮训练师、飞行管理员……），以较小字体显示在其名字下方。副本内不显示。"
L["What an interrupted cast bar does: Blade slices it in two, Shatter breaks it into shards, Snap cracks it in the middle, Burn out burns the fill away, Rewind whips it back to empty, Shockwave bursts light from it, Fizzle lets its light leak out. Your own interrupts light up in your accent color. Point at a choice to see it on the preview."] = "施法条被打断时的效果：刀锋将其一分为二，粉碎将其碎成碎片，折断让它从中间裂开，燃尽让填充部分燃烧殆尽，倒带让它迅速退回空条，冲击波从中爆发出光芒，熄灭让它的光芒渐渐流失。你自己的打断会以你的强调色亮起。指向一个选项即可在预览中看到。"
L["What changed in each version."] = "每个版本的更新内容。"
L["What changed in each version. Click a version to open or close it."] = "每个版本的更新内容。点击一个版本以展开或收起。"
L["What each enemy plate shows on and around its bar, and its colors."] = "每个敌方姓名板在其计量条上及周围显示的内容，以及颜色。"
L["What each item's icon shows in the Bank and alts window."] = "银行和小号窗口中每个物品图标显示的内容。"
L["What each item's icon shows in the bank."] = "银行中每个物品图标显示的内容。"
L["What each item's icon shows."] = "每个物品图标显示的内容。"
L["What each slot shows, left to right. The clock, framerate and coordinates are on the minimap too."] = "每个栏位从左到右显示的内容。时钟、帧数和坐标也在微缩地图上。"
L["What happens to the fights you have so far when you enter a dungeon, raid or battleground: keep them, ask whether to reset, or reset at once. Running back after you die doesn't count."] = "进入地下城、团队副本或战场时对已有战斗记录的处理：保留、询问是否重置，或立即重置。死亡后跑回副本不算在内。"
L["What happens to the fights you have so far when you join a group: keep them, ask whether to reset, or reset at once."] = "加入队伍时对已有战斗记录的处理：保留、询问是否重置，或立即重置。"
L["What it shows"] = "显示内容"
L["What sits between the text's parts."] = "文字各部分之间的内容。"
L["What the meter lists: damage, healing, damage taken, interrupts, dispels, deaths and more. The button on the meter changes it too."] = "统计列出的内容：伤害、治疗、承受伤害、打断、驱散、死亡等。统计上的按钮也可更改。"
L["What the second meter lists: damage, healing, damage taken, interrupts, dispels, deaths and more."] = "第二个统计列出的内容：伤害、治疗、承受伤害、打断、驱散、死亡等。"
L["What the target's or focus's cast bar does when its cast is interrupted. Your own interrupts light up in your accent color."] = "目标或焦点的施法被打断时施法条的效果。你自己的打断会以你的强调色亮起。"
L["What the tracker does when you enter a dungeon, raid or battleground. It comes back as you leave."] = "进入地下城、团队副本或战场时追踪器的表现。离开时会恢复。"
L["What this extra text shows first, like the name, the level or the guild."] = "这段额外文字首先显示的内容，例如名字、等级或公会。"
L["What this group takes. Click to change."] = "此组收取的内容。点击以更改。"
L["What this slot on the data text strip shows. Slots count from the left."] = "信息条上这个栏位显示的内容。栏位从左边开始计数。"
L["What you loot and your skill-ups, sliding in as ribbons at the bottom right."] = "你拾取的物品和技能提升，以条带形式从右下角滑入。"
L["What you loot slides in at the bottom right of the screen in its quality color, more of the same adding to its count, and fades a few seconds later. Point at a line for the item's tooltip. Move it with /dui unlock."] = "你拾取的物品以其品质颜色从屏幕右下角滑入，相同物品会累加数量，几秒后淡出。指向一行可查看物品的鼠标提示。用/dui unlock移动它。"
L["What's Training is still reading your spells."] = "“可训练”仍在读取你的法术。"
L["What's included"] = "包含内容"
L["When Threat colors are on, they replace this color while showing."] = "开启威胁颜色时，显示期间它们会取代此颜色。"
L["When a buff runs out, the spells after it slide over to fill its spot. When off, every spell keeps its place. A spell set to Keep its spot (Behavior tab) keeps it either way."] = "增益结束时，其后的法术会滑过来填补空位。关闭后每个法术保持原位。设为“保留位置”（行为标签页）的法术无论如何都保持原位。"
L["When a cast is interrupted, the bar stays full for a moment and says Interrupted."] = "施法被打断时，计量条会保持满格片刻并显示被打断。"
L["When an NPC has only one thing to offer (a vendor, flight master, banker or trainer) and no quests, its window opens straight away. Hold Shift to see the dialogue."] = "当NPC只提供一种服务（商人、飞行管理员、银行职员或训练师）且没有任务时，直接打开其窗口。按住Shift可查看对话。"
L["When auto loot is on, everything is picked up at once instead of one item at a time."] = "开启自动拾取时，一次拾取所有物品，而不是逐个拾取。"
L["When hovering a button shows its spell or item tooltip."] = "悬停按钮时何时显示其法术或物品鼠标提示。"
L["When it shows"] = "何时显示"
L["When off, any debuff with a type (Magic, Curse, Disease, Poison) shows, even one you can't remove."] = "关闭后，任何有类型（魔法、诅咒、疾病、中毒）的减益效果都会显示，即使是你无法移除的。"
L["When off, the game's own bag windows are used."] = "关闭后使用游戏自带的背包窗口。"
L["When off, the game's tracker stays where Edit Mode puts it."] = "关闭后游戏的追踪器停留在编辑模式放置的位置。"
L["When ready"] = "就绪时"
L["When the accent color is a gradient (Daylight's or your class's), window borders run along it."] = "当强调色为渐变（Daylight的或你职业的）时，窗口边框沿着它变化。"
L["When the shown bag bar fades and how far."] = "显示的背包栏何时渐隐以及渐隐程度。"
L["When the shown micro menu fades and how far."] = "显示的微型菜单何时渐隐以及渐隐程度。"
L["When to show"] = "何时显示"
L["When you destroy a good item, the confirmation box is filled in. You still press the button."] = "摧毁优质物品时，确认框会自动填写。你仍需按下按钮。"
L["When you dodge, parry or an attack misses you."] = "你躲闪、招架或攻击未命中你时。"
L["When you go away, the world dims, the UI fades and your character stands beside a card with your name, zone, rested XP and a fun fact. Move, click or press any key to come back. Never in combat, boss fights, keystones or PvP matches."] = "你离开时，世界变暗，界面渐隐，你的角色站在一张显示你名字、地区、精力充沛经验值和趣闻的卡片旁。移动、点击或按任意键即可返回。在战斗、首领战、钥石或PvP比赛中从不触发。"
L["When you have forms"] = "当你有形态时"
L["When you have totems"] = "当你有图腾时"
L["When your next auto-attack lands: a bar for each hand you swing with."] = "你下一次自动攻击的命中时间：你挥击的每只手各一个计量条。"
L["Where \"Kicked by\" and the name show: beside the cast bar or under it."] = "“打断者”和名字的显示位置：施法条旁边或下方。"
L["Where along the frame the row starts: the angled end facing the middle of your screen, the middle, or the far end."] = "这一行在框体上的起始位置：朝向屏幕中央的斜角端、中间，或远端。"
L["Where along the frame's top the tab sits. A full-width tab always starts at the outer end. Or drag the tab in Design mode."] = "标签在框体顶部的位置。全宽标签总是从外侧末端开始。也可在设计模式中拖动标签。"
L["Where along the power bar the power text sits."] = "能量文字在能量条上的位置。"
L["Where new lines come in."] = "新行出现的位置。"
L["Where on the button its key shows."] = "按键在按钮上显示的位置。"
L["Where on the frame this square sits."] = "这个方块在框体上的位置。"
L["Where the box you type in appears. Under the panel keeps a strip below the chat for it, so it never covers any text."] = "输入框出现的位置。“在面板下方”会在聊天下方保留一条空间，因此绝不会遮挡任何文字。"
L["Where the dispel icon sits on each frame, or just outside it."] = "驱散图标在每个框体上的位置，或在其外侧。"
L["Where the interrupter's name shows: right of the cast bar or under it."] = "打断者名字的显示位置：施法条右侧或下方。"
L["Where the leader crown sits on each frame, or just outside it."] = "领袖皇冠在每个框体上的位置，或在其外侧。"
L["Where the name sits across the bar, while it's on the bar: left, center or right."] = "名字在计量条上时横向的位置：左、中或右。"
L["Where the name sits across the bar: left, center or right."] = "名字在计量条上横向的位置：左、中或右。"
L["Where the name sits inside its tab: left, center or right."] = "名字在其标签内的位置：左、中或右。"
L["Where the numbers open when you hover the bar. Automatic opens them toward the middle of the screen."] = "悬停计量条时数字展开的方向。自动会朝屏幕中央展开。"
L["Where the raid marker sits on each frame, or just outside it."] = "团队标记在每个框体上的位置，或在其外侧。"
L["Where the ready check answer sits on each frame, or just outside it."] = "就位确认回答在每个框体上的位置，或在其外侧。"
L["Where the role icon sits on each frame, or just outside it."] = "职责图标在每个框体上的位置，或在其外侧。"
L["Where the role, marker, crown and dispel icons sit on a tile."] = "职责、标记、皇冠和驱散图标在格子上的位置。"
L["Where things sit on your screen."] = "各元素在屏幕上的位置。"
L["Where this category sits on the bar."] = "此类别在计量条上的位置。"
L["Where this extra text sits on the frame, or just outside it."] = "这段额外文字在框体上的位置，或在其外侧。"
L["Where this group sits in the bag."] = "此组在背包中的位置。"
L["Where you put it"] = "你放置的位置"
L["Where your frames sit. Healers get the group as big tiles in the middle of the screen."] = "你的框体所在位置。治疗者会在屏幕中央看到以大格子显示的队伍。"
L["Whether each raid group is a column, side by side, or a row, stacked down."] = "每个团队小组是一列并排，还是一行向下堆叠。"
L["Whether the meter counts the fight you're in or every fight since the last reset."] = "统计计算你当前的战斗，还是自上次重置以来的所有战斗。"
L["Whether the name tab's end is cut at an angle. Same as the frame follows the frame's own end."] = "名字标签的末端是否斜切。“与框体相同”会跟随框体自身的末端。"
L["Whether the party frames stack down or line up across."] = "小队框体向下堆叠还是横向排列。"
L["Whether the second meter counts the fight you're in or every fight since the last reset."] = "第二个统计计算你当前的战斗，还是自上次重置以来的所有战斗。"
L["Whether this extra group shows debuffs or buffs."] = "这个额外组显示减益效果还是增益效果。"
L["Whether your bars and your frame step aside when you're not fighting. Every part has its own Visible setting later."] = "你不在战斗时，动作条和框体是否让开。之后每个部分都有自己的可见设置。"
L["Which bar the rows below set."] = "下方各行设置的是哪个计量条。"
L["Which buffs show."] = "显示哪些增益效果。"
L["Which buffs this group shows."] = "此组显示哪些增益效果。"
L["Which buttons the look rows on this page change. A bar keeps what you change for it; the rest follows All bars."] = "此页面上的外观行更改哪些按钮。一个动作条会保留你为它做的更改；其余跟随所有动作条。"
L["Which corner of the button its count shows in."] = "按钮的数量显示在哪个角。"
L["Which debuffs show."] = "显示哪些减益效果。"
L["Which debuffs this group shows."] = "此组显示哪些减益效果。"
L["Which end of the group stays put when a spell in it hides."] = "组内法术隐藏时哪一端保持不动。"
L["Which frame the pips sit on."] = "点位于哪个框体上。"
L["Which key accepts, continues and completes. Enter is also the key that opens chat."] = "哪个键用于接受、继续和完成。回车也是打开聊天的键。"
L["Which numbers"] = "哪些数字"
L["Which of the six squares the rows below set."] = "下方各行设置的是六个方块中的哪一个。"
L["Which part's fade the rows below set."] = "下方各行设置的是哪个部分的渐隐。"
L["Which quest tracker?"] = "使用哪个任务追踪器？"
L["Which side of its owner's frame each pet bar sits on."] = "每个宠物条位于其主人框体的哪一侧。"
L["Which side of the list the quest item buttons sit on."] = "任务物品按钮位于列表的哪一侧。"
L["Which stat groups start open. By class and spec: Attributes and the one that matters for you. Groups you open or fold yourself are remembered for each character."] = "哪些属性组默认展开。按职业和专精：属性以及对你重要的那一组。你自己展开或折叠的组会为每个角色记住。"
L["Which way the color runs along a bar."] = "颜色沿计量条延伸的方向。"
L["Which way the row adds its icons, starting from its position."] = "这一行从其位置开始添加图标的方向。"
L["Which way the row of icons fills from its first icon."] = "这一行图标从第一个图标开始填充的方向。"
L["While Heroic Strike, Cleave or Maul waits for your next swing, the melee bars change color and show its name."] = "英勇打击、顺劈斩或槌击等待你下一次挥击时，近战计量条会变色并显示其名称。"
L["While moving frames, edges and centers line up with other frames. Hold Shift to drop anywhere."] = "移动框体时，边缘和中心会与其他框体对齐。按住Shift可随意放置。"
L["While possessing"] = "附身时"
L["While swinging"] = "挥击时"
L["While swinging: each bar only while its swing runs, gone between swings. In combat: all your bars while you're fighting."] = "挥击时：每个计量条只在其挥击进行时显示，挥击之间消失。战斗中：战斗时显示你所有的计量条。"
L["While the buff or debuff isn't up, it keeps its spot as a grayed icon or an empty bar, so you see what's missing."] = "增益或减益效果不存在时，它保留位置显示为灰色图标或空计量条，让你看到缺少什么。"
L["While the panel is away, how long each message stays before it fades. A new message doesn't bring old ones back. Move the mouse over the chat to see them all again."] = "面板隐藏时，每条信息停留多久后淡出。新信息不会让旧信息重新出现。将鼠标移到聊天上可再次查看全部。"
L["While you cast, the power the spell will use is shaded on your power bar."] = "施法时，法术将消耗的能量会在你的能量条上显示为阴影。"
L["While you have a bow, gun, crossbow, thrown weapon or wand."] = "当你装备弓、枪、弩、投掷武器或魔杖时。"
L["While you have a target, every other plate fades so your target stands out. A plate that starts casting comes back to full."] = "当你有目标时，其他姓名板都会淡出，让你的目标突出。开始施法的姓名板会恢复完全显示。"
L["While you have a target, your target's plate and all other plates use the sizes below (relative to Width, Health bar height and Scale)."] = "当你有目标时，你目标的姓名板和其他所有姓名板使用下方的尺寸（相对于宽度、生命条高度和缩放）。"
L["While you have a weapon in your off hand."] = "当你副手装备武器时。"
