L["Windows"] = "窗口"
L["Windows glide in and out, tooltips fade in, a spell's icon pops when it's ready, gold and XP count up. When off, everything snaps into place."] = "窗口滑入滑出，鼠标提示渐显，法术就绪时图标弹出，金币和经验递增。关闭后一切直接到位。"
L["Windows open & close"] = "窗口打开与关闭"
L["Wisdom"] = "智慧"
L["With Keep its spot (Buff missing), it shows only when you need to cast it, like Battle Shout."] = "设为保留位置（缺少增益）时，只在你需要施放时显示，例如战斗怒吼。"
L["With a pet"] = "有宠物时"
L["With both on, it shows only when you're in a group and in combat. The second meter follows these too."] = "两项都开启时，只在你在队伍中且处于战斗时显示。第二个统计也遵循这些设置。"
L["With chat open, Shift-click links the quest first."] = "聊天打开时，Shift+点击会先链接任务。"
L["With items in categories, stacks of the same item show as one, with the total. They show apart while you trade or have the mailbox or auction house open, so you can Shift-click one to split it."] = "物品分类时，相同物品的堆叠显示为一个，并显示总数。交易时或打开邮箱、拍卖行时会分开显示，方便你Shift+点击拆分。"
L["With items in categories, your Soul Shards show as one, with how many you have, though each still takes its own slot."] = "物品分类时，你的灵魂碎片显示为一个并显示数量，但每个仍占用自己的栏位。"
L["With no portrait and no name tab, the role, marker, crown and dispel icons sit in the frame's corners."] = "没有头像和名字标签时，职责、标记、皇冠和驱散图标位于框体的角落。"
L["Withdraw"] = "提取"
L["Withdraw gold"] = "提取金币"
L["Within each zone. Most recent progress moves a quest up when a kill, item or objective counts. Nearest first looks again every few seconds as you move, never in a fight or a dungeon. Nothing moves in a fight."] = "在每个地区内。最近进度：击杀、物品或目标计数时将任务上移。最近优先：移动时每隔几秒重新检查，战斗或地下城中不会。战斗中不会移动任何任务。"
