L["Your Legacy Points, their rewards, the challenges that earn them and the Legacy trees, in one window, in DaylightUI style."] = "你的经典旧世点数、其奖励、获取点数的挑战和经典旧世天赋树，全部在一个DaylightUI风格的窗口中。"
L["Your accent, when the accent color is set to Custom color."] = "强调色设为自定义颜色时你的强调色。"
