L["Your bindings"] = "你的绑定"
L["Your buffs"] = "你的增益"
L["Your buffs and debuffs."] = "你的增益和减益效果。"
L["Your buffs grow direction"] = "你的增益增长方向"
L["Your buffs left / right"] = "你的增益左 / 右"
L["Your buffs position"] = "你的增益位置"
L["Your buffs sorted into color-coded groups; debuffs edged by type."] = "你的增益效果分入颜色区分的组中；减益效果按类型加边框。"
L["Your buffs up / down"] = "你的增益上 / 下"
L["Your buffs, minimap and info panel, quest tracker and chat fade away too, so only the fire and the world are left. Point at any of them to see it."] = "你的增益、微缩地图和信息面板、任务追踪器和聊天也会淡出，只留下篝火和世界。指向其中任何一个即可看到它。"
L["Your buffs, sorted into colored categories. Right-click a buff to cancel it; shift-click to move it to another category. The bar sits beside the info panel; to move it, turn off Attach to the info panel."] = "你的增益效果，分入彩色类别中。右键点击增益可取消它；Shift+点击可将其移到另一个类别。该条位于信息面板旁边；要移动它，请关闭“附着到信息面板”。"
L["Your cast bar's color for a moment after your cast is interrupted."] = "你的施法被打断后片刻内施法条的颜色。"
L["Your cast bar's color while you cast."] = "你施法时施法条的颜色。"
L["Your cast bar's color while you channel."] = "你引导时施法条的颜色。"
L["Your cast bar's colors"] = "你的施法条颜色"
L["Your casts and channels in your class color, or your class's gradient with a two-color fill. Not with the Daylight gradient."] = "你的施法和引导使用你的职业颜色，或双色填充时使用你职业的渐变。不适用于Daylight渐变。"
L["Your character window: gear, model, stats and the other pages. It opens with C, as always."] = "你的角色窗口：装备、模型、属性和其他页面。照常按C打开。"
L["Your chat also comes back the next time you log in on this character, under a gray line with when you left."] = "你下次在此角色上登录时，聊天也会恢复，位于一条标明你离开时间的灰线下方。"
L["Your class"] = "你的职业"
L["Your class can heal; pick Healer if you do."] = "你的职业可以治疗；如果你负责治疗，请选择治疗者。"
L["Your class's pick"] = "你职业的推荐"
L["Your class's pick follows your class on every character. Pick one to watch it instead."] = "你职业的推荐会在每个角色上跟随你的职业。选择一个即可改为观察它。"
L["Your damage over time spells: the end of the health they will still take is shaded darker."] = "你的持续伤害法术：它们仍将造成的生命值末端会以较暗的阴影显示。"
L["Your damage over time spells: the end of the health they will still take is shaded darker. The color is on Unit Frames > Colors."] = "你的持续伤害法术：它们仍将造成的生命值末端会以较暗的阴影显示。颜色在单位框体 > 颜色中。"
L["Your debuffs"] = "你的减益"
L["Your debuffs, crowd control and buffs you can remove, on enemy plates."] = "敌方姓名板上你的减益效果、控制效果和你可以移除的增益效果。"
L["Your focus's cast bar fills from the right. Not while it sits inside the frame."] = "你焦点的施法条从右侧开始填充。在框体内时不适用。"
L["Your focus's casts, while they last. It uses the target cast bar's colors."] = "你焦点的施法，持续期间显示。它使用目标施法条的颜色。"
L["Your frame's own health color, so it can look unlike the others. Same as the Colors page follows the color every frame shares; Daylight gradient is the logo's blue to orange."] = "你框体自己的生命颜色，可以与其他框体不同。“与颜色页面相同”会跟随所有框体共享的颜色；Daylight渐变是标志的蓝色到橙色。"
L["Your frames per second beside the clock."] = "时钟旁边显示你的每秒帧数。"
L["Your frames per second beside the clock. Hover it for latency, addon CPU and memory."] = "时钟旁边显示你的每秒帧数。悬停可查看延迟、插件CPU和内存。"
L["Your friends, recent allies, friend requests and the raid, in one window, in DaylightUI style."] = "你的好友、近期往来、好友请求和团队，全部在一个DaylightUI风格的窗口中。"
L["Your group is too big for a %d-player activity."] = "你的队伍人数对于%d人活动来说太多了。"
L["Your guild's officer chat."] = "你公会的官员聊天。"
L["Your heals over time and shields, everything you cast, or all of them. A class without heals sees everything it casts."] = "你的持续治疗和护盾、你施放的所有效果，或全部。没有治疗能力的职业会看到它施放的所有效果。"
L["Your health and mana come back faster while you're not fighting or casting."] = "不在战斗或施法时，你的生命值和法力值恢复得更快。"
L["Your health and power just under your character, the way Legion's personal display sat at your feet."] = "你的生命值和能量就在你角色下方，就像军团再临的个人资源显示在你脚下一样。"
L["Your health bar, your power under it and, for rogues and druids, your combo points, just under your character. It follows the camera as you zoom."] = "你的生命条、其下方的能量，以及盗贼和德鲁伊的连击点数，就在你角色下方。镜头缩放时随之移动。"
L["Your health. Each point adds about 10; you have %.0f."] = "你的生命值。每点约增加10；你有%.0f。"
L["Your last name after your first, at the top of the window."] = "在窗口顶部，你的名字后显示你的姓氏。"
L["Your letters, sending, and what you made through the mail and the auction house, in one window, in DaylightUI style."] = "你的信件、寄送，以及你通过邮件和拍卖行的收入，全部在一个DaylightUI风格的窗口中。"
L["Your listing"] = "你的列表"
L["Your main hand swings every %.2f seconds. Lower is faster."] = "你的主手每%.2f秒挥击一次。越低越快。"
L["Your mana, rage or energy under the health bar."] = "生命条下方你的法力值、怒气或能量。"
L["Your melee attacks hit harder: Strength adds attack power."] = "你的近战攻击更强：力量增加攻击强度。"
L["Your own buffs and heals over time, in a row above the name."] = "你自己的增益效果和持续治疗，排成一行显示在名字上方。"
L["Your own color"] = "你自己的颜色"
L["Your own cooldown layout: every spell the Cooldown Manager tracks as an icon or a bar, placed where you like and snapped together. One layout per talent set, for this character."] = "你自己的冷却布局：冷却管理器追踪的每个法术都以图标或计量条显示，放在你喜欢的位置并对齐吸附。每个天赋组一个布局，仅限此角色。"
L["Your own frame sits with the party's. When off, only the rest of the party shows."] = "你自己的框体与小队一起显示。关闭后只显示小队其他成员。"
L["Your own frame."] = "你自己的框体。"
L["Your own groups"] = "你自己的分组"
L["Your own layout on this character. When off, this character's spells show where the game puts them, still in DaylightUI's look. Saved for this character."] = "此角色使用你自己的布局。关闭后此角色的法术显示在游戏放置的位置，仍使用DaylightUI的外观。为此角色保存。"
L["Your own tile sits with the raid's. When off, only the rest of the raid shows."] = "你自己的格子与团队一起显示。关闭后只显示团队其他成员。"
L["Your party and raid as square tiles under you, dispels easy to spot."] = "你的小队和团队以方形格子显示在你下方，驱散一目了然。"
L["Your party: bars like your own frame, or square tiles. Set how they line up, what shows, and move them as one in unlock mode."] = "你的小队：像你自己框体那样的计量条，或方形格子。设置排列方式、显示内容，并在解锁模式中整体移动。"
