L["Your quests in the DaylightUI look, with item buttons and smooth motion."] = "DaylightUI外观的任务，带有物品按钮和流畅动态效果。"
L["Your role"] = "你的职责"
L["Your shots don't land critical hits yet."] = "你的射击还不会造成爆击。"
L["Your spellbook and talents in one window, in DaylightUI style."] = "你的法术书和天赋，全部在一个DaylightUI风格的窗口中。"
L["Your spells don't land critical hits yet."] = "你的法术还不会造成爆击。"
L["Your target's cast bar fills from the right. Not while it sits inside the frame."] = "你目标的施法条从右侧开始填充。在框体内时不适用。"
