L["/dui whispers - every whisper conversation"] = "/dui whispers - 所有悄悄话对话"
L["1 spam line hidden"] = "已隐藏 1 条垃圾消息"
L["A new whisper shows its first words above the tiles for a few seconds. Click it to answer."] = "新的悄悄话会在方块上方显示开头几个字，持续几秒。点击即可回复。"
L["A note about this player"] = "关于此玩家的备注"
L["A small number in your accent color after a tab's name: how many new messages landed in it since you last looked."] = "标签页名称后的强调色小数字：显示自上次查看以来收到的新消息数量。"
L["A soft glow behind a message that says your name or one of your words."] = "提到你的名字或你设置的词语的消息后方会有柔和的光晕。"
L["A soft sound when your name or one of your words shows up."] = "出现你的名字或你设置的词语时播放一个轻柔的声音。"
L["A thin line in your accent color along the top of the chat."] = "聊天框顶部的一条强调色细线。"
L["Accent line on top"] = "顶部强调线"
L["Answers whispers for you, once per person every 15 minutes."] = "替你回复悄悄话，每人每 15 分钟一次。"
