L["Chat is locked during this fight: whispers can be sent again after it."] = "此战斗期间聊天被锁定：战斗结束后才能再次发送悄悄话。"
L["Chat options"] = "聊天选项"
L["Chat style"] = "聊天样式"
L["Chat style: Classic."] = "聊天样式：经典。"
L["Chat style: Classic. /dui chat daylight for the Daylight chat box."] = "聊天样式：经典。输入 /dui chat daylight 使用 Daylight 聊天框。"
L["Chat style: Daylight."] = "聊天样式：Daylight。"
L["Chat style: Daylight. /dui chat classic for the game's chat windows."] = "聊天样式：Daylight。输入 /dui chat classic 使用游戏自带的聊天窗口。"
L["Classic"] = "经典"
L["Click: open the conversation"] = "点击：打开对话"
L["Combat Log"] = "战斗记录"
L["Conversation width"] = "对话宽度"
L["Copy chat"] = "复制聊天"
L["Daylight UI's chat box in the bottom-left corner, with whispers as conversations beside it. Chat style: Classic keeps the game's own chat windows instead."] = "Daylight UI 的聊天框位于左下角，悄悄话以对话形式显示在旁边。聊天样式选“经典”则保留游戏自带的聊天窗口。"
L["Daylight look"] = "Daylight 外观"
L["Daylight: Daylight UI's own chat box, with its own tabs. Classic: the game's chat windows and tabs in the Daylight look. Switching is instant, and both keep every message."] = "Daylight：Daylight UI 自己的聊天框，带有自己的标签页。经典：游戏自带的聊天窗口和标签页，换上 Daylight 外观。切换即时生效，两者都保留全部消息。"
L["Count on tabs with new messages"] = "有新消息的标签页显示数量"
L["Each new message fades in instead of appearing at once. Never in a fight."] = "每条新消息淡入显示，而不是瞬间出现。战斗中不会。"
