L["Hide repeated messages"] = "隐藏重复消息"
L["How long a new whisper's preview stays."] = "新悄悄话预览停留的时间。"
L["How many people's tiles slide out beside the chat at most."] = "聊天框旁最多滑出多少人的方块。"
