L["In a dungeon or raid"] = "在地下城或团队副本中"
L["In a fight"] = "战斗中"
L["In public channels (General, Trade, say...), the same words from the same person again within a minute are hidden. Guild, group and whispers are never hidden."] = "在公共频道（综合、交易、说……）中，同一个人一分钟内重复的相同内容会被隐藏。公会、队伍和悄悄话永不隐藏。"
L["In the Daylight chat box (Chat style: Daylight)."] = "在 Daylight 聊天框中（聊天样式：Daylight）。"
L["Left of the chat"] = "聊天框左侧"
