L["The Daylight chat box's own look and motion (Chat style: Daylight)."] = "Daylight 聊天框自己的外观与动效（聊天样式：Daylight）。"
L["The chat only"] = "仅聊天框"
L["The side the whisper tiles and conversations slide out from. Left suits a chat on the right of your screen."] = "悄悄话方块和对话滑出的一侧。聊天框在屏幕右侧时适合选左侧。"
