L["Their class icon"] = "职业图标"
L["Their initial"] = "名字首字"
L["Their initial in their class's colors, or their class icon from the set picked in Unit Frames (Daylight UI's own or a Jiberish style)."] = "名字首字使用职业颜色，或使用单位框体中所选图标组的职业图标（Daylight UI 自带或 Jiberish 风格）。"
L["Their own window"] = "独立窗口"
L["Their own window and the chat"] = "独立窗口和聊天框"
L["Their own window: a tile beside the chat for each person you talk to; click one to open the conversation. The chat only: whispers stay in the chat like any other message."] = "独立窗口：聊天框旁为每位交谈对象显示一个方块，点击即可打开对话。仅聊天框：悄悄话像其他消息一样留在聊天框中。"
L["Tile size"] = "方块大小"
L["Trade"] = "交易"
L["Unlock the chat's size"] = "解锁聊天框大小"
L["What the away message says."] = "离开消息的内容。"
L["When someone writes your name where people talk, it lights up in your accent color and the tab it lands in glows."] = "有人在聊天频道里写到你的名字时，名字会以强调色高亮，所在标签页也会发光。"
L["When the away message answers."] = "离开消息何时回复。"
L["Where the box you type in appears. Under the panel keeps a strip below the chat for it, so it never covers any text. At the bottom, the Daylight chat box lifts its messages over the box while you type."] = "输入框出现的位置。“在面板下方”会在聊天框下留出一条空间，输入框永远不会遮住文字。“底部”时，Daylight 聊天框会在你输入时把消息抬到输入框上方。"
L["Whisper tiles"] = "悄悄话方块"
L["Whisper tiles show"] = "悄悄话方块显示"
L["Whispers are part of the Daylight chat box: /dui chat daylight to use it."] = "悄悄话属于 Daylight 聊天框：输入 /dui chat daylight 即可使用。"
L["Whispers open on the"] = "悄悄话打开于"
L["Whispers show in"] = "悄悄话显示于"
L["With the chat input at the bottom: while you type, the messages slide up and the box you type in sits under them, so it never covers a line."] = "输入框在底部时：输入期间消息上移，输入框位于消息下方，不会遮住任何一行。"
L["Words to light up"] = "高亮词语"
L["Words to light up, separated by commas"] = "要高亮的词语，用逗号分隔"
L["XP, reputation and skills"] = "经验、声望与技能"
L["not a table"] = "不是表"
L["show"] = "显示"
L["A bar of its own for the faction you're watching. While it's on, the experience bar no longer turns to reputation when you gain some."] = "为你关注的阵营单独显示一条声望条。开启时，获得声望后经验条不再切换为声望。"
L["Game window skins"] = "游戏窗口皮肤"
L["How far through the standing you are, e.g. 60%."] = "你在当前关系中的进度，例如 60%。"
L["How tall the reputation bar is."] = "声望条的高度。"
L["How wide the reputation bar is. Dragging its corner in unlock mode sets this too."] = "声望条的宽度。在解锁模式中拖动其角落也会设置此项。"
L["More windows"] = "其他窗口"
L["Reputation Bar"] = "声望条"
L["Reputation bar"] = "声望条"
L["Reputation bar gradient"] = "声望条渐变"
L["Reputation bar height"] = "声望条高度"
L["Reputation bar width"] = "声望条宽度"
L["Reputation details position"] = "声望详情位置"
L["Reputation text size"] = "声望文字大小"
L["Show a separate reputation bar"] = "显示独立声望条"
L["Show reputation as text"] = "以文字显示声望"
L["Show reputation percent"] = "显示声望百分比"
L["Show the faction's name"] = "显示阵营名称"
L["Size of the text on the reputation bar. Its font is the experience bar's."] = "声望条上文字的大小。字体与经验条相同。"
L["Spellbook, inspect, professions, group finder, mailbox, social and Legacy: each window's switch, its size and its own extras."] = "法术书、观察、专业、队伍查找器、邮箱、社交和传承：各窗口的开关、尺寸和额外功能。"
L["The bar shades from dark to bright in its standing's colors, editable on the Gradients page."] = "声望条按其关系的颜色由暗到亮渐变，可在渐变页面编辑。"
L["The faction's name on the bar."] = "声望条上的阵营名称。"
L["The numbers on the bar, e.g. 1,800 / 3,000."] = "声望条上的数字，例如 1,800 / 3,000。"
L["The reputation you're watching, always, on its own bar. Pick the faction on the Reputation page of the character window. Move it in unlock mode; drag its corner to resize."] = "你关注的声望，始终显示在独立的声望条上。在角色窗口的声望页面选择阵营。在解锁模式中移动它；拖动角落调整大小。"
L["Welcome back, %s"] = "欢迎回来，%s"

-- Lines contributed by a Chinese player for 1.6.1, the ones that still match.
L["%d pt"] = "%d 磅"
L["%s (drag items here)"] = "%s（将物品拖到这里）"
L["%s lets you move frames; right-click a handle to put one back."] = "%s 可移动框体；右键点击拖动柄可将其复位。"
L["%s opens the settings."] = "%s 打开设置。"
L["%s, skill %d / %d"] = "%s，技能 %d / %d"
L["/dui brew - preview the brew"] = "/dui brew - 预览酿造效果"
L["/dui fishing - preview the fishing water"] = "/dui fishing - 预览钓鱼水面"
L["/dui forge - preview the forge"] = "/dui forge - 预览锻造效果"
L["/dui glow - preview the object glow"] = "/dui glow - 预览物体发光效果"
L["/dui platecheck - run while a nameplate is missing, and send us what it prints"] = "/dui platecheck - 姓名板缺失时运行，并将输出结果发给我们"
L["/dui plateprobe - run after /dui platecheck while nameplates are missing, and say if they come back"] = "/dui plateprobe - 姓名板缺失时在 /dui platecheck 后运行，并告知是否恢复"
L["/dui sewing - preview the sewing"] = "/dui sewing - 预览裁缝效果"
L["/dui workshop - preview the workshop"] = "/dui workshop - 预览工程效果"
L["A ! after each crit."] = "每次爆击后添加一个 !。"
L["A - before damage and a + before heals."] = "伤害前显示 -，治疗前显示 +。"
L["A line of light under each crit."] = "在每次爆击下方显示一条光线。"
L["A mob that needs you slowly brightens and dims, quicker when it's about to switch. For a tank that's a mob you lost, for damage and healers one attacking you. Needs the health bar, border or glow above."] = "需要你处理的怪物会缓慢明暗闪烁，即将转向时闪得更快。对坦克来说是你失去仇恨的怪物，对伤害和治疗职业来说是正在攻击你的怪物。需要开启上方的生命条、边框或光晕。"
L["A moving glow around the button while its spell is queued or being cast."] = "法术排队或正在施放时，按钮周围会出现流动光效。"
L["A new group starts empty and waits in your bag: drag items onto its name, or click the search beside it here to fill it by itself."] = "新建分组初始为空，并等待在背包中：将物品拖到分组名称上，或点击此处分组旁的搜索按钮自动填充。"
L["A profile per character or talent set, and a share string for your whole setup."] = "每个角色或每套天赋各用一个配置，并可生成分享整套设置的字符串。"
L["A quest under the mouse shows its objectives and clicks beside the tracker. When off, nothing shows and clicks work the same."] = "鼠标悬停的任务会在追踪器旁显示目标和点击操作。关闭后不显示，但点击行为不变。"
L["A second chat box with its own tabs, for loot, guild or a combat log. Right-click a chat tab to move it over, or drag it onto the other panel. Typing and whispers stay in the main chat."] = "第二个聊天框，拥有独立标签页，可用于战利品、公会或战斗日志。右键点击聊天标签可将其移过去，或将其拖到另一个面板上。输入和悄悄话仍保留在主聊天框。"
L["A shield landing on you."] = "施加到你身上的护盾。"
L["A slim angled bar at the bottom of the screen: the clock in the middle, your data texts on both sides."] = "屏幕底部的一条细长斜角栏：时钟位于中间，数据文字位于两侧。"
L["A small crown tab that opens ready check, role check, a pull timer, and target and world markers. It shows while you lead the group or assist in a raid. When off, these are only in the game's slash commands."] = "一个小王冠标签，可打开就位确认、职责确认、开怪倒计时、目标标记和世界标记。当你担任队长或在团队中担任助理时显示。关闭后只能通过游戏的斜杠命令使用。"
L["A small dot in front of each quest you're tracking."] = "在你追踪的每个任务前显示一个小圆点。"
L["A small icon and count at the end of a quest's line when others in your party have it too, here and in the quest log on the map."] = "当队伍中其他成员也有同一任务时，在任务行末尾显示小图标和人数，追踪器和地图任务日志中均会显示。"
L["A small icon before each text, in your accent color."] = "在每段文字前显示一个使用强调色的小图标。"
L["A small skull by the bar once your damage over time is enough to finish that enemy."] = "当你的持续伤害足以击杀该敌人时，在血条旁显示一个小骷髅。"
L["A small slanted mark beside each line, in its color."] = "在每行文字旁显示一个同色的小斜角标记。"
L["A soft shadow under each line."] = "在每行文字下方添加柔和阴影。"
L["A warning that stays up while your health or mana is low."] = "生命值或法力值过低时持续显示的警告。"
L["A word or phrase"] = "一个词或短语"
L["About to switch"] = "即将转向"
L["Absorb shields gained"] = "获得的吸收护盾"
L["Accent follows the accent color on the Appearance page. Class uses your class's gradient (set on the Gradients page). Reputation keeps its standing's colors."] = "“强调色”跟随外观页面中的强调色。“职业”使用职业渐变（在渐变页面设置）。“声望”保留当前关系等级的颜色。"
L["Active border and glow color"] = "启用边框与光效颜色"
L["After you cast a spell that costs mana, a light crosses your mana bar for the 5 seconds until your Spirit regen is back. Shows on your player frame and personal display."] = "施放消耗法力的法术后，法力条上会有一道光扫过，持续 5 秒，直到你的精神回蓝恢复。会显示在玩家框体和个人显示上。"
L["Always, or only while you hold this key."] = "始终生效，或仅在你按住此键时生效。"
L["An item link shows your equipped item beside it, as the game's own compare setting says. Off, only while Shift is held."] = "物品链接旁会显示你装备的物品，遵循游戏自带的比较设置。关闭后，仅在按住 Shift 时显示。"
L["An outline keeps the text readable over bright ground and spell effects."] = "描边可让文字在明亮地面和法术效果上依然清晰可读。"
L["Anchor: %s"] = "锚点：%s"
L["Answers whispers for you, once per person every 15 minutes. Someone you whispered in that time doesn't get it."] = "自动回复悄悄话，每人每 15 分钟一次。你在这段时间内主动密语过的人不会收到自动回复。"
L["Anything else you can use lights up too: doors, levers, mailboxes."] = "其他可交互物体也会发光：门、拉杆、邮箱。"
L["Arrow keys move it, Shift a grid step"] = "方向键移动；按住 Shift 时按网格步进。"
L["Attacking you"] = "正在攻击你"
L["Attacks that didn't land on you."] = "未命中你的攻击。"
L["Boss emotes"] = "首领表情"
L["Breath bar"] = "呼吸条"
L["Brew"] = "酿造"
L["Buffs gained and lost"] = "获得和失去的增益"
L["By the quest's difficulty for your level, or one color for all. The quest log on the map uses the same colors."] = "按任务相对你等级的难度着色，或所有任务使用同一种颜色。地图上的任务日志使用相同颜色。"
L["Calm"] = "平静"
L["Can't interrupt"] = "无法打断"
L["Cast bar on the personal display"] = "个人显示上的施法条"
L["Cast spells by clicking your unit frames, or by hovering them and pressing your usual keys."] = "点击单位框体施放法术，或将鼠标悬停在单位框体上并按常用按键施放。"
L["Casts, interrupts and more"] = "施法、打断及其他"
L["Channels"] = "频道"
L["Chests, crates and barrels light up. A crate or barrel may take one loot before it's recognized."] = "宝箱、板条箱和木桶会发光。板条箱或木桶可能需要先拾取一次才能被识别。"
L["Clear all"] = "全部清除"
L["Click again: pinned ones stay"] = "再次点击：已固定的项目会保留"
L["Click the item to enchant"] = "点击要附魔的物品"
L["Click to pick another"] = "点击选择其他物品"
L["Click: pick its color"] = "点击：选择颜色"
L["Color spell hits by school"] = "按法术学派为法术伤害着色"
L["Combat text"] = "浮动战斗信息"
L["Combat text outline"] = "浮动战斗信息描边"
L["Combat text preset"] = "浮动战斗信息预设"
L["Combat text shadow"] = "浮动战斗信息阴影"
L["Community invites only open from the game's own chat: set Chat style to Classic, then click it."] = "社区邀请只能从游戏自带的聊天框打开：将聊天样式设为“经典”，然后点击它。"
L["Compare with what you wear"] = "与你装备的物品比较"
L["Counts like 0/6, and Ready, at the end of each quest's row."] = "在每个任务行的末尾显示类似 0/6 的计数，以及“可交付”。"
L["Crit exclamation mark"] = "爆击感叹号"
L["Crit light"] = "爆击光效"
L["Crit style"] = "爆击样式"
L["Crit underline"] = "爆击下划线"
L["Crits"] = "爆击效果"
L["Ctrl-click"] = "Ctrl+点击"
L["Current zone first in the quest log"] = "任务日志中当前区域优先"
L["Cuts both ends of the bar at an angle. Off, they're straight."] = "将计量条两端切成斜角。关闭后两端为平直。"
L["Cuts the end of your target's cast bar at an angle. When off, its end is straight. Not inside the frame or sliding out under it."] = "将目标施法条的末端切成斜角。关闭后末端为平直。不适用于框体内或从框体下方滑出的施法条。"
L["Cuts the right end of the breath bar at an angle, on the fatigue and feign death bars too. When off, the end is straight."] = "将呼吸条右端切成斜角，疲劳条和假死条也一样。关闭后末端为平直。"
L["Cuts the right end of the flight timer at an angle. When off, the end is straight."] = "将飞行计时条右端切成斜角。关闭后末端为平直。"
L["Data bar"] = "数据栏"
L["Data bar accent line"] = "数据栏强调线"
L["Data bar angled ends"] = "数据栏斜角端"
L["Data bar border opacity"] = "数据栏边框不透明度"
L["Data bar height"] = "数据栏高度"
L["Data bar icons"] = "数据栏图标"
L["Data bar labels"] = "数据栏标签"
L["Data bar text size"] = "数据栏文字大小"
L["Data bar width"] = "数据栏宽度"
L["DaylightMogul's mailbox is in use."] = "DaylightMogul 的邮箱正在使用中。"
L["DaylightMogul's profession window is in use."] = "DaylightMogul 的专业窗口正在使用中。"
L["DaylightMogul's vendor window is in use."] = "DaylightMogul 的商人窗口正在使用中。"
L["DaylightUI saved the crowd control alert's position. Reload to put it in place?"] = "DaylightUI 已保存控制技能警报的位置。要重载界面以应用吗？"
L["DaylightUI saved these positions. Reload to put them in place?"] = "DaylightUI 已保存这些位置。要重载界面以应用吗？"
L["Debuffs gained and lost"] = "获得和失去的减益"
L["Did the nameplates come back within a second? Tell the Daylight UI team yes or no, then /reload."] = "姓名板是否在一秒内恢复？请告诉 Daylight UI 团队“是”或“否”，然后 /reload。"
L["Drag a tab to move it. Right-click: what it shows, rename, remove"] = "拖动标签页可移动。右键点击：设置显示内容、重命名、移除"
L["Emotes"] = "表情"
L["Enchant all"] = "全部附魔"
L["Enchant on"] = "附魔到"
L["Every area's fade in one place: in combat, on mouseover, or always shown."] = "所有区域的淡出设置集中在一处：战斗中、鼠标悬停时或始终显示。"
L["Everything switched on, with Daylight UI's own look."] = "全部开启，并采用 Daylight UI 自带的样式。"
L["Experience and honor"] = "经验与荣誉"
L["Experience bar fade"] = "经验条淡出"
L["Experience bar has its own fade"] = "经验条使用独立淡出"
L["Fade the UI while talking"] = "对话时淡出界面"
L["Fire orange, frost blue, shadow purple. When off, they use the Spell hits color."] = "火焰为橙色、冰霜为蓝色、暗影为紫色。关闭后使用“法术命中”的颜色。"
L["Fishing water"] = "钓鱼水面"
L["Flare lands big in a burst of soft light. Slam lands bigger and faster. Pop is a small bump. Plain is just bigger text."] = "闪耀：以一团柔光大幅弹出。重击：弹得更大、更快。轻弹：轻微弹跳。朴素：只放大文字。"
L["Flight maps, books and letters, tabards and petitions, the stable. Also the game's own quest, gossip, vendor, trainer and bank windows while Daylight UI's are off."] = "飞行地图、书籍和信件、战袍和请愿书、马厩。以及 DaylightUI 对应窗口关闭时游戏自带的任务、对话、商人、训练师和银行窗口。"
L["Flight maps, stable and books"] = "飞行地图、马厩和书籍"
L["Flip the loot feed left and right"] = "左右翻转战利品信息流"
L["Font, accent and colors"] = "字体、强调色与颜色"
L["Forge"] = "锻造"
L["Full numbers, or short ones for high-level play."] = "使用完整数字，或适合高级内容显示的缩写数字。"
L["Glow on an active spell"] = "启用中的法术发光"
L["Glow on chests"] = "宝箱发光"
L["Glow on everything else"] = "其他物体发光"
L["Glow on ore and herbs"] = "矿脉和草药发光"
L["Glow on quest objects"] = "任务物体发光"
L["Glow on your fishing bobber"] = "你的鱼漂发光"
L["Glows while the buff is down, to remind you to cast it."] = "增益缺失时发光，提醒你施放。"
L["Good to know"] = "实用提示"
L["Group %d (%d)"] = "分组 %d（%d）"
L["Guild and communities, the calendar, trading, the guild bank. Also the game's own friends, mail and group finder windows while Daylight UI's are off."] = "公会和社区、日历、交易、公会银行。以及 DaylightUI 对应窗口关闭时游戏自带的好友、邮件和队伍查找器窗口。"
L["Guild, calendar and trading"] = "公会、日历和交易"
L["Hardcore"] = "硬核"
L["Heals"] = "治疗"
L["Heals over time"] = "持续治疗"
L["Heals you receive."] = "你受到的治疗。"
L["Health text position"] = "生命值文字位置"
L["Hide shows the spell only while it's on cooldown. It keeps its gap: the other spells don't move."] = "“隐藏”仅在法术冷却中时显示它，并保留空位：其他法术不会移动。"
L["Hides messages with these in public channels, never guild, group or whispers. Whole words; capitals don't matter. Chat style: Daylight only."] = "在公共频道中隐藏包含这些词的消息，不影响公会、队伍和悄悄话。按整词匹配，不区分大小写。仅适用于 Daylight 聊天样式。"
L["Hits you take from spells."] = "你受到法术造成的伤害。"
L["Hits you take from weapons."] = "你受到武器攻击造成的伤害。"
L["Hover a setting to see what it does; the arrow beside a changed setting puts it back."] = "将鼠标悬停在设置上可查看说明；更改过的设置旁的箭头可将其恢复。"
L["Hover a text for details, click it to open its window. Move it in unlock mode (/dui unlock). When it reaches the screen's corners, chat and the damage meters' windows start above it unless you've moved them."] = "悬停文字可查看详情，点击可打开对应窗口。在解锁模式（/dui unlock）中移动。当它到达屏幕角落时，聊天框和伤害统计窗口会从其上方开始，除非你已移动过它们。"
L["Hover delay (seconds)"] = "悬停延迟（秒）"
L["Hovering a Questie icon on the map or minimap, or a quest in the quest log, makes that quest's icons a little bigger and fades the other quests' icons."] = "悬停地图或微缩地图上的 Questie 图标，或任务日志中的任务时，会稍微放大该任务的图标，并淡化其他任务的图标。"
L["Hovering an icon says what it is. While the mouse is on an icon, mouseover casting misses that player. Clicks always go through to the frame."] = "悬停图标可查看其含义。鼠标位于图标上时，鼠标指向施法不会命中该玩家。点击仍会穿透到框体。"
L["Hovering an item, spell or quest link in chat shows its tooltip. Off, clicking a link still opens it."] = "在聊天中悬停物品、法术或任务链接时显示其鼠标提示。关闭后，点击链接仍可打开。"
L["How a big hit or heal, or a spell lighting up, lands."] = "设置强力伤害、治疗或法术触发效果出现时的表现。"
L["How big the number of stacks is on each buff icon."] = "每个增益图标上显示层数的字号大小。"
L["How big the number of stacks is on each debuff icon."] = "每个减益图标上显示层数的字号大小。"
L["How big the texts are. The one in the middle is a little bigger."] = "文字大小。中间的文字会稍大一些。"
L["How big the time left is on each buff icon."] = "每个增益图标上剩余时间的字号大小。"
L["How big the time left is on each debuff icon."] = "每个减益图标上剩余时间的字号大小。"
L["How bright the light behind a crit is. At 0 there is none."] = "设置爆击文字背后光效的亮度。为 0 时不显示光效。"
L["How far a line travels. Stack ignores this."] = "文字移动的距离。“堆叠”模式会忽略此项。"
L["How far the angled end leans, docked bars included. Set to 0 to use the Slant angle on Extras."] = "斜角端的倾斜程度，包括停靠的动作条。设为 0 时使用“额外”中的斜角角度。"
L["How far under the object's name the light sits once you can reach it. The game doesn't say how tall an object is, so this is a best fit for most of them."] = "进入可交互范围后，光效位于物体名称下方多远。游戏不提供物体高度，因此此值适用于大多数物体。"
L["How long the mouse rests on a link before its tooltip shows, so sweeping across the chat leaves it quiet."] = "鼠标在链接上停留多久后显示提示，避免鼠标扫过聊天框时频繁弹出。"
L["How low your health or mana gets before the warning shows."] = "生命值或法力值低到此比例时显示警告。"
L["How much of the screen's width the bar takes, in percent."] = "计量条占屏幕宽度的百分比。"
L["How see-through a spell set to Fade gets."] = "设为“淡出”的法术的透明度。"
L["How see-through it is while shown, whatever the fade does. At 0 it never shows, even under the mouse or in a fight."] = "显示时的透明度，不受淡出设置影响。为 0 时永远不会显示，即使鼠标悬停或进入战斗。"
L["How solid the border around the bar is: 0 is no border."] = "计量条边框的实心程度：0 为无边框。"
L["How solid the quest log's background is. Lower lets the world show through behind the list."] = "任务日志背景的实心程度。数值越低，列表后的世界越明显。"
L["How tall a crit is once it settles."] = "爆击文字稳定后的高度。"
L["How tall a line of text is."] = "一行文字的高度。"
L["How tall each quest's row is in the quest log. Larger text keeps enough room however low this is set."] = "任务日志中每个任务行的高度。即使此值设得很低，较大文字也会保留足够空间。"
L["How tall the data bar is."] = "数据栏的高度。"
L["How you find your way to quests, how they show in the tracker, and how talking to NPCs looks."] = "任务寻路方式、任务在追踪器中的显示方式，以及与 NPC 对话时的外观。"
L["Immersive Preset"] = "沉浸预设"
L["In your layout: click to move it here."] = "在你的布局中：点击将其移动到这里。"
L["Its ring buttons in your action bar look. The ring, its spin and its options stay OPie's."] = "其环形按钮会采用你的动作条外观。圆环、旋转和选项仍由 OPie 控制。"
L["Keep tracking on"] = "保持追踪开启"
L["Last sold"] = "上次售出"
L["Layout and profile"] = "布局与配置"
L["Left stream"] = "左侧文字流"
L["Light the border on an active spell"] = "启用中的法术边框发光"
L["Link tooltip position"] = "链接鼠标提示位置"
L["Link tooltips"] = "链接鼠标提示"
L["Lock the chat's spot and size"] = "锁定聊天框的位置和大小"
L["Low health"] = "生命值过低"
L["Low health warning at"] = "低生命值警告阈值"
L["Low mana"] = "法力值过低"
L["Mana regen sweep"] = "法力回复扫光"
L["Mark tracked quests in the quest log"] = "在任务日志中标记已追踪任务"
L["Melee and ranged hits"] = "近战和远程命中"
L["Minimap tracking"] = "微缩地图追踪"
L["Mining veins and herbs light up."] = "矿脉和草药会发光。"
L["Mirrors the feed: lines line up on the left, slide in from the left and leave to the right, with the icon at the right end. Handy when the feed sits on the left of the screen. When off, lines line up on the right."] = "镜像信息流：文字左对齐，从左侧滑入并向右侧离开，图标位于右端。适合信息流位于屏幕左侧时使用。关闭后文字右对齐。"
L["Missing health shows nothing while you're at full."] = "满血时不显示缺失生命值。"
L["Modules on"] = "已启用模块"
L["Money"] = "金币"
L["Mouse wheel or right-drag: slide the tabs"] = "鼠标滚轮或右键拖动：滑动标签页"
L["Mouseover casting"] = "鼠标指向施法"
L["Mouseover key"] = "鼠标指向按键"
L["Move the camera in"] = "拉近镜头"
L["Move the text"] = "移动文字"
L["Move the text streams"] = "移动文字流"
L["Move to main panel"] = "移到主面板"
L["Move to second panel"] = "移到第二个面板"
L["Move together"] = "一起移动"
L["Moves your cast bar under the personal display, as wide as it."] = "将你的施法条移动到个人显示下方，并与其同宽。"
L["Moves your swing timers under the personal display, as wide as it."] = "将你的攻击计时条移动到个人显示下方，并与其同宽。"
L["NPCs"] = "NPC"
L["New group"] = "新建分组"
L["New options"] = "新选项"
L["Next to the chat sits just above it and never covers the lines. The tooltip spot is the Tooltip handle you move with /dui unlock."] = "“聊天框旁”会位于聊天框正上方，绝不遮挡文字。“鼠标提示位置”是使用 /dui unlock 移动的“鼠标提示”拖动柄。"
L["No group"] = "无分组"
L["No words yet."] = "尚无词语。"
L["None: click the item"] = "无：点击物品"
L["Not attacking you"] = "未攻击你"
L["Not recommended for your class."] = "不推荐你的职业使用。"
L["Nothing, hide the tags"] = "不显示，隐藏标签"
L["Nudges it left or right from under the health bar, in pixels. In Design mode on the preview, drag it there."] = "从生命条下方左右微调，单位为像素。在设计模式的预览中可直接拖动。"
L["Nudges it up or down from under the health bar, in pixels. In Design mode on the preview, drag it there."] = "从生命条下方上下微调，单位为像素。在设计模式的预览中可直接拖动。"
L["Number format"] = "数字格式"
L["Numbers"] = "数字"
L["OPie"] = "OPie"
L["Object glow"] = "物体发光"
L["Object glow color"] = "物体发光颜色"
L["Object glow height"] = "物体发光高度"
L["Object glow in dungeons and raids"] = "地下城和团队副本中的物体发光"
L["Object glow in fights"] = "战斗中的物体发光"
L["Object glow look"] = "物体发光外观"
L["Objects glow in dungeons, raids and battlegrounds too."] = "地下城、团队副本和战场中的物体也会发光。"
L["Objects in the world"] = "世界中的物体"
L["Objects keep glowing while you're in a fight."] = "战斗中物体仍会发光。"
L["Objects your quests need light up."] = "任务需要的物体会发光。"
L["Off, the experience bar fades with the panel. On, it follows the settings here, attached or separate."] = "关闭时，经验条随信息面板一起淡出。开启时，经验条遵循此处的设置，无论附着还是独立显示。"
L["One color for each threat state, or a gradient for each. The gradients are also on General > Gradients."] = "每种威胁状态使用一种颜色，或每种状态使用渐变。渐变也可在“综合 > 渐变”中设置。"
L["One custom color, the accent, your class color, or your class's two colors as a gradient (from the Gradients page)."] = "一种自定义颜色、强调色、你的职业颜色，或将你的职业双色作为渐变（在渐变页面设置）。"
L["Only enemies"] = "仅敌人"
L["Only what you move here"] = "仅显示你移动到此处的物品"
L["Open"] = "打开"
L["Or pick one here to skip the click"] = "也可在此选择，省去点击"
L["Ore, herbs, chests, quest objects and your fishing bobber light up as you come near, dim from afar and bright once you can reach them. Ore and herbs only glow for a character who can gather them. This changes a few of the game's interact settings while it's on, and gives them back when it's off."] = "靠近矿脉、草药、宝箱、任务物体和你的鱼漂时它们会发光，远处较暗，进入可交互范围后变亮。矿脉和草药仅对可采集它们的角色发光。开启时会更改游戏的部分交互设置，关闭后恢复。"
L["Overpower"] = "压制"
L["Party members on a quest"] = "正在做同一任务的队员"
L["Past this the oldest line leaves early, so a big pull never floods the screen."] = "超过此数量时，最早的文字会提前消失，避免大量拉怪时刷满屏幕。"
L["Personal absorbs"] = "个人吸收护盾"
L["Personal display angle"] = "个人显示斜角"
L["Personal health bar"] = "个人生命条"
L["Personal incoming heals"] = "个人受到治疗"
L["Pick a page on the left to shape your interface. Changes apply as you make them."] = "在左侧选择一个页面来调整界面。更改会立即生效。"
L["Player, target, party and raid frames."] = "玩家、目标、小队和团队框体。"
L["Plays it in the middle of the screen. Also /dui glow."] = "在屏幕中央播放。也可使用 /dui glow。"
L["Plays it now; move to end it. Also /dui brew."] = "立即播放；移动即可结束。也可使用 /dui brew。"
L["Plays it now; move to end it. Also /dui fishing."] = "立即播放；移动即可结束。也可使用 /dui fishing。"
L["Plays it now; move to end it. Also /dui forge."] = "立即播放；移动即可结束。也可使用 /dui forge。"
L["Plays it now; move to end it. Also /dui sewing."] = "立即播放；移动即可结束。也可使用 /dui sewing。"
L["Plays it now; move to end it. Also /dui workshop."] = "立即播放；移动即可结束。也可使用 /dui workshop。"
L["Plus and minus signs"] = "正负号"
L["Preview the brew"] = "预览酿造效果"
L["Preview the fishing water"] = "预览钓鱼水面"
L["Preview the forge"] = "预览锻造效果"
L["Preview the object glow"] = "预览物体发光效果"
L["Preview the sewing"] = "预览裁缝效果"
L["Preview the workshop"] = "预览工程效果"
L["Profiles and sharing"] = "配置与分享"
L["Puts the zone you're in at the top of the quest log. When off, zones stay in the game's order."] = "将你当前所在区域置于任务日志顶部。关闭后区域按游戏原本顺序排列。"
L["PvE"] = "PvE"
L["Quest list"] = "任务列表"
L["Quest log opacity"] = "任务日志不透明度"
L["Quest log row height"] = "任务日志行高"
L["Quest log sort order"] = "任务日志排序"
L["Quest log text size"] = "任务日志文字大小"
L["RP"] = "RP"
L["RP PvP"] = "RP PvP"
L["Raid warnings"] = "团队警报"
L["Rarity colors"] = "品质颜色"
L["Recipe names take the rarity color of what they make. Off, they show how likely a skill-up is."] = "配方名称使用成品品质对应的颜色。关闭后，显示技能提升的几率。"
L["Recipe names take the rarity color of what they make. Off, they show how likely a skill-up is. The same switch sits beside the window's search."] = "配方名称使用成品品质对应的颜色。关闭后，显示技能提升的几率。窗口搜索框旁也有相同开关。"
L["Remove a character"] = "移除角色"
L["Reputation bars in their colors from the Gradients page, skill, PvP and currency bars in the accent's. When off, they're plain fills."] = "声望条使用渐变页面中的关系等级颜色，技能、PvP 和货币条使用强调色。关闭后为纯色填充。"
L["Rest the mouse on a frame and press a spell on your action bars: it goes to that player, with no click and no change of target. Works on anyone the mouse is on, in the world too, and with mouse buttons bound to your bars. This is the game's own setting."] = "将鼠标停在框体上并按动作条中的法术：法术会施放给该玩家，无需点击，也不会切换目标。适用于鼠标指向的任何单位，包括世界中的单位，绑定到动作条的鼠标按键也可以。这是游戏自带设置。"
L["Right stream"] = "右侧文字流"
L["Right-click to fish"] = "右键钓鱼"
L["Right-click: remove a character"] = "右键点击：移除角色"
L["Rows added after this version carry a NEW tag as you go through the pages. Search for new to list them all."] = "在此版本之后新增的设置行会在浏览页面时带有“新”标记。搜索 new 可列出全部新增项。"
L["Run this guide again from General > Home, or with %s."] = "可从“综合 > 首页”再次运行本向导，或使用 %s。"
L["Second chat panel"] = "第二个聊天面板"
L["Second panel"] = "第二个面板"
L["Second panel height"] = "第二个面板高度"
L["Second panel width"] = "第二个面板宽度"
L["Seconds a line stays before it fades."] = "每行文字淡出前停留的秒数。"
L["Select"] = "选择"
L["Sewing"] = "裁缝"
L["Short labels like Gear, Bags and Guild before each number. They drop off when the bar is too narrow."] = "在每个数字前显示“装备”“背包”“公会”等短标签。计量条过窄时标签会自动隐藏。"
L["Short tag"] = "短标签"
L["Show NEW on options added since"] = "显示自某版本后新增选项的“新”标记"
L["Show combat text"] = "显示浮动战斗信息"
L["Show in %s"] = "在 %s 中显示"
L["Show keeps it as a grayed icon or an empty bar, so you see what's missing. Hide shows it only while the buff is up, like Power Word: Shield."] = "“显示”会保留灰色图标或空计量条，便于看出缺少什么。“隐藏”仅在增益存在时显示，例如真言术：盾。"
L["Show keybind"] = "显示快捷键"
L["Show keybinds on icons"] = "在图标上显示快捷键"
L["Show leader tools"] = "显示队长工具"
L["Show progress in the quest log"] = "在任务日志中显示进度"
L["Show quest levels in the quest log"] = "在任务日志中显示任务等级"
L["Show quest tooltips"] = "显示任务鼠标提示"
L["Show the data bar"] = "显示数据栏"
L["Show with a target only for something you can attack: talking to a quest giver or a vendor leaves it faded."] = "仅对有目标且可攻击的对象显示：与任务发布者或商人对话时会保持淡化。"
L["Shows a handle on every spot. Drag to move it."] = "在每个位置显示拖动柄。拖动即可移动。"
L["Size of the quest names in the quest log on the map. Zone names, levels and progress follow it."] = "地图任务日志中任务名称的大小。区域名称、等级和进度会随之变化。"
L["Slanted mark"] = "斜角标记"
L["Spell hits"] = "法术命中"
L["Spell icon side"] = "法术图标侧"
L["Spotlight a quest's map icons on hover"] = "悬停时突出显示任务的地图图标"
L["Sweep: a ring with a light running round it. Angled frame: the Daylight UI shape on the ground with a light running round it. Daybreak: a beam of light leaning down onto the object. Sunrise: a low sun rising behind it."] = "扫光：圆环上有一道光环绕运行。斜角框：地面上显示 Daylight UI 形状，并有光环绕运行。破晓：一道光斜照到物体上。日出：一轮低日从物体后方升起。"
L["Swing timers on the personal display"] = "个人显示上的攻击计时条"
L["Switches off"] = "关闭"
L["Switches on"] = "开启"
L["Tabs"] = "标签页"
L["Text Slow Mode"] = "文字缓慢模式"
L["Text size for every chat window. Also in each chat tab's right-click menu."] = "所有聊天窗口的文字大小。也可在每个聊天标签的右键菜单中设置。"
L["Text size: %s"] = "文字大小：%s"
L["The bar along the bottom of the screen."] = "屏幕底部的数据栏。"
L["The bar's color when it's set to One color."] = "计量条设为“单一颜色”时使用的颜色。"
L["The bar's own color, so it can look unlike your player frame. Same as the Colors page follows the color every frame shares."] = "此计量条独立颜色，使其外观可不同于玩家框体。“与颜色页面相同”会跟随所有框体共享的颜色。"
L["The button's border lights up while its spell is queued, like Heroic Strike waiting for your next swing, or being cast."] = "法术排队时按钮边框会亮起，例如英勇打击等待下次挥击，或正在施放。"
L["The color of the lit border and the glow on an active spell."] = "启用中的法术亮起边框和光效的颜色。"
L["The crowd control alert's spot is kept by the game's Edit Mode, and you're on an Edit Mode layout of your own: move it there (Esc > Edit Mode)."] = "控制技能警报的位置由游戏的编辑模式保存，而你正在使用自己的编辑模式布局：请在那里移动它（Esc > 编辑模式）。"
L["The damage meter and minimap fade together (and the separate meter window, if used). So does the experience bar, unless you give it its own fade below."] = "伤害统计和微缩地图一起淡出（如果使用独立统计窗口也一样）。经验条也会一起淡出，除非在下方为其启用独立淡出。"
L["The game menu, addon list, macros, clock, loot, socketing, upgrading, the scrapper, the auction house, the professions book, the world map's frame, the breath bar, the crowd control alert. Also the game's own character and inspect windows while Daylight UI's are off."] = "游戏菜单、插件列表、宏、时钟、拾取、插槽、升级、分解机、拍卖行、专业书、世界地图框体、呼吸条、控制技能警报。以及 DaylightUI 对应窗口关闭时游戏自带的角色和观察窗口。"
L["The game's numbers that pop off what you hit."] = "从你击中的目标身上弹出的游戏数字。"
L["The game's other short messages: an interrupt, a dispel, an extra attack."] = "游戏的其他简短消息：打断、驱散、额外攻击等。"
L["The game's windows Daylight UI didn't rebuild. Rebuilt windows have their own switches under Extras."] = "Daylight UI 未重建的游戏窗口。已重建的窗口在“额外”中有各自开关。"
L["The healer's name beside each heal. In a fight the game can hide who it was, so your own heals may show your name too."] = "在每次治疗旁显示治疗者的名字。战斗中游戏可能隐藏施法者，因此你自己的治疗也可能显示你的名字。"
L["The health text shows at full health too. When off, it disappears while you're at full."] = "满生命值时也显示生命文字。关闭后，满血时文字会消失。"
L["The key that casts each spell, on its icon. It reads your action bars, so a spell on no bar shows none. Any icon can change this in the layout editor."] = "每个法术图标上显示施放该法术的按键。此信息读取自动作条，因此未放在动作条上的法术不会显示按键。任何图标都可在布局编辑器中单独更改。"
L["The key that casts this spell, read from your action bars."] = "施放此法术的按键，读取自动作条。"
L["The level in front of each quest name."] = "每个任务名称前的等级。"
L["The line along the top of the bar, in your accent color."] = "计量条顶部沿边缘的强调色线条。"
L["The look everything shares: the font, the accent color and the window background."] = "所有内容共用的外观：字体、强调色和窗口背景。"
L["The mob is attacking you."] = "怪物正在攻击你。"
L["The mob is in the fight, but attacking someone else."] = "怪物已进入战斗，但正在攻击其他人。"
L["The name of a buff as it lands on you or leaves."] = "增益施加到你身上或消失时显示其名称。"
L["The name of a debuff as it lands on you or leaves."] = "减益施加到你身上或消失时显示其名称。"
L["The order of the quests inside each zone in the quest log on the map."] = "地图任务日志中每个区域内任务的排列顺序。"
L["The short tag before these messages. Left empty it stays [%s]."] = "这些消息前的短标签。留空时仍显示为 [%s]。"
L["The spell being cast, as a small icon by the cast bar."] = "正在施放的法术，以施法条旁的小图标显示。"
L["The spell's icon at the end of your target's cast bar. Not inside the frame or sliding out under it."] = "目标施法条末端显示法术图标。不适用于框体内或从框体下方滑出的施法条。"
L["The text scrolling around your character. When off, none shows, the game's own included."] = "围绕角色滚动的战斗文字。关闭后不显示任何战斗文字，包括游戏自带的。"
L["The text scrolling around your character: hits you take, heals, procs and more."] = "围绕角色滚动的战斗文字：你受到的攻击、治疗、触发效果等。"
L["The ticks of a heal over time on you."] = "你身上持续治疗的每一跳。"
L["They come back if you log in on them."] = "登录这些角色后，它们会重新出现。"
L["Threat color style"] = "威胁颜色样式"
L["Threat: attacking you"] = "威胁：正在攻击你"
L["Threat: not attacking you"] = "威胁：未攻击你"
L["Tooltip on hover"] = "悬停时显示鼠标提示"
L["Top stream"] = "顶部文字流"
L["Tracking from a spell, like Find Minerals, comes back after you log out, change zones or die. Turn it off yourself and it stays off."] = "通过法术获得的追踪（例如寻找矿物）会在登出、切换区域或死亡后恢复。若你手动关闭，则保持关闭。"
L["Turns off"] = "关闭"
L["Unlock the chat: drag the tab row to move it, a corner to size it"] = "解锁聊天框：拖动标签行可移动，拖动角落可调整大小"
L["Used when Nameplates > Threat > Threat color style is Two-color gradient."] = "当“姓名板 > 威胁 > 威胁颜色样式”设为双色渐变时使用。"
L["What fades, and when"] = "哪些内容淡出，以及何时淡出"
L["What the bar shows. Pick None to leave a slot empty, and the others close up."] = "计量条显示的内容。选择“无”可保留空位，其他内容会依次收拢。"
L["What the tracker does when you enter a dungeon, raid or battleground. It comes back as you leave. This zone only keeps the quests for where you are; All over the list shows the rest until you leave."] = "进入地下城、团队副本或战场时追踪器的行为。离开后会恢复。仅当前区域：只保留你所在区域的任务；全部：离开前显示完整列表。"
L["What's new"] = "更新内容"
L["When off, nothing shows here, even for the messages that go to it."] = "关闭后此处不显示任何内容，即使有消息被分配到该文字流。"
L["Where along the health bar the health text sits."] = "生命文字在生命条上的位置。"
L["Where to start"] = "从哪里开始"
L["While it's off cooldown but you can't cast it: Overpower before a dodge, Riposte before a parry, Execute on a healthy target. Show leaves it dimmed. Hide keeps its gap: the other spells don't move."] = "当法术已冷却但暂时无法施放时：躲闪前的压制、招架前的还击、目标满血时的斩杀。“显示”会使其保持灰暗。“隐藏”会保留空位：其他法术不会移动。"
L["While you do engineering, two brass gears turn at the bottom of the screen with sparks where they meet, a brass tide shows how far through the batch you are, and your action bars and unit frames fade away. Move, target or cast something else and everything comes back; a fight brings it back at once."] = "进行工程学时，屏幕底部会有两个黄铜齿轮转动，接触处迸出火花，黄铜色进度带显示批量制作进度，同时动作条和单位框体淡出。移动、选中目标或施放其他法术时所有内容恢复；进入战斗会立即恢复。"
L["While you make potions, a flask sits at the bottom of the screen with bubbles rising past it, a green tide shows how far through the batch you are, and your action bars and unit frames fade away. Move, target or cast something else and everything comes back; a fight brings it back at once."] = "制作药水时，屏幕底部会有一只药瓶，气泡从旁边升起，绿色进度带显示批量制作进度，同时动作条和单位框体淡出。移动、选中目标或施放其他法术时所有内容恢复；进入战斗会立即恢复。"
L["While you smith, an anvil and hammer work along the bottom of the screen with sparks on each finished item, a molten tide shows how far through the batch you are, and your action bars and unit frames fade away. Move, target or cast something else and everything comes back; a fight brings it back at once."] = "进行锻造时，屏幕底部会出现铁砧和锤子，每完成一件物品都会迸出火花，熔岩色进度带显示批量制作进度，同时动作条和单位框体淡出。移动、选中目标或施放其他法术时所有内容恢复；进入战斗会立即恢复。"
L["While you tailor, a spool sits at the bottom of the screen, a tide of cloth with a growing seam shows how far through the batch you are, and your action bars and unit frames fade away. Move, target or cast something else and everything comes back; a fight brings it back at once."] = "进行裁缝时，屏幕底部会出现线轴，布匹色进度带与不断延伸的缝线显示批量制作进度，同时动作条和单位框体淡出。移动、选中目标或施放其他法术时所有内容恢复；进入战斗会立即恢复。"
L["While your line is in, calm water lies along the bottom of the screen with a little bobber on it, and your action bars and unit frames fade away. When a fish comes in the water splashes. Move, target or cast something else and everything comes back; a fight brings it back at once. The game doesn't tell addons when a fish bites, so the splash comes on the catch, not the bite."] = "鱼线入水后，屏幕底部会出现平静水面和一个小鱼漂，同时动作条和单位框体淡出。有鱼上钩时水面会溅起水花。移动、选中目标或施放其他法术时所有内容恢复；进入战斗会立即恢复。游戏不会在鱼咬钩时通知插件，因此水花出现在钓起时，而不是咬钩时。"
L["Who else gets the crown tab in a party, for the markers: the party's tank, or everyone. Ready check and the pull timer stay with the leader. In a raid only the leader and assists can mark."] = "在小队中谁还可以获得用于标记的王冠标签：小队的坦克，或所有人。就位确认和开怪倒计时仍仅限队长。在团队中只有团长和助理可以标记。"
L["Window: talking opens a window at the side. Immersive: the talk is a card on the right, the camera comes in over your shoulder and the rest of the UI fades away until you're done. Vendors and trainers stay a window."] = "窗口：对话会在侧边打开窗口。沉浸：对话会显示为右侧卡片，镜头拉近到肩后，界面其余部分淡出，直到对话结束。商人和训练师仍使用窗口。"
L["With Show under Buff missing, Hide makes it appear only when you need to cast it, like Battle Shout."] = "当“增益缺失”设为“显示”时，“隐藏”会使其仅在你需要施放时出现，例如战斗怒吼。"
L["With a fishing pole equipped, a quick right-click on the world casts Fishing. With no bait on the pole, the first click puts on the best bait in your bags. Holding the button still turns the camera, and clicking an NPC, an object or the bobber works as usual. Hold Shift, Ctrl or Alt to skip the cast."] = "装备鱼竿后，在世界中快速右键点击可施放钓鱼。若鱼竿上没有鱼饵，第一次点击会自动装上背包中最好的鱼饵。按住按钮仍可转动镜头，点击 NPC、物体或鱼漂照常有效。按住 Shift、Ctrl 或 Alt 可跳过施法。"
L["With the immersive look, the NPC's words appear letter by letter and the choices drift in after them. Click or press the accept key to see them all at once."] = "在沉浸外观下，NPC 的话语会逐字出现，选项随后浮现。点击或按接受键可立即全部显示。"
L["With the immersive look, the camera comes in over your shoulder and looks at the NPC while you talk, then goes back to how you had it. Not while mounted or in a fight."] = "在沉浸外观下，对话时镜头会拉近到肩后并看向 NPC，结束后恢复原样。骑乘或战斗中不生效。"
L["With the immersive look, the whole UI fades away while you talk, so only the NPC and the talk are left. A fight brings everything back at once."] = "在沉浸外观下，对话时整个界面会淡出，只留下 NPC 和对话内容。进入战斗会立即恢复所有界面。"
L["Within each zone. Most recent progress moves a quest and its zone to the top when a kill, item or objective counts. Nearest first looks again every few seconds as you move, never in a fight or a dungeon. Nothing moves in a fight."] = "在每个区域内。最近有进展的任务及其区域会在击杀、拾取或目标计数时移到顶部。“最近优先”会随你移动每隔几秒重新排序，战斗中或地下城内不会重排。战斗中任何内容都不会移动。"
L["Words and phrases to hide"] = "要隐藏的词语和短语"
L["Workshop"] = "工程"
L["Writes zone names in capital letters. When off, they're written as the game writes them."] = "将区域名称写成大写字母。关闭后按游戏原本的大小写显示。"
L["Yell"] = "大喊"
L["You can also drag the panel's bottom-right corner to size it."] = "也可以拖动面板右下角调整大小。"
L["Your accent color, or a color that says what the object is: copper for ore, green for herbs, gold for quests, blue for chests."] = "使用你的强调色，或使用表示物体类型的颜色：矿脉为铜色、草药为绿色、任务物体为金色、宝箱为蓝色。"
L["Your bobber lights up while your line is in the water."] = "鱼线入水时你的鱼漂会发光。"
L["Your frames"] = "你的框体"
L["Your health on the display. Turn it off to keep just your power bar. Needs the power bar on."] = "个人显示上的生命值。关闭后仅保留能量条。需要开启能量条。"
L["Your health written on the personal display's health bar."] = "写在个人显示生命条上的生命值。"
L["Your mana, rage or energy under the health bar. Needs the health bar on."] = "生命条下方的法力、怒气或能量。需要开启生命条。"
L["Your mana, rage or energy written on the personal display's power bar."] = "写在个人显示能量条上的法力、怒气或能量。"
L["Your setup"] = "你的设置"
L["Your target's cast bar fills from the right. Not inside the frame or sliding out under it."] = "目标施法条从右向左填充。不适用于框体内或从框体下方滑出的施法条。"
L["Zone names in capitals in the quest log"] = "任务日志中的区域名称大写"
L["another frame adds it to this group, or takes it out"] = "另一个框体会将它加入此分组，或从中移除"
L["Minimap box"] = "微缩地图框"
L["The box around the minimap, with the damage meter and data texts in it. The experience bar and the meters' own windows keep the General page's background."] = "微缩地图周围的框，包含伤害统计和数据文字。经验条和统计自身的窗口沿用“综合”页面的背景。"
L["Damage meter side"] = "伤害统计位置"
L["Which side of the minimap the damage meter slides out of, with the threat meter beside it. Automatic picks the side toward the middle of the screen, so it follows when you move the panel."] = "伤害统计从微缩地图哪一侧滑出，威胁统计会显示在其旁边。“自动”会选择朝向屏幕中央的一侧，因此移动面板后也会跟随。"
L["Minimap box border"] = "微缩地图框边框"
L["A border and shadow around the minimap's box."] = "为微缩地图框添加边框和阴影。"
