L["Top stream most lines at once"] = "顶部文字流最大行数"
L["Slant leans along the UI's angle. Rise and Fall go straight. Arc curves away from you. Fountain sprays both ways. Stack stays put, and new lines push the older ones up."] = "斜角：沿界面斜角倾斜。上升和下落：垂直移动。弧形：向你侧方弯曲飞出。喷泉：向两侧喷出。堆叠：位置固定，新行会把旧行向上推。"
L["Which side of the spot the lines line up on."] = "文字从该位置的哪一侧对齐。"
