-- From the same player: lines new in 1.6.2 and 1.6.3.
L["A border and shadow around the experience bar's box and the threat meter's window."] = "为经验条框体和威胁统计窗口添加边框与阴影。"
L["A profile from the Profiles page, used as it is."] = "直接使用“配置”页面中的现有配置。"
L["A second bar above it."] = "在其上方显示第二条动作条。"
L["A small badge at the foot of the portrait"] = "头像底部的小徽章"
L["A small button at the top-right of the chat for the game's chat menu: pick the language you speak, emotes, say, yell and more."] = "聊天框右上角的小按钮，可打开游戏聊天菜单：选择语言、表情、说话、大喊等。"
L["A whole look at once. Daylight leans the numbers along the UI's slant and lights up crits. Calm is small and slow. Punchy is big and flung out both ways. Classic curves like the game's own. Changing a row below makes it Custom."] = "一次套用整套外观。Daylight 会沿界面斜角显示数字并高亮爆击。Calm 小而缓慢。Punchy 较大并向两侧飞出。Classic 则像游戏原版一样弯曲。更改下方任意选项后会变为“自定义”。"
L["Action Bar 1 in %s"] = "%s 中的动作条 1"
L["Addons made by other people on top of DaylightUI: plugins with features of their own, and profile packs with ready-made setups."] = "基于 DaylightUI 制作的第三方功能扩展，以及包含预设方案的配置包。"
L["Alerts & Loot Won"] = "提示与获得的战利品"
L["Always shown"] = "始终显示"
L["Amounts shortened (12.3K) or in full (12,345), on both meters, the breakdown and reports."] = "两个统计、明细和报告中的数值显示为缩写（12.3K）或完整形式（12,345）。"
L["Apply opacity to every window"] = "将透明度应用到所有窗口"
L["At the mouse"] = "鼠标位置"
L["Automatic is your Appearance font. The sample above shows it at once; the numbers in the world change after you restart the game."] = "“自动”使用你在外观页面选择的字体。上方示例会立即变化；世界中的数字需要重启游戏后才会改变。"
L["Automatic uses your Appearance font."] = "“自动”使用你在外观页面选择的字体。"
L["Bars and your frame fade after a fight."] = "战斗结束后动作条和你的框体淡出。"
L["Battle.net Logins"] = "战网登录提示"
L["Beside the meter"] = "统计旁"
L["Brings in the pack's newer version of this profile: its settings and frame positions replace yours. Your Edit Mode layout stays as it is."] = "导入配置包中此配置的新版设置和框体位置，覆盖当前内容；保留编辑模式布局。"
L["By zone"] = "按区域"
L["By zone: green in friendly lands, amber in contested ones, red in hostile ones, blue in sanctuaries. One color: always the color below."] = "按区域：友方领地为绿色，争夺中为琥珀色，敌方领地为红色，圣殿为蓝色。单色：始终使用下方颜色。"
L["CC Alert"] = "控制警报"
L["Changed"] = "改动"
L["Chat input text size"] = "聊天输入框文字大小"
L["Chat menu button"] = "聊天菜单按钮"
L["Chat menu: emotes and languages"] = "聊天菜单：表情与语言"
L["Chat menu: emotes and languages (speaking %s)"] = "聊天菜单：表情与语言（当前语言：%s）"
L["Chat tab text size"] = "聊天标签文字大小"
L["Clock color"] = "时钟颜色"
L["Coordinates color"] = "坐标颜色"
L["Coordinates text size"] = "坐标文字大小"
L["Custom active border and glow color"] = "自定义启用边框与光效颜色"
L["Custom guild color"] = "自定义公会颜色"
L["Custom job color"] = "自定义 NPC 职能颜色"
L["Draining line"] = "流失线"
L["Draws the turning map a little closer, so its corners never go empty when you face a diagonal. Off: the full view, with the corners cut."] = "将旋转地图稍微拉近，使斜向面对时四角不会空白。关闭后显示完整视图，但四角会被裁掉。"
L["Each item in the loot window flashes in its color as the light running down it passes, and again as you take it. When off, the light still runs and the items still ease in, without the flash."] = "拾取窗口中，光扫过每件物品时它会按品质颜色闪烁，拾取时也会再次闪烁。关闭后，扫光和物品渐入仍会保留，但不闪烁。"
L["Error Messages"] = "错误提示"
L["Everything stays on screen."] = "所有内容始终显示在屏幕上。"
L["Fill the corners while turning"] = "转向时补全四角"
L["Fixed"] = "修复"
L["Framerate color"] = "帧数颜色"
L["Gives the box you type in its own text size, set in the row below. When off, it matches the messages' text size."] = "为输入框单独设置文字大小，在下方一行调整。关闭时与消息文字大小一致。"
L["Gives the second chat panel its own background opacity, set in the row below. When off, it's as see-through as the main chat panel."] = "为第二聊天面板单独设置背景不透明度，在下方一行调整。关闭时与主聊天面板透明程度相同。"
L["Gone until a fight or a change."] = "进入战斗或发生变化前隐藏。"
L["Guild names in the player's class color, plain white, or one color."] = "公会名使用玩家职业颜色、纯白色或统一颜色。"
L["Guild size"] = "公会名大小"
L["How big the coordinates are."] = "坐标文字的大小。"
L["How big the zone name is."] = "区域名称文字的大小。"
L["How long each buff and debuff has left, on its icon."] = "增益和减益图标上显示剩余时间。"
L["How see-through every window and panel is: bags, character, spellbook, NPC, group finder, the game's windows we restyle, chat, the info panel, the quest box and the buff bars. One with a separate opacity on its own page keeps that."] = "所有窗口和面板的透明程度：背包、角色、法术书、NPC、队伍查找器、由 DaylightUI 重新设计样式的游戏窗口，以及聊天、信息面板、任务框和增益条。若某个窗口在自己的页面单独设置了透明度，则保留该设置。"
L["How see-through the box around the minimap (and the damage meter in it) is: 0 is fully see-through."] = "微缩地图外框（以及框内伤害统计）的透明程度：0 为完全透明。"
L["How see-through the experience bar's box and the meters' own windows are."] = "经验条框体以及统计自身窗口的透明程度。"
L["How solid the second chat panel's background is: 0 is fully see-through."] = "第二聊天面板背景的实心程度：0 为完全透明。"
L["How thick the Flat border is. The Daylight frame follows the border size on General > Appearance."] = "Flat 边框的粗细。Daylight 边框使用“常规 > 外观”中的边框宽度。"
L["Immersive"] = "沉浸"
L["In a group, colors a mob by who it's attacking; solo plates never change. Red while it's attacking you, yellow while it's attacking someone else, orange when it's about to switch."] = "在队伍中，根据怪物当前攻击的对象改变姓名板颜色；单人时姓名板不变。攻击你时为红色，攻击他人时为黄色，即将切换目标时为橙色。"
L["In the tooltip spot"] = "鼠标提示位置"
L["Its own section in the list on the left, under Plugins."] = "在左侧列表“扩展”下显示独立分类。"
L["Its ready-made profiles are on the Profiles page and in the setup guide."] = "其预设配置显示在“配置”页面和设置向导中。"
L["Its tooltips in the Daylight UI frame, in your background opacity. Its layout, words and stat colors stay."] = "将其鼠标提示套用 DaylightUI 边框，并使用你的背景不透明度。其布局、文字和属性颜色保持不变。"
L["Job"] = "职能"
L["Job color"] = "职能颜色"
L["Job size"] = "职能文字大小"
L["Just your main bar."] = "仅显示主动作条。"
L["Large"] = "大"
L["Loot Rolls"] = "战利品掷骰"
L["Loot Window"] = "拾取窗口"
L["Loot window"] = "拾取窗口"
L["Loot window flash"] = "拾取窗口闪光"
L["Lost"] = "失去仇恨"
L["Medium"] = "中"
L["Meter numbers"] = "统计数字"
L["NPC jobs in soft tan, plain white, or one color."] = "NPC 职能文字使用柔和棕色、纯白色或统一颜色。"
L["Next to the chat"] = "聊天框旁"
L["On you"] = "在你身上"
L["One row"] = "一行"
L["Out of combat"] = "非战斗时"
L["Paging: this bar can show another page of buttons while you're in a stance or form, or while you hold a key. Pick a spare page to fill it with spells of its own."] = "分页：该动作条可在姿态、形态或按住某个按键时显示另一页按钮。选择一个备用页面，并放入该页自己的法术。"
L["Puts this font on the game's own text as well: menus, tooltips, quest text, popups, nameplate names. Sizes and outlines stay the game's."] = "同时将此外观字体用于游戏自带文字：菜单、鼠标提示、任务文本、弹窗和姓名板名字。字号和描边仍保持游戏原样。"
L["QuestieDB isn't on, so the arrow is left out: it needs QuestieDB to know where each mob is."] = "QuestieDB 未开启，因此不显示任务箭头：它需要 QuestieDB 来定位每个怪物。"
L["Replaces the game's damage meter window. The tab on the panel's edge, on the meter's side, also shows or hides it."] = "替换游戏自带的伤害统计窗口。面板边缘、统计一侧的标签也可显示或隐藏它。"
