L["The NPC job's color when Job color is One color."] = "NPC 职能颜色设为“单色”时使用的颜色。"
L["The border's color. The border still lights up in your accent color while you drag a corner to size the chat."] = "边框颜色。拖动聊天框角落调整大小时，边框仍会以强调色亮起。"
L["The color of the clock."] = "时钟文字的颜色。"
