L["The color of the framerate."] = "帧数文字的颜色。"
L["The edge round every chat panel: the main one, the second one and a chat window pulled out on its own. As the chat style gives the Daylight chat box the Daylight frame and the Classic style a thin line. Daylight is the warm band inside a dark outline, Flat a plain line."] = "每个聊天面板的边框：主面板、第二面板以及单独拉出的聊天窗口。聊天样式为 Daylight 时聊天框使用 Daylight 边框，Classic 时使用细线。Daylight 是深色轮廓内的暖色带，Flat 是普通细线。"
L["The experience bar's box, and the meters' and threat meter's own windows. The minimap's box has its own on the Minimap page. At 0 opacity the boxes disappear; the bars still show."] = "经验条框体，以及统计和威胁统计自己的窗口。微缩地图框在“微缩地图”页面单独设置。不透明度为 0 时框体会消失，但计量条仍会显示。"
L["The guild name's color when Guild color is One color."] = "公会名颜色设为“单色”时使用的颜色。"
L["The size of the words on the chat tabs."] = "聊天标签上文字的大小。"
L["The size of what you type in the chat box."] = "聊天输入框内文字的大小。"
L["The small tab on the meter's outer edge (it shows while the mouse is near) slides it out or back by hand."] = "统计外侧的小标签（鼠标靠近时显示）可手动将统计滑出或收回。"
L["The zone name's color when Zone name color is One color."] = "区域名称颜色设为“单色”时使用的颜色。"
L["Their color when Active border and glow color is set to Your own color."] = "“启用边框与光效颜色”设为“自定义颜色”时使用的颜色。"
L["Ticket Status"] = "客服支持状态"
L["Time left position"] = "剩余时间位置"
L["Top Center Status"] = "顶部中央状态"
L["Trade (Local)"] = "交易（本地）"
L["Trade (Services)"] = "交易（服务）"
L["Turns off every separate background opacity, so every window and panel matches Window background opacity."] = "关闭所有单独设置过的背景不透明度，让每个窗口和面板都与“窗口背景不透明度”一致。"
L["Two rows"] = "两行"
L["Two rows and side bars"] = "两行和侧边动作条"
L["Under the meter it rises out of the damage meter's bottom inside the panel, as wide as the meter, and the meter's rows make room. Docked (beside or under), it shows only while the damage meter is open. Its own window goes anywhere: move it in unlock mode (/dui unlock) and drag its corner to size it."] = "位于统计下方时，它会从面板内伤害统计的底部升起，与统计同宽，统计的行会为其让出空间。停靠（在旁或在下方）时，仅当伤害统计打开时显示。独立窗口可放到任意位置：在解锁模式（/dui unlock）中移动，拖动角落调整大小。"
L["When you're away"] = "离开时"
L["Where the time sits: on the icon's top edge, across its middle, or on its bottom edge."] = "剩余时间的位置：图标顶部边缘、中间或底部边缘。"
L["Which end of the cast bar it sits at. In Design mode on the preview, drag it there."] = "它位于施法条的哪一端。在设计模式预览中可直接拖到该位置。"
L["Who's closest to pulling your target, in a small window that slides out beside the damage meter, along its bottom, or anywhere on its own."] = "显示谁最接近对你的目标造成仇恨，可从小窗口在伤害统计旁、其底部或任意独立位置滑出。"
L["Your class's pick (%s)"] = "你职业的推荐（%s）"
L["Zone name text size"] = "区域名称文字大小"
L["[G] for General, [T] for Trade, [G] for guild (in guild green), [P] for party, [S] for say, [Y] for yell, [W] for whispers. Lines already in chat stay as they were. A chat tab's Show window sets your own tags."] = "[G] 综合、[T] 交易、[G] 公会（公会绿）、[P] 小队、[S] 说、[Y] 大喊、[W] 密语。聊天中已有的行保持原样。聊天标签的“显示窗口”可设置你自己的标签。"

-- From the same player: lines new in 1.6.4 and 1.6.5.1 (the data bar page).
L["%d bar"] = "%d 条"
L["%d bars"] = "%d 条"
L["%d buff"] = "%d 个增益"
L["%d buffs"] = "%d 个增益"
L["%d cooldown"] = "%d 个冷却"
L["%d cooldowns"] = "%d 个冷却"
L["%d utility"] = "%d 个功能技能"
