L["03:27 PM"] = "下午 03:27"
L["03:27:32 PM"] = "下午 03:27:32"
L["A copy of the profile you're using, used by the talent set you're in from now on."] = "复制当前使用的配置，并从现在起用于当前天赋组。"
L["A group you deleted comes back, with its items."] = "已删除的分组会连同其中的物品一起恢复。"
L["A layout string from the game's own Cooldown Manager (its Export), a guide or another UI. It becomes a new profile, used by the talent set you're in."] = "来自游戏自带冷却管理器（其“导出”功能）、攻略或其他界面的布局字符串。它会成为一个新配置，并用于当前天赋组。"
L["A new group starts empty. Hold Shift while dragging an item to see your empty groups in the bag, and drop it on one's name. Or click the search beside it here to fill it by itself."] = "新分组初始为空。拖动物品时按住 Shift 可在背包中看到空分组，再把物品拖到分组名称上；也可点击此处分组旁的搜索按钮自动填充。"
L["A new name for the profile you're using."] = "为当前使用的配置输入新名称。"
L["A small headset button at the top-right of the chat. It opens the game's Chat Channels window, where you join voice chat with your party, raid or a channel."] = "聊天框右上角的小耳机按钮，可打开游戏的“聊天频道”窗口，在其中加入小队、团队或频道语音聊天。"
L["A soft chime when talents are applied, a talent set is switched, a spell is learned at a trainer or a letter is sent."] = "天赋应用、切换天赋组、在训练师处学习法术或寄出信件时播放轻柔提示音。"
L["Ambience"] = "环境音"
L["An empty profile, used by the talent set you're in."] = "一个空配置，供当前天赋组使用。"
L["Another swing bar whose look to copy onto the one picked in Settings for."] = "将另一条攻击计时条的外观复制到“设置对象”中选中的计时条。"
L["Bar background opacity"] = "计量条背景不透明度"
L["Best in your bags"] = "背包中最佳"
L["Boss color"] = "首领颜色"
L["Boss health bars in the color below, so they stand out in a crowd. Threat colors still show over it."] = "首领的生命条使用下方颜色，使其在人群中更醒目。威胁颜色仍会覆盖显示。"
L["Boss"] = "首领"
L["Bosses in their own color"] = "首领使用独立颜色"
L["Bring back a group"] = "恢复分组"
L["By difficulty: the game's gray, green, yellow, orange and red for how hard the enemy is for your level. Or always white, your accent color, or one color you pick. ?? stays red."] = "按难度：使用游戏根据敌人相对你等级的难度显示灰色、绿色、黄色、橙色和红色。也可始终为白色、强调色或你选择的单一颜色。?? 等级仍显示红色。"
L["By threat (orange, then red)"] = "按威胁值（先橙色，后红色）"
L["Can't interrupt gradient"] = "无法打断渐变"
L["Caster color"] = "施法者颜色"
L["Caster"] = "法系"
L["Casters in their own color"] = "施法者使用独立颜色"
L["Class-colored names and numbers"] = "名字与数字使用职业颜色"
L["Click: mute all sound"] = "点击：全部静音"
L["Click: sound back on"] = "点击：恢复声音"
L["Click: use (after combat)"] = "点击：使用（战斗后）"
L["Click: use"] = "点击：使用"
L["Confirmations"] = "确认提示"
L["Cooking"] = "烹饪"
L["Copy %s"] = "复制 %s"
