L["Custom level color"] = "自定义等级颜色"
L["Custom threat % color"] = "自定义威胁值 % 颜色"
L["Data bar left slot 1"] = "数据条左侧栏位 1"
L["Data bar left slot 2"] = "数据条左侧栏位 2"
L["Data bar left slot 3"] = "数据条左侧栏位 3"
L["Data bar left slot 4"] = "数据条左侧栏位 4"
L["Data bar middle slot"] = "数据条中间栏位"
L["Data bar right slot 1"] = "数据条右侧栏位 1"
