L["Data bar right slot 4"] = "数据条右侧栏位 4"
L["Delete profile"] = "删除配置"
L["Deletes the profile you're using, for every character of this class. Talent sets that used it have none."] = "删除当前使用的配置，并作用于该职业的所有角色。使用过它的天赋组将没有配置。"
L["Detach as group"] = "整组分离"
L["Detach the main hand bar"] = "分离主手计时条"
L["Detach the main hand, off hand or ranged bar from the others to move and size it on its own."] = "将主手、副手或远程攻击计时条从整组中分离，以便单独移动和调整大小。"
