L["Detached bars"] = "已分离的计时条"
L["Dialog"] = "对话"
L["Each bar's hand (or the queued attack) and the time to the next swing, written on the bar. A bar detached on its own has its own."] = "每条计时条上显示当前手（或排队攻击）以及距下次挥击的时间。单独分离的计时条使用自己的设置。"
L["Each bar's name and number in that player's class color."] = "每条统计条上的名字和数字使用该玩家的职业颜色。"
L["Effects"] = "音效"
L["Enchanting"] = "附魔"
L["Equipped"] = "已装备"
L["Gives the window its own background opacity, set in the row below. When off, it's as see-through as the info panel's boxes (General page)."] = "为该窗口单独设置背景不透明度，在下方一行调整。关闭时与信息面板框体的透明程度一致（综合页面）。"
L["Group name color"] = "小队成员姓名颜色"
L["Group names"] = "小队成员姓名"
L["Hide friendly plates in instances"] = "在副本中隐藏友方姓名板"
L["How big the number is. 0 fits it to the tag."] = "数字大小。设为 0 时自动适配标签。"
L["How dungeons, quests and zones are listed when you list yourself: lowest level first, or A to Z. The Sort button on that page changes it too."] = "发布组队信息时，地下城、任务和区域的排列方式：按等级从低到高，或按名称 A 到 Z。该页面的“排序”按钮也可切换。"
L["How see-through the experience bar's box and the meters' own windows are (a meter window can have its own, on its page)."] = "经验条框体以及各统计自身窗口的透明程度（统计窗口可在自己的页面单独设置）。"
L["How solid the empty part and outline of each bar are. At 0 only the colored bars show."] = "每条计量条空白部分和轮廓的实心程度。设为 0 时只显示彩色计量条。"
L["How solid the window's background is: 0 is fully see-through, leaving only the bars."] = "窗口背景的实心程度：0 为完全透明，仅保留计量条。"
L["How tall the tag is. 0 matches the name tab."] = "标签高度。设为 0 时与姓名标签一致。"
