L["Import a Cooldown Manager layout"] = "导入冷却管理器布局"
L["Import a layout"] = "导入布局"
L["Imported the Cooldown Manager profile %s, used by talent set %d."] = "已导入冷却管理器配置 %s，供天赋组 %d 使用。"
