L["Loot window animations"] = "拾取窗口动画"
L["Master"] = "主音量"
L["Mobs that use mana in the color below: the ones to interrupt or pull out of line of sight. A boss or rare keeps its own color. Threat colors still show over it."] = "使用法力的怪物显示为下方颜色：这些怪物通常需要打断或拉出视线。首领或稀有怪仍使用自己的颜色。威胁颜色仍会覆盖显示。"
L["Music"] = "音乐"
L["Muted"] = "已静音"
L["NPC"] = "NPC"
L["Name for the copy:"] = "副本名称："
L["Name for the new profile:"] = "新配置名称："
L["Names of the players in your party or raid in their own color."] = "小队或团队成员的名字使用各自的颜色。"
L["No Hearthstone in your bags."] = "背包中没有炉石。"
L["No change"] = "不更改"
L["No plates over friendly players and NPCs in dungeons, raids, battlegrounds and arenas. They come back as you leave."] = "在地下城、团队副本、战场和竞技场中不显示友方玩家和 NPC 的姓名板，离开后恢复。"
L["Now"] = "当前"
L["Nudges the tag sideways. Only while it sits on the frame."] = "左右微调标签位置。仅在标签位于框体上时有效。"
L["Nudges the tag up or down. Only while it sits on the frame."] = "上下微调标签位置。仅在标签位于框体上时有效。"
L["On its own, the tag leaves the frame and you can move it anywhere in unlock mode, like near the middle of the screen."] = "独立显示时，标签会离开框体；可在解锁模式中将其移动到任意位置，例如屏幕中央附近。"
L["On the frame"] = "在框体上"
L["Only when detached as a group. Hung under the player frame, the bars match its width."] = "仅在整组分离时有效。挂在玩家框体下方时，计时条会与框体同宽。"
L["Only when detached as a group. Main hand at the bottom, the others above it."] = "仅在整组分离时有效。主手计时条位于底部，其他计时条在其上方。"
L["Only when detached as a group."] = "仅在整组分离时有效。"
L["Only when detached on its own."] = "仅在单独分离时有效。"
L["Opens the layout editor right on your screen, on the profile your talent set uses: pull spells up from the tray, drag them where you want them, hook them together, click one to change it. Type /cdm to open it any time. Out of combat only."] = "直接在屏幕上打开当前天赋组所用配置的布局编辑器：从托盘中拉出法术，拖到想要的位置并连接起来，点击某个法术即可修改。随时输入 /cdm 打开。仅限战斗外使用。"
L["Paste a layout string from the game's Cooldown Manager (its Export), a guide or another UI (Ctrl+V). It becomes a new profile, used by talent set %d."] = "粘贴来自游戏自带冷却管理器（其“导出”功能）、攻略或其他界面的布局字符串（Ctrl+V）。它会成为一个新配置，供天赋组 %d 使用。"
L["Paste a string"] = "粘贴字符串"
L["Players with a Total RP 3 profile show by their roleplay name on unit frames, nameplates, the threat meter and windows. Each frame's First and last names switch still picks first name or full name."] = "拥有 Total RP 3 角色扮演资料的玩家会在单位框体、姓名板、威胁统计和窗口中显示角色扮演姓名。各框体的“名和姓”开关仍可选择只显示名字或完整姓名。"
L["Quest log order"] = "任务日志顺序"
L["Rare and rare elite health bars in the color below. Threat colors still show over it."] = "稀有和稀有精英的生命条使用下方颜色。威胁颜色仍会覆盖显示。"
L["Rare color"] = "稀有颜色"
L["Rare"] = "稀有"
L["Rares in their own color"] = "稀有怪使用独立颜色"
L["Remove group from layout"] = "从布局中移除分组"
L["Rename %s"] = "重命名 %s"
L["Rename profile"] = "重命名配置"
L["Right-click: pick a channel"] = "右键点击：选择频道"
L["Right-click: pick a profession"] = "右键点击：选择专业"
L["Roleplay names"] = "角色扮演姓名"
L["Second panel hides"] = "第二面板隐藏时机"
L["Show empty groups"] = "显示空分组"
L["Sort activities by"] = "活动排序方式"
L["Special mobs"] = "特殊怪物"
L["Tailoring"] = "裁缝"
L["Takes every spell of this group out of the layout; they go back to the tray."] = "将此分组中的所有法术从布局中移除，并放回托盘。"
L["Takes the bars out from under the player frame so you can move them together (/dui unlock); they slide out of their own box. When off, they hang under the player frame, under the cast bar while it hangs there, even with the cast bar detached."] = "将计时条从玩家框体下方移出，以便整组移动（/dui unlock）；它们会从自己的框中滑出。关闭时，计时条挂在玩家框体下方；施法条挂在那里时则挂在施法条下方，即使施法条已分离也是如此。"
L["The color of your party and raid members' names."] = "小队和团队成员姓名的颜色。"
L["The hand (or the queued attack, or the range) written on the bar. Only when detached on its own."] = "计时条上显示当前手（或排队攻击，或距离）。仅在单独分离时有效。"
L["The hand and time on the bar. Only when detached on its own."] = "计时条上显示当前手和时间。仅在单独分离时有效。"
L["The health bar's color on a boss."] = "首领生命条的颜色。"
L["The health bar's color on a mob that uses mana."] = "使用法力的怪物生命条颜色。"
L["The health bar's color on a rare."] = "稀有怪生命条的颜色。"
L["The layout: %s."] = "布局：%s。"
L["The level's color when Level color is One color."] = "等级颜色设为“单色”时使用的颜色。"
L["The light running down the loot window as it opens, items easing in behind it, the shine on rare items, taken items rising away, and the window fading in and out. When off, the loot window opens and closes with none of them."] = "拾取窗口打开时扫过一道光，物品随后渐入；稀有物品会闪光，拾取的物品向上离开，窗口也会淡入淡出。关闭后，拾取窗口打开和关闭时不再播放这些动画。"
L["The number's color when Threat % color is One color."] = "威胁值 % 颜色设为“单色”时使用的颜色。"
L["The number's color. By threat goes orange as you get close to pulling, red once it's on you."] = "数字颜色。“按威胁值”会在接近 OT 时变为橙色，仇恨落到你身上后变为红色。"
L["The small framed box behind the number. When off, only the number shows."] = "数字后方的带框小背景。关闭时只显示数字。"
L["The spell name and time on your target's cast bar. Not inside the frame: there it's Text size inside the frame."] = "目标施法条上的法术名称和时间。位于框体内时不使用此项，而使用框体内的“文字大小”。"
L["The spell name and timer while the bar sits inside the target frame, even past the power bar's height. 0 sizes them to fit the power bar."] = "施法条位于目标框体内时的法术名称和计时，即使超出能量条高度也显示。设为 0 时会调整为适应能量条。"
L["The tag's end is angled like the frame. When off, both ends are straight."] = "标签末端像框体一样倾斜。关闭时两端均为直角。"
L["The time to the next swing, written on the bar. Only when detached on its own."] = "计时条上显示距下次挥击的时间。仅在单独分离时有效。"
L["The weapon's picture at the start of the bar. Only when detached on its own."] = "计时条起点显示武器图标。仅在单独分离时有效。"
L["Threat % color"] = "威胁值 % 颜色"
L["Threat % size"] = "威胁值 % 大小"
L["Threat %"] = "威胁值 %"
L["Threat color"] = "威胁值颜色"
L["Threat color: white, turning orange or red only when the enemy needs you, as with the breathing pulse. Or always white, your accent color, or one color you pick."] = "威胁值颜色：白色，仅在敌人需要你处理时变为橙色或红色，与呼吸闪烁一致。也可始终为白色、强调色或你选择的单一颜色。"
L["Threat tag angled end"] = "威胁值标签斜角末端"
L["Threat tag box"] = "威胁值标签框体"
L["Threat tag color"] = "威胁值标签颜色"
L["Threat tag height"] = "威胁值标签高度"
L["Threat tag left / right"] = "威胁值标签左右偏移"
L["Threat tag position"] = "威胁值标签位置"
L["Threat tag text size"] = "威胁值标签文字大小"
L["Threat tag up / down"] = "威胁值标签上下偏移"
L["Threat tag width"] = "威胁值标签宽度"
L["Total"] = "总计"
L["Tracked first"] = "已追踪优先"
L["Voice chat and channels"] = "语音聊天与频道"
L["Voice chat button"] = "语音聊天按钮"
L["Volume"] = "音量"
L["What the angled tab in the middle of the bar shows. Pick None to leave the tab out."] = "设置数据条中央斜角标签显示的内容。选择“无”可隐藏该标签。"
L["What this slot on the left side of the data bar shows, counted from the screen's edge."] = "设置数据条左侧栏位显示的内容；栏位从屏幕边缘向内计数。"
L["What this slot on the right side of the data bar shows, counted from the screen's edge."] = "设置数据条右侧栏位显示的内容；栏位从屏幕边缘向内计数。"
L["Wheel: louder or quieter"] = "滚轮：调高或调低音量"
L["When the second panel gets out of the way, on its own: keep a loot or combat log panel up while the main chat floats away, or the other way round. Idle time and how long messages stay are the main chat's."] = "第二面板独立隐藏的时机：可在主聊天框淡出时保留拾取或战斗日志面板，也可反过来。空闲时间和消息保留时长沿用主聊天框的设置。"
L["Which profile this talent set uses. Your class's profiles show here, from every character of this class."] = "当前天赋组使用哪个配置。此处显示该职业所有角色的配置。"
L["While swinging: each bar only while its swing runs, gone between swings. In combat: all your bars while you're fighting. A bar detached on its own has its own."] = "挥击时：每条计时条仅在对应挥击进行时显示，挥击之间隐藏。战斗中：战斗期间显示所有计时条。单独分离的计时条使用自己的设置。"
L["While swinging: only while its swing runs. In combat: while you're fighting. Only when detached on its own."] = "挥击时：仅在对应挥击进行时显示。战斗中：战斗期间显示。仅在单独分离时有效。"
L["You're on talent set %d, which has no profile. New and Import make one for it."] = "当前为天赋组 %d，但尚未指定配置。使用“新建”或“导入”为它创建一个配置。"
L["You're on talent set %d. The buttons below work on its profile, %s."] = "当前为天赋组 %d。下方按钮作用于其配置 %s。"
L["Your frame's own health color, so it can look unlike the others. Same as the Colors page follows the color every frame shares; Daylight gradient is the logo's blue to orange; Accent color follows your accent on General > Appearance, gradient included."] = "玩家框体独立生命颜色，使其可与其他框体不同。“与配色页面相同”会跟随所有框体共用的颜色；Daylight 渐变为标志的蓝到橙；强调色跟随“综合 > 外观”中的强调色，包括渐变。"
L["Your groups with nothing in them always show in the bag. When off, they show only while you hold Shift with an item on the cursor."] = "空分组始终显示在背包中。关闭后，仅当鼠标持有物品并按住 Shift 时显示。"
L["Your main hand's bar. Turn it off to keep only your other bars, like a hunter's ranged bar."] = "你的主手计时条。关闭后可只保留其他计时条，例如猎人的远程计时条。"
L["Your own cooldown layout: every spell the Cooldown Manager tracks as an icon or a bar, placed where you like and snapped together. Layouts are profiles: as many per class as you like, one for each talent set."] = "自定义冷却布局：冷却管理器追踪的每个法术都以图标或计量条显示，放在你喜欢的位置并自动吸附。布局即配置：每个职业可创建任意多个，每个天赋组各用一个。"
L["Your threat on each enemy as a number by its health bar: at 100% it turns on you. Shows in a group or with a pet. Works with Threat colors on or off."] = "在每名敌人的生命条旁以数字显示你的威胁值：达到 100% 时敌人会转向你。在小队中或带有宠物时显示。无论威胁颜色是否开启都有效。"
