-- DaylightUI 1.6.7 additions and corrections, checked by Finn.
L["%d quests to turn in"] = "%d 个可交任务"
L["/dui platefix - run while nameplates are invisible, one step each time, and say which step brought them back"] = "/dui platefix - 在姓名板不可见时运行，每次执行一步，并说明哪一步恢复了显示"
L["A green part after your experience shows what the quests you can turn in will give. Hover the bar for the total."] = "经验条后的绿色部分显示可交任务将提供的经验。将鼠标悬停在经验条上可查看总数。"
L["AP"] = "攻强"
L["Add by ID"] = "按 ID 添加"
L["Also supporting"] = "其他支持者"
L["By power type: mana blue, rage red, energy yellow, each as its gradient from General > Gradients. Or one color you pick."] = "按资源类型：法力蓝色、怒气红色、能量黄色，各自使用“常规 > 渐变”中的渐变；也可选择单一颜色。"
L["Cooldown layout report saved. Type /reload, then send your DaylightUI.lua file."] = "冷却布局报告已保存。请输入 /reload，然后将你的 DaylightUI.lua 文件发送给我们。"
L["Copy the text in the box and send it to the Daylight UI team, then /reload."] = "复制框中的文字并发送给 Daylight UI 团队，然后输入 /reload。"
L["Crit"] = "爆击"
L["Ctrl+C to copy, then paste it in a bug report on the Daylight UI Discord. After that, /reload."] = "按 Ctrl+C 复制，然后粘贴到 Daylight UI Discord 的错误报告中。之后输入 /reload。"
L["Cuts the end of each detached cast bar at an angle. When off, its end is straight."] = "将每个独立施法条末端切成斜角。关闭后末端为平直。"
L["Each detached cast bar fills from the right."] = "每个独立施法条从右向左填充。"
L["Each party member's casts on their own frame, while they last. They use the target cast bar's colors."] = "在小队成员各自的框体上显示其施法，持续至施法结束。颜色沿用目标施法条。"
L["Flash Heal"] = "快速治疗"
L["Flare"] = "闪耀"
L["Full (1,234)"] = "完整（1,234）"
L["Glows while the buff is up: Clearcasting, Nightfall."] = "增益存在时发光：清晰预兆、夜幕。"
L["Hit"] = "命中"
L["How tall each party cast bar is. Not inside the frame, where it takes the power bar's place."] = "每个小队施法条的高度。位于框体内时不适用，此时会占用能量条位置。"
L["How wide each detached cast bar is. Under the frame it matches the frame's width."] = "每个独立施法条的宽度。位于框体下方时与框体同宽。"
L["In your bags"] = "背包中"
L["Item ID:"] = "物品 ID："
L["Loaded"] = "已装填"
L["Mana, rage or energy as a thin bar under the health bar: see a caster running dry, or a rogue saving up energy. The cast bar moves down under it."] = "在生命条下方以细条显示法力、怒气或能量，便于观察法系资源耗尽或盗贼积蓄能量。施法条会下移到其下方。"
L["Moves the detached cast bars sideways from their side."] = "将独立施法条从所在侧左右移动。"
L["Moves the detached cast bars up or down from their side."] = "将独立施法条从所在侧上下移动。"
