L["Play it again"] = "再次播放"
L["Play the quest's voice"] = "播放任务语音"
L["Players and mana users: every enemy player, and the mobs that cast. Everyone with power: warriors' rage and the like too. Your target only: just the one you have selected."] = "玩家和法力使用者：所有敌方玩家及会施法的怪物。所有拥有资源的单位：也包括战士的怒气等。仅目标：只显示当前选中的单位。"
