L["Run /dui platefix first, while the nameplates are invisible."] = "请先在姓名板不可见时运行 /dui platefix。"
L["SP"] = "法强"
L["Shards"] = "碎片"
L["Show XP from finished quests"] = "显示已完成任务的经验"
L["Show all levels"] = "显示所有等级"
L["Show party cast bars"] = "显示小队施法条"
L["Slam"] = "重击"
L["Soul Shards"] = "灵魂碎片"
L["Spell ID:"] = "法术 ID："
L["Spell casts for you, your target, focus and party."] = "显示你、目标、焦点和小队的法术施法。"
