L["Stop the voice"] = "停止语音"
L["Sweep"] = "扫光"
L["Talent set 1"] = "天赋组 1"
L["That item has no use to time."] = "该物品没有可计时的使用效果。"
L["The game menu, addon list, macros, clock, loot, socketing, upgrading, the scrapper, the auction house, the professions book, the world map's frame, the breath bar. Also the game's own character and inspect windows while Daylight UI's are off."] = "游戏菜单、插件列表、宏、时钟、拾取、插槽、升级、分解机、拍卖行、专业书、世界地图框体和呼吸条。以及 DaylightUI 对应窗口关闭时游戏自带的角色和观察窗口。"
L["The space between the health bar and the power bar. Set to 0 to join them."] = "生命条与能量条之间的间距。设为 0 时两者贴合。"
L["The spell name and time on the party's cast bars. Inside the frame it's kept small enough for the power bar."] = "小队施法条上的法术名称和时间。位于框体内时会缩小以适配能量条。"
L["The spell name and timer on the party's cast bars."] = "小队施法条上的法术名称和计时。"
L["The spell name and timer while the bar sits inside a party frame, even past the power bar's height. 0 sizes them to fit the power bar."] = "施法条位于小队框体内时的法术名称和计时，即使超出能量条高度也可显示。设为 0 时自动适配能量条。"
L["The spell's icon at the end of each detached cast bar."] = "每个独立施法条末端显示法术图标。"
L["Their mana, rage or energy as a thin bar under the health bar: see a healer running low. Who gets one, its size and color follow Health & Names > Power bar."] = "在生命条下方以细条显示其法力、怒气或能量，便于观察治疗者资源不足。显示对象、尺寸和颜色遵循“生命与姓名 > 能量条”。"
L["Thick outline"] = "粗轮廓线"
L["Top 10"] = "前十名"
L["Type a number."] = "请输入数字。"
L["When off, every bar, border and highlight uses one flat color instead of two blended ones. The colors below still pick that color: the middle of each pair."] = "关闭后，所有计量条、边框和高亮都使用单一颜色而非两种颜色混合。下方颜色仍用于选取该颜色：每组双色的中间色。"
L["When short of power"] = "资源不足时"
L["Which side of each party frame a detached cast bar sits on."] = "独立施法条位于每个小队框体的哪一侧。"
L["While it's off cooldown but you lack the energy, rage or mana for it: Kick shows only once you can afford it. Show tints it blue. Hide keeps its gap: the other spells don't move."] = "技能冷却结束但资源不足时：仅在资源足够后显示“脚踢”；“显示”会将其染成蓝色；“隐藏”会保留空位，其他法术不会移动。"
L["Rise"] = "上升"
L["Fall"] = "下降"
L["Fountain"] = "喷泉式"


