-- DaylightUI 1.6.9 additions and corrections, checked by Finn.
L["%d groups: %s%s."] = "%d 个分组：%s%s。"
L["%d of %d"] = "%d / %d"
L["%s an item to move it to another group, lock it so it's never sold, or sell it as junk. %s at the top shows your bank and your other characters' bags from anywhere."] = "%s物品可将其移到其他分组、锁定以免被出售，或标记为垃圾出售。顶部的%s按钮可随时查看你的银行和其他角色的背包。"
L["%s and %s"] = "%s 和 %s"
L["%s and %s both want to paint the %s of %s; %s keeps it."] = "%s和%s都想要绘制%s的%s；保留%s。"
L["%s is no longer junk."] = "%s已不再标记为垃圾。"
L["%s on the options' Home page runs it any time."] = "设置“主页”上的%s可随时重新运行。"
L["%s will be sold as junk."] = "%s将被作为垃圾出售。"
L["%s: %s already has a setting called %s."] = "%s：%s已存在名为%s的设置。"
L["%s: only Daylight UI's own functions can be hooked, not %s."] = "%s：只能挂钩 Daylight UI 自身的函数，不能挂钩%s。"
L[", and %d more"] = "、另有 %d 个"
L["/dui platelog - run while nameplates are invisible: copy what it shows into a bug report"] = "/dui platelog - 在姓名板不可见时运行：将显示的内容复制到错误报告中"
L["/dui tour - a short tour of what Daylight UI adds"] = "/dui tour - 快速浏览 Daylight UI 提供的功能"
L["A color for each kind"] = "每种类型一种颜色"
L["A light running round the ring, a slow breath, or no movement."] = "一道光环环绕圆环流动、缓慢呼吸，或静止不动。"
L["A marker and breadcrumbs to your quest."] = "在任务目标上显示标记，并在地面显示引导路径。"
L["A minute to see what Daylight UI does that the game doesn't: the damage meter, buff and bag groups, moving frames and where every setting lives."] = "用一分钟了解 Daylight UI 独有的功能：伤害统计、增益与背包分组、可移动的框体，以及各项设置的位置。"
L["A one-minute walk past what DaylightUI adds: the damage meter, buff and bag groups, moving frames and these options."] = "一分钟浏览 DaylightUI 新增的内容：伤害统计、增益与背包分组、可移动的框体，以及这些设置项。"
L["A party's tank too"] = "队伍坦克也显示"
L["A ring follows your mouse cursor, so it's easy to find in a busy fight."] = "一个圆环跟随鼠标指针，让你在激烈的战斗中也能一眼找到它。"
L["A small diamond by the names of the players in your party or raid, so they stand out in a crowd while their names keep their class color."] = "在小队或团队玩家的名字旁显示一个小菱形，让他们在人群中更醒目，同时名字保持职业颜色。"
L["A soft light around the ring."] = "圆环周围柔和的光晕。"
L["A square in the spell's color, or the spell's own icon edged in that color."] = "以法术颜色显示的方块，或边缘带有该颜色的法术图标。"
L["A trail of light follows the cursor as it moves."] = "光标移动时留下一道光痕。"
L["Abilities"] = "技能"
L["Above the chat"] = "聊天框上方"
L["Add point"] = "添加点数"
