L["Each bar's hand (or the queued attack) and the time to the next swing, written on the bar. Each bar's own switches under Detached bars can turn off one or the other."] = "每根计时条上的指针（或排队攻击）和下次攻击的剩余时间。每根条在“独立计时条”下的开关可以分别关闭其中一项。"
L["Enemy players carrying a flag in a battleground, one frame each. Right-click one to set it as your focus."] = "战场中携带旗帜的敌方玩家，每人一个框体。右键点击某一框体可将其设为焦点。"
