L["Every piece of Daylight UI moves. %s shows a handle on each: drag it, scroll to resize, right-click to put it back. %s shows every frame with sample units, to style them without a group."] = "Daylight UI 的每个部件都可移动。%s会在每个部件上显示控制柄：拖动移动，滚轮调整大小，右键复位。%s会显示带示例单位的全部框体，方便在没有队伍时调整样式。"
