L["Gameplay SFX"] = "游戏音效"
L["Gives the second chat panel its own text size, set in the row below. When off, it matches the main chat's text size."] = "为第二个聊天面板单独设置文字大小，在下方一行设置。关闭时与主聊天框的文字大小一致。"
L["Gives this bar the border, corners and shadow below. When off, it follows General > Appearance."] = "为此计量条使用下方的边框、圆角和阴影。关闭后，跟随“综合 > 外观”的设置。"
L["Global cooldown on the ring"] = "圆环显示公共冷却"
L["Gold characters"] = "金币统计角色"
L["Gold, gear, free bag slots and who's online, turning amber then red when gear or bags run low. Hover one for details, click it for its window."] = "金币、装备、剩余背包格数和在线好友，装备或背包紧张时由琥珀色变为红色。悬停查看详情，点击打开对应窗口。"
L["Green when done"] = "完成时变绿"
L["Group color"] = "队伍颜色"
