L["How big it is."] = "它的大小。"
L["How big the arrows are."] = "箭头的大小。"
L["How big the dispel icon is."] = "驱散图标的大小。"
L["How big the dispel icon is. With the name or portrait it fits there until you change this."] = "驱散图标的大小。跟随名字或头像时会自动适配，直到你修改此设置。"
L["How big the leader crown is. With the name or portrait it fits there until you change this."] = "领袖皇冠的大小。跟随名字或头像时会自动适配，直到你修改此设置。"
L["How big the leader's crown is, in pixels. With the name or portrait it fits there until you change this, and Leader crown size scales it."] = "领袖皇冠的大小（像素）。跟随名字或头像时会自动适配，直到你修改此设置；“领袖皇冠大小”也会影响它。"
L["How big the numbers are. 1 is the game's own size."] = "数字的大小。1 为游戏默认尺寸。"
L["How big the raid marker is. With the name or portrait it fits there until you change this."] = "团队标记的大小。跟随名字或头像时会自动适配，直到你修改此设置。"
L["How big the ready check is."] = "就位确认标记的大小。"
L["How big the ready check is. With the name or portrait it fits there until you change this."] = "就位确认标记的大小。跟随名字或头像时会自动适配，直到你修改此设置。"
L["How big the role icon is. With the name or portrait it fits there until you change this."] = "职责图标的大小。跟随名字或头像时会自动适配，直到你修改此设置。"
L["How big your target's name is. 0 keeps it the same as every plate's Name size."] = "目标名字的大小。0 表示与其他姓名板的“名字大小”一致。"
L["How long a new item stays in Recent before it goes to its own group. Right-click Recent to clear it sooner."] = "新物品在“最近”中停留多久后归入自己的分组。右键“最近”可提前清空。"
L["How long each bar is."] = "每根能量条的长度。"
L["How much a plate lights up while your mouse is over it. At 0% it doesn't light up."] = "鼠标悬停在姓名板上时的提亮程度。0% 表示不提亮。"
L["How much of each power you have, on its bar."] = "每种资源当前剩余量，显示在能量条上。"
L["How see-through the box behind the quest list is. Lower lets more of the world show through."] = "任务列表背后方框的透明度。越低，透出的场景越多。"
L["How see-through the chat panel's background is. Lower lets more of the world show behind the messages."] = "聊天面板背景的透明度。越低，消息背后透出的场景越多。"
L["How solid the empty part of every health and power bar is. Lower lets the world show through it, like the game's own frames."] = "每个生命条和能量条空白部分的透明度。越低越能看到后面的场景，类似游戏自带框体。"
L["How solid the empty part of every plate's health and power bar is. Lower lets the world show through it, like the game's own plates."] = "每个姓名板生命条和能量条空白部分的透明度。越低越能看到后面的场景，类似游戏自带姓名板。"
L["How solid the ring is."] = "圆环的不透明度。"
L["How tall each bar is."] = "每根能量条的高度。"
L["How wide the ring is."] = "圆环的宽度。"
L["Import bag groups"] = "导入背包分组"
L["Import groups"] = "导入分组"
L["Import one here"] = "在此导入"
L["Imported %d bag groups."] = "已导入 %d 个背包分组。"
L["In a fight the window stays: scroll it, switch tabs and click a spell to cast it. The search and section buttons wait until the fight ends. Turn it off to get the game's own book in a fight, where you can drag spells to your bars."] = "战斗中窗口保持可用：可以滚动、切换标签并点击法术施放。搜索和分类按钮要等战斗结束。关闭后，战斗中会使用游戏自带的法术书，可以从中把法术拖到动作条。"
L["Inside the frame it covers the power bar (in the Ribbon style, or with power bars off, it slides out under the frame instead). Under the frame it slides out during a cast: give it room with the party's spacing. Detached, it's a bar you size here, beside each frame."] = "在框体内时，它覆盖能量条（缎带样式或关闭能量条时，会改为从框体下方滑出）。在框体下方时，施法过程中它会滑出：请用小队间距为其留出空间。分离后，它是独立计量条，可在此设置尺寸，显示在每个框体旁。"
L["Inside the frame it covers the power bar, as wide as it (in the Ribbon style it sits below the frame instead). Above, below or on its own it's a bar you size here; on its own you move it in unlock mode. Under the frame it slides out during a cast, and the buffs below keep room for it."] = "在框体内时，它覆盖能量条并与其等宽（缎带样式中则位于框体下方）。在上方、下方或独立时，可在此设置其尺寸；独立时在解锁模式中移动。在框体下方时，施法过程中它会滑出，下方的增益会为其保留空间。"
L["Inspect window"] = "观察窗口"
L["Instances"] = "副本"
L["Instances are dungeons, raids and battlegrounds."] = "副本包括地下城、团队副本和战场。"
L["It starts folded away: the tab on the panel's edge slides it out."] = "默认折叠隐藏：点击面板边缘的标签可将其滑出。"
L["Items sorted into groups by type. To move an item to another group, drag it onto that group's heading or Alt-right-click it. Click a heading to collapse it; right-click Recent to clear it. Alt-right-click also locks an item so it's never sold or disenchanted."] = "物品按类型分入各分组。要将物品移到其他分组，可将其拖到该分组标题上，或对物品 Alt+右键点击。点击标题可折叠；右键“最近”可清空。Alt+右键点击还会锁定物品，使其不会被出售或分解。"
L["Its bag, bank and guild bank windows, slots and buttons. Another look can still be picked in Bagnon's own options."] = "其背包、银行和公会银行窗口、栏位与按钮。仍可在 Bagnon 自己的设置中选择其他外观。"
L["Its bag, bank and guild bank windows, slots, buttons and settings, while its own Blizzard look is picked."] = "其背包、银行和公会银行窗口、栏位、按钮与设置，同时保留其自带的暴雪外观。"
L["Junk, sold at the next vendor"] = "垃圾，下次访问商人时出售"
L["Just left of the panel, level with its top"] = "位于面板左侧，与其顶部平齐"
L["Just left of the panel, the first row resting on its bottom edge"] = "位于面板左侧，第一行紧贴其底边"
L["Just the tracker. Add the rest later."] = "仅保留任务追踪器。其余功能以后再添加。"
L["Keep the spellbook in a fight"] = "战斗中保留法术书"
L["Keeps the name inside the bar. When off, it sits in a small tab above the frame, like the other frames' names."] = "将名字保留在计量条内。关闭后，名字会像其他框体一样显示在框体上方的小标签中。"
L["Keybind"] = "按键绑定"
L["Keybinds, stack counts, macro names and cooldown numbers on every bar, the Cooldown Manager and totems"] = "所有动作条、冷却管理器和图腾上的快捷键、层数、宏名称和冷却数字"
L["Leader crown pixel"] = "领袖皇冠像素"
L["Leave Vehicle"] = "离开载具"
L["Left of the frame"] = "框体左侧"
