L["Paging: this bar can show another page of buttons while you hold a key. Your stances and forms change it too, unless you switch that off below. Pick a spare page to fill it with spells of its own."] = "翻页：按住某个按键时，此动作条可以显示另一页按钮。你的姿态和形态也会切换它，除非你在下方关闭该功能。选择一个备用页，为它单独放入法术。"
L["Paints %s."] = "绘制%s。"
L["Paste bag groups (Ctrl+V). A group with the same name as one of yours is updated; the others are added."] = "粘贴背包分组（Ctrl+V）。与你现有分组同名的分组会被更新，其余分组会被添加。"
