L["Plays once as the buff lands, like Clearcasting or Nightfall."] = "在增益生效时播放一次，例如清晰预兆或夜幕。"
L["Plays once as the spell comes off cooldown, never on the global cooldown."] = "在法术冷却结束时播放一次，公共冷却期间不播放。"
L["Plays once as you become able to cast it: Revenge after a block, Overpower after a dodge, Execute on a low target. Rage or mana coming back doesn't count."] = "在你能够施放它时播放一次：格挡后复仇、闪避后压制、血量低的目标可用斩杀。怒气或法力恢复不会触发。"
L["Press Escape and pick Daylight UI in the game menu, or type %s. Search finds any setting. %s over any Daylight UI window sizes it. %s on Home runs this tour again."] = "按 Esc 并在游戏菜单中选择 Daylight UI，或输入%s。搜索可找到任何设置。在任意 Daylight UI 窗口上使用%s可调整其大小。主页上的%s可重新运行本导览。"
