L["Takes the main hand bar out of the group onto a handle of its own (/dui unlock), with the settings below. It rises into place as it fades in."] = "将主手计时条从组中分离，使用独立移动柄（/dui unlock），并采用下方设置。淡入时会升到对应位置。"
L["Takes the off hand bar out of the group onto a handle of its own (/dui unlock), with the settings below. It rises into place as it fades in."] = "将副手计时条从组中分离，使用独立移动柄（/dui unlock），并采用下方设置。淡入时会升到对应位置。"
L["Takes the ranged bar out of the group onto a handle of its own (/dui unlock), with the settings below. It rises into place as it fades in."] = "将远程计时条从组中分离，使用独立移动柄（/dui unlock），并采用下方设置。淡入时会升到对应位置。"
