L["The Daylight UI look."] = "Daylight UI 外观。"
L["The arrows in your accent color, or one you pick below."] = "箭头使用你的强调色，或使用你在下方选择的颜色。"
L["The arrows' color when Arrow color is Own color."] = "箭头颜色设为“自定义颜色”时的箭头颜色。"
L["The chat window's text and the chat bubbles"] = "聊天窗口的文字和聊天气泡"
L["The color of your party and raid members' names (with Group names on) and of the Group mark."] = "小队和团队成员名字（开启“队伍名字”时）以及队伍标记的颜色。"
L["The data texts, and the clock, framerate, zone name and coordinates on the minimap"] = "信息文字，以及微缩地图上的时钟、帧率、地区名和坐标"
L["The empty part of every bar in the group. A spell's own background wins."] = "分组中每个计量条的空白部分。法术自身的背景优先。"
L["The empty part of the bar, behind the fill."] = "计量条填充后方的空白部分。"
L["The experience bar's text and its +XP"] = "经验条的文字及其 +经验"
L["The fill of the bar."] = "计量条的填充。"
L["The frame whose setup to copy onto this one."] = "要将其设置复制到此框体的源框体。"
L["The game menu, addon list, macros, clock, loot, socketing, upgrading, the scrapper, the auction house, the professions book, the world map's frame, the breath bar, the crowd control alert, the box that splits a stack. Also the game's own character and inspect windows while Daylight UI's are off."] = "游戏菜单、插件列表、宏、时钟、拾取、镶嵌、升级、分解机、拍卖行、专业书、世界地图框体、呼吸条、控制警报和拆分堆叠的输入框。Daylight UI 的对应窗口关闭时，还包括游戏自带的角色和观察窗口。"
L["The global cooldown sweeps around the ring after each spell, so you see when the next one is ready."] = "每次施法后公共冷却沿圆环转一圈，让你知道下一个法术何时就绪。"
L["The hand (or the queued attack, or the range) written on the bar, attached or detached."] = "计时条上显示的指针（或排队攻击，或射程），无论附着还是独立显示。"
L["The health and level numbers on the nameplates"] = "姓名板上的生命值和等级数字"
L["The height of a whisper conversation above the chat or dragged away. Beside the chat it's as tall as the chat."] = "密语对话显示在聊天框上方或拖离后的高度。在聊天框旁时与聊天框同高。"
L["The level number on the nameplates. General uses the health text font."] = "姓名板上的等级数字。“综合”会使用生命值文字的字体。"
L["The number on the bar. General uses your player frame's, or the one on General > Appearance when that has none."] = "计量条上的数字。“综合”会使用玩家框体的设置，若玩家框体未设置，则使用“综合 > 外观”中的设置。"
L["The outline round the time and stack count on buffs and debuffs, apart from General > Appearance's, so the time stays easy to read over any icon."] = "增益和减益上剩余时间与层数的描边，独立于“常规 > 外观”的设置，让时间在任何图标上都清晰易读。"
L["The overshield grows from where the health starts instead of from the frame's end."] = "溢出护盾从生命条起点处延伸，而不是从框体末端。"
L["The overshield in the absorb shields' color, or a color of its own."] = "溢出护盾使用吸收护盾的颜色，或使用自己的颜色。"
L["The overshield's color when Overshield color is Custom color."] = "溢出护盾颜色设为“自定义颜色”时的溢出护盾颜色。"
L["The overshield's look: the same as the shield texture, or its own."] = "溢出护盾的外观：与护盾材质相同，或使用自己的材质。"
L["The pet's health bar takes the mood color instead: red unhappy, yellow content, green happy. Turn Pet happiness off to have only this."] = "宠物的生命条改用快乐值颜色：不高兴为红色，满意为黄色，快乐为绿色。关闭“宠物快乐值”可只保留此项。"
L["The pet's mood face edged in its color, or a square filled with it."] = "宠物的表情脸带该颜色描边，或显示填充该颜色的方块。"
L["The pets' health text"] = "宠物的生命值文字"
L["The pets' names"] = "宠物的名字"
L["The player frame"] = "玩家框体"
L["The power bar"] = "能量条"
L["The raid tiles' health text"] = "团队方块的生命值文字"
L["The raid tiles' names"] = "团队方块的名字"
L["The ring lights up the moment your next spell is ready."] = "下一个法术就绪的瞬间圆环亮起。"
L["The ring's color when Cursor ring color is Custom."] = "光标圆环颜色设为“自定义”时的圆环颜色。"
L["The role, marker and crown ride with the name tab or portrait until you pick a spot for them. The dispel icon sits in a corner."] = "职责图标、标记和皇冠跟随名字标签或头像，直到你为它们指定位置。驱散图标显示在角落。"
L["The size of the messages on the second chat panel."] = "第二个聊天面板中消息的大小。"
L["The spell name and time on the cast bars"] = "施法条上的法术名和时间"
L["The spell name and time on the party's cast bars"] = "小队施法条上的法术名和时间"
L["The spell name and time on the party's cast bars. General uses the font on General > Appearance."] = "小队施法条上的法术名和时间。常规设置使用“常规 > 外观”中的字体。"
L["The spell name and time on your cast bar"] = "你施法条上的法术名和时间"
L["The spell name and time on your focus's cast bar"] = "焦点施法条上的法术名和时间"
L["The spell name and time on your target's cast bar"] = "目标施法条上的法术名和时间"
L["The spellbook and talent keys open DaylightUI's window. Turn it off to always use the game's window."] = "法术书和天赋按键打开 DaylightUI 的窗口。关闭后始终使用游戏自带窗口。"
L["The swing timer's hand and time"] = "攻击计时条的武器和时间"
L["The threat number on the nameplates. General uses the health text font."] = "姓名板上的威胁数值。“综合”会使用生命值文字的字体。"
L["The threat number. General uses this frame's health text font."] = "威胁数值。“综合”会使用此框体的生命值文字字体。"
L["The time to the next swing, written on the bar, attached or detached."] = "显示在计时条上的下次攻击剩余时间，无论附着还是独立显示。"
L["The tour waits until the fight is over."] = "导览会等待战斗结束。"
L["The width of a whisper conversation."] = "密语对话的宽度。"
L["This bar's own outline, corners and shadow, to match a power bar of its own or stand apart."] = "此计量条自己的描边、圆角和阴影，可与它自己的能量条匹配，或单独设置。"
