L["This frame's names, and its level badge"] = "此框体的名字和等级徽章"
L["This frame's power text"] = "此框体的能量文字"
L["This icon's own size. Whole group sizes every icon in the group."] = "此图标自己的大小。“整个分组”会统一分组中所有图标的大小。"
L["Threat % font"] = "威胁值 % 字体"
L["Threat % grow direction"] = "威胁值 % 增长方向"
L["Threat % left / right"] = "威胁值 % 左/右"
L["Threat % position"] = "威胁值 % 位置"
L["Threat % up / down"] = "威胁值 % 上/下"
L["Threat tag font"] = "威胁值标签字体"
L["Threat: about to switch gradient"] = "威胁：即将转向（渐变）"
L["Threat: attacking you gradient"] = "威胁：正在攻击你（渐变）"
L["Threat: not attacking you gradient"] = "威胁：未攻击你（渐变）"
L["Tiles grow"] = "方块延伸方向"
L["Tour skipped. %s on the options' Home page shows it again."] = "已跳过导览。设置主页上的%s可再次查看。"
L["Trades places with the spell after it in the group. Each keeps its own look and options."] = "与分组中后一个法术交换位置。各自的外观和设置保持不变。"
L["Trades places with the spell before it in the group. Each keeps its own look and options."] = "与分组中前一个法术交换位置。各自的外观和设置保持不变。"
L["Tradeskills"] = "专业技能"
L["Travel Form"] = "旅行形态"
L["Turn the PvP frames on or off. When off, the game shows its own after a reload."] = "开启或关闭 PvP 框体。关闭后，重新加载界面会显示游戏自带的框体。"
L["Turn the focus frame on or off."] = "开启或关闭焦点框体。"
L["Turn the party frame on or off."] = "开启或关闭小队框体。"
L["Turn the pet frame on or off."] = "开启或关闭宠物框体。"
L["Turn the player frame on or off."] = "开启或关闭玩家框体。"
L["Turn the target frame on or off."] = "开启或关闭目标框体。"
L["Under the frame"] = "框体下方"
L["Unlearn %s"] = "遗忘%s"
L["Usable or proc"] = "可用或触发"
L["Uses Daylight UI's API without registering as a plugin."] = "使用 Daylight UI 的 API 但未注册为插件。"
L["What this slot on the "] = "此栏位位于数据条"
L["When a shield is bigger than the health missing, the part that doesn't fit runs back over the health with a bright line. When off, only the shield that fits shows."] = "当护盾大于缺失的生命值时，放不下的部分会带着亮线倒回生命条上。关闭时只显示装得下的护盾。"
L["Where a whisper conversation opens. Drag one by its top to put it anywhere on your screen, and drag its corner to resize it."] = "密语对话的打开位置。拖动其顶部可放到屏幕任意位置，拖动边角可调整大小。"
L["Where on or around the frame it sits."] = "它位于框体上或框体周围的位置。"
L["Where the dispel icon sits: with the name tab or portrait (in a corner when the frame has neither), or any spot on or around the frame."] = "驱散图标的位置：跟随名字标签或头像（若两者都无则显示在角落），或框体上、框体周围的任意位置。"
L["Where the leader crown sits: with the name tab or portrait (in a corner when the frame has neither), or any spot on or around the frame."] = "领袖皇冠的位置：跟随名字标签或头像（若两者都无则显示在角落），或框体上、框体周围的任意位置。"
L["Where the next line of frames goes once one is full."] = "一行排满后，下一行框体的排列方向。"
L["Where the raid marker sits: with the name tab or portrait (in a corner when the frame has neither), or any spot on or around the frame."] = "团队标记的位置：跟随名字标签或头像（若两者都无则显示在角落），或框体上、框体周围的任意位置。"
L["Where the ready check sits on each frame, or just outside it."] = "就位确认标记在每个框体上或框体外侧的位置。"
L["Where the ready check sits: with the name tab or portrait (in a corner when the frame has neither), or any spot on or around the frame."] = "就位确认标记的位置：跟随名字标签或头像（若两者都无则显示在角落），或框体上、框体周围的任意位置。"
L["Where the role icon sits: with the name tab or portrait (in a corner when the frame has neither), or any spot on or around the frame."] = "职责图标的位置：跟随名字标签或头像（若两者都无则显示在角落），或框体上、框体周围的任意位置。"
L["Where you dragged it"] = "自定义位置"
L["Which way the frames run from the first one. Up or Left starts them at the bottom or the right, so a small group sits by that edge."] = "框体从第一个开始的排列方向。向上或向左会让它们从底部或右侧开始，使小队伍靠近对应边缘。"
L["Whose gold the Gold text's tooltip lists and adds up: every character, or only those of the faction you're playing. A character counts for its faction once it has logged in after this update."] = "“金币”文本的提示中列出并合计哪些角色的金币：所有角色，或仅限你正在玩阵营的角色。角色在本次更新后登录过才会计入其阵营。"
L["With the map maximized, the quest list opens beside it, as it does on the small map, instead of taking its room from the map. On a narrow screen the map gives up only what doesn't fit."] = "地图最大化时，任务列表像在微缩地图上一样显示在地图旁边，而不是占用地图的空间。屏幕较窄时，地图只会让出放不下的部分。"
L["With the name or portrait"] = "跟随名字或头像"
L["With the power bar on its own (Player > Power bar), the cast bar and the swing timer under it can slide out from under the power bar instead of the frame."] = "能量条独立显示时（玩家 > 能量条），其下方的施法条和攻击计时条可以从能量条下方滑出，而不是从框体下方。"
L["Yes, the quest helper"] = "好，启用任务助手"
L["You move at %.0f%% of a normal run: on foot, mounted, swimming or flying, by what you're doing."] = "你的移动速度为正常奔跑速度的 %.0f%%，取决于当前状态：步行、骑乘、游泳或飞行。"
L["You must restart the game for the new damage numbers font to take effect."] = "需要重启游戏，新的伤害数字字体才会生效。"
L["Your accent color (a gradient accent runs across the ring), your class's colors, or one you pick."] = "使用你的强调色（渐变强调色横贯圆环）、职业颜色，或你选择的颜色。"
L["Your bags sort items into groups by kind. Press %s to open them."] = "你的背包按类型将物品分入各分组。按%s打开。"
L["Your buffs sort themselves into groups. A buff in the wrong one? %s it and pick its group."] = "你的增益会自动分入各分组。有增益分错组？%s它并选择分组。"
L["Your casts and channels fill a thin ring around it."] = "你的施法和引导会填满它周围的一个细圆环。"
L["Your own frame shows here even when you're not in a group."] = "即使不在队伍中，你自己的框体也会显示在这里。"
L["Your own groups as text to copy: paste it on another character, or give it to a friend."] = "你自己的分组导出为可复制的文本：粘贴到其他角色，或分享给朋友。"
L["Your own groups: their names, searches and the items you moved to them. Ctrl+C to copy, then share it."] = "你自己的分组：名称、搜索条件和移入的物品。按 Ctrl+C 复制后即可分享。"
L["Your pet's mood beside the frame: red while it's unhappy, yellow while content, green while happy. Hover for its damage, loyalty and diet."] = "宠物框体旁显示其快乐值：不高兴为红色，满意为黄色，快乐为绿色。悬停可查看伤害、忠诚度和饮食。"
L["Your stances, forms, stealth and the page keys swap this bar's buttons, as in the game. Off, it always shows its own buttons. Vehicles still take it over."] = "你的姿态、形态、潜行和翻页键会像游戏中一样切换此动作条的按钮。关闭后始终显示自己的按钮。载具仍会接管此动作条。"
L["Your target only"] = "仅你的目标"
