-- DaylightUI 1.7 additions, reviewed by Finn.
L["%s · %s"] = "%s · %s"
L["%sClick|r%s: details  ·  |r%sShift-click|r%s: report|r"] = "%s点击|r%s：详情  ·  |r%sShift+点击|r%s：报告|r"
L["A border and shadow around the window."] = "为窗口添加边框和阴影。"
L["A friendly player's buffs as a row of small icons, so you can see what they're missing before you rebuff. Not in combat: the game hides other players' buffs then."] = "将友方玩家的增益显示为一排小图标，方便你在补增益前看出对方缺少什么。战斗中不显示：此时游戏会隐藏其他玩家的增益。"
L["A square filled with the mood's color, or the pet's mood face edged in it."] = "以心情颜色填充的方块，或以该颜色描边的宠物心情表情。"
L["A thin line across the bars where your threat would pull the mob: 110% of the tank's in melee, 130% at range. Not shown against a boss, whose numbers the game keeps hidden."] = "横跨各条状态条的细线，标示你的仇恨会吸引目标的临界值：近战为坦克仇恨的 110%，远程为 130%。对首领不显示，因为游戏会隐藏首领的仇恨数值。"
L["A window showing an earlier fight goes back to this fight (or Overall) as the next one starts."] = "显示早先战斗的窗口会在下一场战斗开始时切回当前战斗（或“总体”）。"
L["ABSORBS"] = "吸收"
L["All meters"] = "所有统计"
L["Always show yourself"] = "始终显示自己"
L["Amount"] = "数值"
L["Amounts shortened (12.3K) or in full (12,345), on every meter, the breakdowns and reports."] = "将所有统计、明细和报告中的数值缩写（12.3K）或显示完整数值（12,345）。"
L["An Alliance or Horde crest by the names of players of the other faction, on enemy and friendly plates alike."] = "在敌对和友方姓名板上，为对方阵营玩家显示联盟或部落徽记。"
L["Angled bar ends"] = "斜角条端"
L["Angled ends on"] = "斜角端应用于"
L["Attackers"] = "攻击者"
L["Avoidable"] = "可规避"
L["Back to the current fight on a pull"] = "开怪时返回当前战斗"
L["Bar gradient"] = "状态条渐变"
L["Bar icons"] = "状态条图标"
L["Bar spacing"] = "状态条间距"
L["Both ends"] = "两端"
L["Click a name to rename it. A click on Settings edits that window on the other tabs."] = "点击名称可重命名。在其他标签页点击“设置”可编辑该窗口。"
L["Cuts the ends of each line at an angle. When off, the ends are straight."] = "将每条状态条的末端切成斜角。关闭时末端为平角。"
L["DPS"] = "DPS"
L["Damage or healing per second, in brackets after the total."] = "在总值后的括号内显示每秒伤害或治疗。"
L["Damage, healing and more for every fight, beside the minimap: the mode, the fight and its length on top, and its buttons there while the mouse is over it (which fight, what it counts, %s, reset, %s). Hover a name for their spells; click it for everything. More windows: %s."] = "在微缩地图旁显示每场战斗的伤害、治疗等数据：顶部显示模式、战斗和持续时间，鼠标悬停时还会显示按钮（选择哪场战斗、统计内容、%s、重置、%s）。悬停名字可查看其法术；点击可查看全部内容。更多窗口：%s。"
L["Damage, healing and threat meters: the one in the info panel, the threat meter beside it, and as many windows of your own as you like."] = "伤害、治疗和威胁统计：信息面板中的统计、旁边的威胁统计，以及任意数量的自定义窗口。"
L["Daylight UI's own icons, the game's own round class icons, or with the Jiberish Fabled Icons addon installed, its Fabled styles (art by JiberishUI and its artists, read from that addon's own folder)."] = "Daylight UI 自带图标、游戏自带的圆形职业图标；安装 Jiberish Fabled Icons 插件后，还可使用其 Fabled 样式（美术由 JiberishUI 及其画师制作，从该插件自己的文件夹读取）。"
L["Deadly"] = "致命"
L["Death"] = "死亡"
L["Destroy"] = "摧毁"
L["Disp."] = "驱散"
L["Each bar in its player's class color or all in one color; a threat meter can color each bar by how close that player is to pulling."] = "每条状态条使用玩家职业颜色或统一颜色；威胁统计可根据玩家接近吸引仇恨的程度为每条状态条着色。"
L["Each player's place, before their icon."] = "显示每位玩家的排名，位于其图标之前。"
L["Each player's share of everyone's total, in brackets. The game hides the numbers during a fight, so it shows once the fight is over."] = "在括号内显示每位玩家占全员总值的比例。游戏会在战斗中隐藏数值，因此战斗结束后才会显示。"
L["Each player's total, the first number on their bar."] = "每位玩家的总值，即状态条上的第一个数字。"
L["Equip"] = "装备"
L["Every number, by player"] = "按玩家显示所有数值"
L["Everyone's total for the fight, beside its length."] = "在持续时间旁显示战斗的全员总值。"
L["Fight on: updates when it ends."] = "战斗中：结束后更新。"
L["Fight summary"] = "战斗摘要"
L["Focus Target"] = "焦点目标"
L["Friendly NPCs' names when Name color is Custom."] = "名称颜色设为“自定义”时，友方 NPC 的名称颜色。"
L["Friendly players' names when Name color is Custom."] = "名称颜色设为“自定义”时，友方玩家的名称颜色。"
L["Gives this window its own background opacity, set in the row below. When off, it's as see-through as the info panel's boxes (General page)."] = "让此窗口使用独立的背景不透明度，在下方设置。关闭时，其透明度与信息面板的框体一致（“综合”页面）。"
L["Group total in the header"] = "标题栏中的小队总值"
L["HPS"] = "HPS"
L["Health bars of mobs your quests still need in the color below, so they're easy to pick out of a pack. A boss or rare keeps its own color. Threat colors still show over it. Not inside instances."] = "任务仍然需要的怪物生命条使用下方颜色，便于从怪堆中辨认。首领或稀有怪物保持自己的颜色。威胁颜色仍会覆盖显示。副本内不生效。"
L["How solid this window's background is: 0 is fully see-through, leaving only the bars."] = "此窗口背景的不透明度：0 为完全透明，只显示状态条。"
L["How tall the window is. Dragging its corner in unlock mode sets it too."] = "窗口高度。在解锁模式中拖动窗口角落也可以调整。"
L["How thick the ring is. A thicker ring leaves a smaller picture inside. The red aggro ring and its lights follow it."] = "光环的粗细。光环越粗，内部头像越小。红色仇恨光环及其亮光会随其调整。"
L["How wide the window is. Dragging its corner in unlock mode sets it too."] = "窗口宽度。在解锁模式中拖动窗口角落也可以调整。"
L["In a group or with a pet"] = "在小队中或带有宠物时"
L["Info Panel > Meters"] = "信息面板 > 统计"
L["Int."] = "打断"
L["Killing blow"] = "致命一击"
L["Left end"] = "左端"
L["Line round the middle"] = "中线"
L["Meters"] = "统计"
L["Mobs that use mana in the color below: the ones to interrupt or pull out of line of sight. A boss, rare or quest mob keeps its own color. Threat colors still show over it."] = "将使用法力的怪物显示为下方颜色：这些怪物需要打断或拉出视线。首领、稀有或任务怪物保持自己的颜色。威胁颜色仍会覆盖显示。"
L["Moves the "] = "移动"
L["Moves the spell name and time sideways together while the bar sits inside the target frame."] = "当施法条位于目标框体内时，同时左右移动法术名称和时间。"
L["Moves the spell name and time up or down together while the bar sits inside the target frame. They can sit outside the bar."] = "当施法条位于目标框体内时，同时上下移动法术名称和时间。它们可以位于施法条外。"
L["NPC names"] = "NPC 名称"
L["Names of the other faction's players you can't attack (not flagged for PvP) when Name color is Custom."] = "名称颜色设为“自定义”时，无法攻击的对方阵营玩家（未开启 PvP 标记）的名称颜色。"
L["Names on friendly plates in their class or reaction color, a class gradient, or plain white. Reaction: players in green too. Custom: pick a color for players, NPCs and the other faction below."] = "友方姓名板上的名称使用职业或阵营反应颜色、职业渐变色，或纯白色。“反应”：玩家也显示为绿色。“自定义”：在下方分别为玩家、NPC 和对方阵营选择颜色。"
L["Never shown solo: then everything is on you. The threat meter beside the meter slides back once the fight ends, and a click on its tab overrides this until the next fight. A threat window of your own set to Never shows in every fight in a group."] = "单人时永不显示：此时所有威胁都由你承担。战斗结束后，统计旁的威胁统计会收起，点击其标签可在下一场战斗前覆盖此设置。设为“从不”的自定义威胁窗口会在小队中的每场战斗显示。"
L["New ranks on your bars"] = "动作条上的新等级"
L["New window"] = "新建窗口"
L["No absorbs yet."] = "暂无吸收数据。"
L["No avoidable damage yet."] = "暂无可规避伤害。"
L["No damage taken yet."] = "暂无承受伤害。"
L["No damage yet."] = "暂无伤害。"
L["No death in this fight."] = "本场战斗无死亡。"
L["No deaths yet."] = "暂无死亡。"
L["No dispels yet."] = "暂无驱散。"
L["No enemies yet."] = "暂无敌人。"
L["No fights yet."] = "暂无战斗。"
L["No healing yet."] = "暂无治疗。"
L["No interrupts yet."] = "暂无打断。"
L["Not while under the frame (the portrait ring covers that spot) or between the frames."] = "不能位于框体下方（头像光环会覆盖该位置）或框体之间。"
L["Not while under the frame or between the frames."] = "不能位于框体下方或框体之间。"
L["Not while under the frame or between the frames: there it fills the space it has."] = "不能位于框体下方或框体之间：在那里它只能填满可用空间。"
L["Nothing here for this player yet."] = "此玩家暂无数据。"
L["Only from its tab"] = "仅从其标签页显示"
L["Other faction names"] = "对方阵营名称"
L["Other faction's crest"] = "对方阵营徽记"
L["Overkill"] = "过量"
L["Overkill %s"] = "过量 %s"
L["Own window"] = "独立窗口"
L["Per second"] = "每秒"
L["Picking an earlier fight in one window shows it in every window on This fight. Windows on Overall stay there."] = "在一个窗口中选择早先的战斗时，所有设为“当前战斗”的窗口都会显示该场战斗。设为“总体”的窗口保持不变。"
L["Player names"] = "玩家名称"
L["Players' last names after their first on the threat meters. When off, first names only, which fit the narrow rows better."] = "在威胁统计中于名字前显示玩家的姓氏。关闭时只显示名字，更适合较窄的行。"
L["Portrait rings"] = "头像光环"
L["Powershifting: the game takes a moment to confirm a new form, and shows your caster bar until it does. Put /click DaylightUICat (or DaylightUIBear, DaylightUIMoonkin) at the top of your shift macro and this bar swaps the moment you press it."] = "能量变身：游戏需要一点时间确认新形态，在确认前会继续显示你的施法者动作条。将 /click DaylightUICat（或 DaylightUIBear、DaylightUIMoonkin）放在变形宏开头，按下时动作条就会立即切换。"
L["Quest"] = "任务"
L["Quest mob color"] = "任务怪物颜色"
L["Quest mobs in their own color"] = "任务怪物使用独立颜色"
L["Rank numbers"] = "排名数字"
L["Reaction"] = "阵营反应"
L["Reaction: every enemy name in red, players too, so friend and foe tell apart at a glance. Or players in their class color, a class gradient, or plain white."] = "阵营反应：所有敌人名称显示为红色，玩家也不例外，便于一眼分辨敌友。也可让玩家使用职业颜色、职业渐变色或纯白色。"
L["Read"] = "阅读"
L["Removes this window and its settings. Click twice."] = "移除此窗口及其设置。请点击两次。"
L["Right end"] = "右端"
L["Right-click: pick which attack power"] = "右键：选择攻击强度类型"
L["Right-click: pin, invite, note, ignore, close"] = "右键：标记、邀请、备注、屏蔽、关闭"
L["Ring thickness"] = "光环粗细"
L["Sell"] = "出售"
L["Settings"] = "设置"
L["Show only in an instance"] = "仅在副本中显示"
L["Show per second"] = "显示每秒数据"
L["Show share"] = "显示占比"
L["Show this window"] = "显示此窗口"
L["Show totals"] = "显示总值"
L["Shows"] = "显示"
L["Size of the names and numbers on the bars."] = "状态条上名称和数字的大小。"
L["Spells"] = "法术"
L["Switched off, the window is gone (its settings stay). The threat meter beside the meter shows by its own rules below."] = "关闭后窗口会隐藏（设置仍会保留）。统计旁的威胁统计按下方自己的规则显示。"
L["Tab settings"] = "标签页设置"
L["Takes the bars out from under the player frame so you can move them together (/dui unlock); they slide out of their own box. When off, they hang under the player frame, under the cast bar while it hangs there, even with the cast bar detached. With your cast bar between your frame and the target's, they fan out under it instead, each a little wider."] = "将状态条从玩家框体下方移出，以便一起移动（/dui unlock）；它们会从自己的框中滑出。关闭时，它们悬挂在玩家框体下方；施法条悬挂在那里时则位于施法条下方，即使施法条已分离也一样。若施法条位于你的框体和目标框体之间，它们会改为在施法条下方展开，并逐条略微加宽。"
L["Takes the damage meter out of the panel into its own window in the bottom-right corner; move it in unlock mode."] = "将伤害统计从信息面板中移出，变为右下角的独立窗口；可在解锁模式中移动。"
L["Target text left / right inside the frame"] = "框体内目标文字 左/右"
L["Target text up / down inside the frame"] = "框体内目标文字 上/下"
L["Targets"] = "目标"
L["The "] = "其"
L["The bars' filled part ends in a slanted edge. When off, it ends square."] = "状态条的填充部分以斜边结束。关闭时以平边结束。"
L["The color of the names on the bars."] = "状态条上名称的颜色。"
L["The game hides who's who here for now: it updates once it can."] = "游戏目前会隐藏此处的人物信息：可获取数据后会更新。"
L["The health bar's color on a mob your quests still need."] = "任务仍然需要的怪物生命条颜色。"
L["The last one follows your target when you can attack it, else the mob your friendly target is on: handy for a healer watching the tank."] = "最后一项会在目标可攻击时跟随你的目标，否则跟随友方目标正在攻击的怪物：适合治疗者观察坦克。"
L["The line on top: the mode, the fight and its length (a meter), or the mob and your own threat (a threat meter). A meter's buttons show in it while the mouse is over the window."] = "顶部一行：模式、战斗及其持续时间（统计），或怪物及你的仇恨（威胁统计）。鼠标悬停在窗口上时，统计的按钮会显示在该行。"
L["The most group members it lists at once."] = "一次列出的最多小队成员数量。"
L["The most group members it lists under the damage meter."] = "伤害统计下方列出的最多小队成员数量。"
L["The ring round every portrait, on every frame. Each frame picks its ring's color on its own page."] = "所有框体头像周围的光环。每个框体可在各自页面选择光环颜色。"
L["The small square before each name: the player's class icon, or nothing."] = "每个名称前的小方块：玩家职业图标，或不显示。"
L["The space between two bars."] = "两条状态条之间的间距。"
L["The spell name and time while the bar sits inside the frame, even past the power bar's height. 0 sizes them to fit the power bar."] = "施法条位于框体内时显示法术名称和时间，甚至可以超出能量条高度。设为 0 时，使其适应能量条高度。"
L["The spell's name on "] = "法术名称在"
L["The thin dark line round the middle of the ring. When off, the ring is one smooth band."] = "光环中部周围的深色细线。关闭时，光环为一条平滑的环带。"
L["The threat meter and your threat windows fade together, apart from the panel."] = "威胁统计和你的威胁窗口会一起淡出，信息面板除外。"
L["The time on "] = "时间在"
L["The window hides outside dungeons, raids, battlegrounds and arenas."] = "在地下城、团队副本、战场和竞技场外隐藏此窗口。"
L["The window hides while you play solo."] = "单人游戏时隐藏此窗口。"
L["Their buffs"] = "其增益"
L["There are already %d meter windows of your own: remove one to make another."] = "你已经有 %d 个自定义统计窗口：请先移除一个再新建。"
L["Threat meter fade"] = "威胁统计淡出"
L["Threat meter position"] = "威胁统计位置"
L["Threat meter rows under the meter"] = "统计下方的威胁统计行"
L["To the bank"] = "存入银行"
L["To your bags"] = "放入背包"
L["Under the meter it rises out of the damage meter's bottom, as wide as the meter. Docked, it shows only while the damage meter is open. Its own window goes anywhere: move it in unlock mode."] = "在统计下方时，它从伤害统计底部展开，与统计同宽。停靠时，仅在伤害统计打开时显示。独立窗口可放在任意位置：在解锁模式中移动。"
L["Up to %d of your own, each with its own settings and spot. Move them in unlock mode."] = "最多可创建 %d 个自定义窗口，每个都有自己的设置和位置。在解锁模式中移动。"
L["What"] = "内容"
L["What this meter lists: damage, DPS, healing, absorbs, damage taken, interrupts, dispels, deaths and more. The button in its header changes it too."] = "此统计列出：伤害、DPS、治疗、吸收、承受伤害、打断、驱散、死亡等。标题栏中的按钮也可切换。"
L["What's left of the cast, or what's left out of the whole cast."] = "显示施法剩余时间，或整个施法过程中的剩余量。"
L["When"] = "时间"
L["When I'm the tank"] = "当我为坦克时"
L["When you learn a new rank of a spell, it takes the place of the rank before it on your bars. A lower rank you keep on purpose, like rank 1 to save mana, stays. Not macros."] = "学会法术的新等级后，新等级会替换动作条上的旧等级。刻意保留的低等级（例如为节省法力保留的 1 级）会保留。不适用于宏。"
L["When you'd be scrolled out of view, your bar stays in the last row with your place."] = "当你会滚出视野时，你的状态条会连同排名停留在最后一行。"
L["Whether the summary shows this column."] = "摘要是否显示此列。"
L["Whether this window counts the fight you're in or every fight since the last reset."] = "此窗口统计当前战斗，还是自上次重置以来的所有战斗。"
L["Which ends of each line are cut at an angle. The other end stays straight."] = "选择每条状态条哪一端切成斜角，另一端保持平角。"
L["Whose threat"] = "谁的威胁"
L["Window header"] = "窗口标题栏"
L["Windows show the same fight"] = "窗口显示同一场战斗"
L["With more than one of these on, it shows only when all of them hold."] = "开启多个条件时，仅在全部满足时才显示。"
L["Your focus"] = "你的焦点"
L["Your target"] = "你的目标"
L["Your target, else your target's target"] = "你的目标，否则为目标的目标"
L["Your windows"] = "你的窗口"
L["gear weapon armor consumable food drink potion reagent tradegoods recipe key container bag quest junk soulbound set locked poor common uncommon rare epic legendary quality level"] = "装备 武器 护甲 消耗品 食物 饮料 药水 材料 商品 配方 钥匙 容器 背包 任务 垃圾 灵魂绑定 套装 已锁定 粗糙 普通 优秀 精良 史诗 传说 品质 等级"
L["new window"] = "新建窗口"

-- More DaylightUI 1.7 lines.
L["Daylight: Daylight UI's own chat box, with its own tabs. Classic: the game's chat windows and tabs in the Daylight look. Switching is instant, and both keep every message. With the game's controller mode on, chat is Classic, since the game's chat windows have its controller buttons."] = "Daylight：Daylight UI 自带的聊天框，拥有自己的标签页。经典：游戏自带的聊天窗口和标签页，采用 Daylight 外观。切换会立即生效，两者都会保留所有消息。开启游戏的手柄模式时，聊天会使用经典模式，因为游戏的聊天窗口支持手柄按键。"

L["Who your focus is looking at."] = "你的焦点正在看谁。"

L["%.2f / %.2f s"] = "%.2f / %.2f 秒"
L["Armor penetration"] = "护甲穿透"
L["Between the frames"] = "框体之间"
L["Bind"] = "绑定"
L["Choose"] = "选择"
L["Controller mode"] = "手柄模式"
L["Controller mode uses the profile %s. Switch to it?"] = "手柄模式使用配置 %s。是否切换？"
L["Dark end"] = "暗端"
L["Each off-hand swing hits for %.0f to %.0f before armor."] = "副手每次挥击在计算护甲前造成 %.0f 到 %.0f 点伤害。"
L["From Stamina, gear and buffs."] = "来自耐力、装备和增益。"
L["From your class, gear and buffs."] = "来自你的职业、装备和增益。"
L["From your gear, buffs and talents."] = "来自你的装备、增益和天赋。"
L["From your quiver, gear and buffs."] = "来自你的箭袋、装备和增益。"
L["Hold: %s"] = "按住：%s"
L["In the middle, the swing timers fanning out under it."] = "在中间，攻击计时条在下方展开。"
L["Light end"] = "亮端"
L["Off-hand damage"] = "副手伤害"
L["Other bars"] = "其他动作条"
L["Page %d"] = "第 %d 页"
L["Pages"] = "页面"
L["Place in bags"] = "放入背包"
L["Press the button to put it on. Hold a trigger for its bar."] = "按下按钮即可装备。按住扳机可显示其动作条。"
L["Slides out from under your frame as you cast."] = "施法时从你的框体下方滑出。"
L["Spell penetration"] = "法术穿透"
L["Talent sets"] = "天赋方案"
L["The game didn't send this quest's reward choices. Close and talk to them again to pick one."] = "游戏没有发送此任务的奖励选项。请关闭窗口并再次与对方交谈以选择奖励。"
L["The most you can hold for your abilities."] = "你的技能可使用的最大资源上限。"
L["The profile this character uses while the game's controller UI is on (Settings > Gameplay > Gamepad). Turning it on or off asks to switch. None: the same profile as without it."] = "开启游戏手柄界面时此角色使用的配置（设置 > 游戏玩法 > 手柄）。开启或关闭时会询问是否切换。无：与未使用手柄时相同的配置。"
L["Turn off"] = "关闭"
L["Turn on"] = "开启"
L["Under your frame"] = "你的框体下方"
L["Without the controller, this character uses the profile %s. Switch to it?"] = "不使用手柄时，此角色使用配置 %s。是否切换？"
L["You can take %.0f damage before you die."] = "你在死亡前可承受 %.0f 点伤害。"
L["You cast %.1f%% faster."] = "你的施法速度提高 %.1f%%。"
L["You get back %.0f mana every 5 seconds while casting."] = "施法时每 5 秒恢复 %.0f 点法力值。"
L["You shoot %.1f%% faster."] = "你的射击速度提高 %.1f%%。"
L["You swing %.1f%% faster."] = "你的挥击速度提高 %.1f%%。"
L["Your attacks ignore %.0f of the target's armor."] = "你的攻击忽略目标 %.0f 点护甲。"
L["Your spells ignore %.0f of the target's resistances."] = "你的法术忽略目标 %.0f 点抗性。"

L["Chests, quest objects and your fishing bobber light up as you come near, dim from afar and bright once you can reach them. This changes a few of the game's interact settings while it's on, and gives them back when it's off."] = "当你靠近时，箱子、任务目标和你的钓鱼浮标会亮起，距离较远时变暗，可触及范围内则变亮。开启时会更改游戏的部分交互设置，关闭时会恢复。"
L["Your accent color, or a color that says what the object is: gold for quests, blue for chests."] = "你的强调色，或表示物体类型的颜色：任务用金色，箱子用蓝色。"

L["%s an item to move it to another group, lock it so it's never sold, or sell it as junk. The %s and %s tabs at the top show your bank and your other characters' bags from anywhere."] = "%s物品可将其移至其他分组、锁定使其永不被出售，或作为垃圾出售。顶部的%s和%s标签页可从任意位置查看你的银行和其他角色的背包。"
L["%s of %d free"] = "%s，共 %d 格空位"
L["%s · %s of %d free"] = "%s · %s，共 %d 格空位"
L["(drag items here)"] = "（将物品拖到此处）"
L["/dui bug - your version, addons and setup, ready to copy into the Discord bug form"] = "/dui bug - 你的版本、插件和配置，可直接复制到 Discord 问题反馈表单"
L["Add to \"Error text, if one popped up\""] = "添加到“错误文本（如弹出）”"
L["Alts"] = "小号"
L["Classic dresses every frame and window in stone and gold with red buttons, the way the game's own windows look. The angled shapes stay."] = "经典会将所有框体和窗口装饰为石材与金色，配以红色按钮，与游戏自带窗口一致。斜角造型保留。"
L["Click a box and press Ctrl+C, then paste it into the Discord form."] = "点击一个框并按 Ctrl+C，然后粘贴到 Discord 表单中。"
L["Crowd control alert"] = "控制技能警报"
L["Daylight UI version"] = "Daylight UI 版本"
L["Enable damage meter"] = "启用伤害统计"
L["Gold accent"] = "金色强调"
L["Grid (bag by bag)"] = "网格（按背包）"
L["Grid (tab by tab)"] = "网格（按标签页）"
L["Other UI addons (bars, plates, bags...)"] = "其他 UI 插件（动作条、姓名板、背包……）"
L["Report a bug"] = "报告问题"
L["Saved %s"] = "已保存 %s"
L["Shelf (grouped by kind)"] = "货架（按类型分组）"
L["Shelf groups items by kind. Grid shows them bag by bag. You can also switch with the button next to the search box."] = "货架按类型分组显示物品。网格则按背包显示。你也可以使用搜索框旁的按钮切换。"
L["Shelf groups the bank by kind. Grid shows it tab by tab. You can also switch with the button next to the search box."] = "“货架”按类型对银行物品分组。“网格”按标签页显示。也可通过搜索框旁的按钮切换。"
L["Shelf groups your items by kind, with a heading for each group. Grid is one even grid, bag by bag. You can also switch with the button next to the search box. In the grid, Alt-right-click an item to keep it in its slot when you clean up."] = "“货架”按类型对你的物品分组，每组带标题。“网格”是整齐划一的网格，逐背包显示。也可通过搜索框旁的按钮切换。在网格中，按住 Alt 右键点击物品可在整理时将其保留在原槽位。"
L["Shelf or grid"] = "货架或网格"
L["Switch between Shelf, grouped by kind, and Grid, bag by bag."] = "在按类型分组的“货架”和逐背包显示的“网格”之间切换。"
L["Switch between Shelf, grouped by kind, and Grid, tab by tab."] = "在按类型分组的“货架”和逐标签页显示的“网格”之间切换。"
L["The alert in the middle of the screen when you're stunned, feared or silenced, as a light line in Daylight UI style. When off, the game's own alert shows instead."] = "当你被昏迷、恐惧或沉默时，屏幕中央的提示会以 Daylight UI 风格的细线显示。关闭时，改为显示游戏自带的提示。"
L["The game menu, addon list, macros, clock, loot, socketing, upgrading, the scrapper, the auction house, the professions book, the world map's frame, the breath bar, the box that splits a stack. Also the game's own character and inspect windows while Daylight UI's are off."] = "游戏菜单、插件列表、宏、时钟、拾取、镶嵌、升级、拆解机、拍卖行、专业技能书、世界地图边框、呼吸条、拆分堆叠的窗口。此外，在 Daylight UI 的角色和观察窗口关闭时，也包括游戏自带的这两个窗口。"
L["Turns the accent color gold to match the Classic look. When off, Classic keeps your own accent color."] = "将强调色变为金色以匹配经典外观。关闭时，经典模式保留你自己的强调色。"
L["; works like |, so one search can list several words: ore; bar; stone"] = "；也可代替 |，因此一次搜索可以列出多个词：矿石；矿锭；石头"
L["Frame layer"] = "框体层级"
L["Cast bar layer"] = "施法条层级"
L["Target cast bar layer"] = "目标施法条层级"
L["Focus cast bar layer"] = "焦点施法条层级"
L["Swing timer layer"] = "攻击计时条层级"
L["Personal display layer"] = "个人资源显示层级"
L["Low"] = "低"
L["High"] = "高"
L["Dialogue"] = "对话"
L[" Where two pieces overlap, the higher layer draws on top: Background, Low, Medium, High, then Dialogue."] = " 当两部分重叠时，层级较高的会显示在上方：背景、低、中、高，然后是对话。"
L["The layer the raid frames draw in, for every raid size."] = "团队框体使用的层级，适用于所有团队规模。"
L["The layer the PvP frames draw in."] = "PvP 框体使用的层级。"
L["The layer your cast bar draws in."] = "你的施法条使用的层级。"
L["The layer your target's cast bar draws in."] = "你的目标施法条使用的层级。"
L["The layer your focus's cast bar draws in."] = "你的焦点施法条使用的层级。"
L["The layer the swing timer draws in when detached, as a group or a bar on its own."] = "攻击计时条独立显示时使用的层级，无论作为一组还是单独一条。"
L["The layer the personal display draws in. Low keeps it under your other frames."] = "个人资源显示使用的层级。“低”会让它位于其他框体下方。"
L["Experience bar orientation"] = "经验条方向"
L["Reputation bar orientation"] = "声望条方向"
L["Horizontal"] = "水平"
L["Vertical"] = "垂直"
L["Vertical stands the separate bar upright, filling from the bottom to the top. Its width is then how tall it stands, and its height how thick."] = "选择“垂直”后，独立计量条会竖立，并从下向上填充。此时“宽度”表示高度，“高度”表示粗细。"
L["Vertical stands the bar upright, filling from the bottom to the top. Its width is then how tall it stands, and its height how thick."] = "选择“垂直”后，计量条会竖立，并从下向上填充。此时“宽度”表示高度，“高度”表示粗细。"
L["Soul bag size"] = "灵魂袋容量"
L["Soul bag slots"] = "灵魂袋栏位"
L["Free slots"] = "空余栏位"
L["Warlocks: the Soul Shards text shows how many your soul bag holds beside the count, and its tooltip the free slots."] = "术士：灵魂碎片文字会在数量旁显示灵魂袋的容量，鼠标提示则显示空余栏位。"
L[" Under the frame, between the frames or under the personal display, it draws with the frame instead."] = "位于框体下方、框体之间或个人资源显示下方时，它会改为随框体绘制。"
L[" Inside the frame or sliding out under it, it draws with the frame instead."] = "位于框体内或从框体下方滑出时，它会改为随框体绘制。"
L[" Inside the frame, it draws with the frame instead."] = "位于框体内时，它会改为随框体绘制。"
L[" Hung under the player frame or the cast bar, it draws with them instead."] = "挂在玩家框体或施法条下方时，它会改为随它们绘制。"
L["The layer the party frames draw in."] = "小队框体使用的层级。"
L["%s chance of a skill point"] = "%s 几率获得技能点"
L["%s, %s, %s"] = "%s，%s，%s"
L["/dui sleepingbag - preview the sleeping bag timer"] = "/dui sleepingbag - 预览睡袋计时器"
L["A line on enemy health bars where your finishing moves start to work. The bar's end up to it lights up in your accent color once the enemy is that low. Your class: warriors (Execute), paladins (Hammer of Wrath), and priests once they know Shadow Word: Death."] = "敌方生命条上标示终结技开始生效的位置。敌人生命值降到该线以下时，到该线为止的条端会以强调色亮起。你的职业：战士（斩杀）、圣骑士（愤怒之锤），以及学会暗言术：灭后的牧师。"
L["A small Alliance or Horde banner before each friend's character, and their faction in the tooltip."] = "在每个好友角色名前显示小小的联盟或部落旗帜，并在鼠标提示中显示其阵营。"
L["A small dot on the bottom left corner of the gray item worth the least, so when your bag is full you know what to throw away. Its tooltip says what it sells for."] = "在价值最低的灰色物品左下角显示小圆点，背包满时就知道该扔什么。鼠标提示会显示其售价。"
L["A small switch on each letter. Tick a few and the button under the list collects only those."] = "每封信件旁的小开关。勾选几封后，列表下方的按钮只收取这些信件。"
L["A square filled with the mood's color, or the pet's mood face."] = "以心情颜色填充的方块，或宠物心情表情。"
L["All, Same game and Online chips over the friends list, to show only the friends you can play with or the ones who are on."] = "好友列表上方的“全部”“同游戏”和“在线”标签，可只显示能一起玩或当前在线的好友。"
L["Alliance"] = "联盟"
L["Band: the bar's end up to the line lights up. Line only: just the line. Whole bar: the whole health bar lights up. Band, breathing: the band, gently pulsing. Spell icon: your finisher's icon shows by the bar, like the DoT skull."] = "光带：到该线为止的条端亮起。仅线条：只显示线条。整条：整条生命条亮起。光带，呼吸：光带轻柔脉动。法术图标：在条旁显示终结技图标，类似持续伤害骷髅。"
L["Blessing"] = "祝福"
L["Button height"] = "按钮高度"
L["Carry more and the bag shows a Delete extra shards button above your money. It deletes nothing until you click it twice. At 0 it never shows."] = "携带数量超过上限时，背包会在金币上方显示“删除多余碎片”按钮。需点击两次才会删除。设为 0 时从不显示。"
L["Cast target"] = "施法目标"
L["Cheapest junk: %s"] = "最便宜的垃圾：%s"
L["Class buffs share one row, then weapon, consumable, world and other buffs each start a row of their own, in the order set on the Categories page. A long row still wraps at Icons per row."] = "职业增益共用一行，随后武器、消耗品、世界和其他增益各按“分类”页面设置的顺序另起一行。过长时会按“每行图标数”换行。"
L["Click: open the recipe"] = "点击：打开配方"
L["Collect this letter"] = "收取此信件"
L["Collect ticked (%d)"] = "收取勾选的信件（%d）"
L["Darnassus"] = "达纳苏斯"
L["Delete %d extra shards"] = "删除 %d 个多余碎片"
L["Delete 1 extra shard"] = "删除 1 个多余碎片"
L["Deleted %d Soul Shards."] = "已删除 %d 个灵魂碎片。"
L["Deleted 1 Soul Shard."] = "已删除 1 个灵魂碎片。"
L["Dim friends you can't play with"] = "调暗无法一起游玩的好友"
L["Each button's height as a percent of its width. 100 is square; lower makes wide, flat buttons. The icon is cropped to fit, never stretched."] = "每个按钮高度占宽度的百分比。100 为正方形；更低会得到宽而扁的按钮。图标会裁切适配，不会拉伸。"
L["Each kind on its own row"] = "每种类型单独一行"
L["Each pet's health bar fills bottom to top instead of across, for tall, narrow pet bars."] = "宠物生命条改为从下向上填充，而不是横向填充，适合高而窄的宠物条。"
L["Each recipe shows its chance of giving a skill point, and the recipe you pick shows where it turns yellow, green and gray."] = "每个配方显示获得技能点的几率；选中的配方会显示何时变为黄色、绿色和灰色。"
L["Earlier error"] = "较早的错误"
L["Execute icon"] = "斩杀图标"
L["Faction"] = "阵营"
L["Faction icons"] = "阵营图标"
L["Filter chips"] = "筛选标签"
L["Friends in another game or on another ruleset show dimmed, like the ones who are offline."] = "其他游戏或规则集的好友会像离线好友一样变暗。"
L["Fully rested"] = "充分休息"
L["Group focus"] = "小队焦点"
L["Group focus mark"] = "小队焦点标记"
L["Horde"] = "部落"
L["How many of an item fit in one bag slot (\"Stacks to 20\"), on items that stack."] = "可堆叠物品每个背包栏位能放多少（“堆叠至 20”）。"
L["How tall each pet bar is. It can be as tall as a party frame, for a narrow pet bar standing beside each member."] = "每条宠物条的高度。可设为与小队框体相同，便于在每个成员旁显示窄宠物条。"
L["How tall the combo point pips under the personal display are. Set to 0 for automatic height."] = "个人资源显示下方连击点圆点的高度。设为 0 时自动决定高度。"
L["How wide each combo point pip under the personal display is. Not while the pips match the display's width."] = "个人资源显示下方每个连击点圆点的宽度。圆点与显示同宽时不适用。"
L["In a group, each enemy's plate takes the size of its threat state, so the mobs that need you stand out. Made for tanks: small while you hold a mob, big once it's on someone else. Your target keeps its own size. Works with Threat colors on or off."] = "在小队中，每个敌方姓名板会按仇恨状态改变大小，让需要你处理的怪物更醒目。为坦克设计：你拉住时较小，转向别人时变大。你的目标保持自身大小。无论威胁颜色是否开启都有效。"
L["In a party or raid, a double arrow in your accent color over the enemy most of your group is targeting, so you can follow the kill target. Needs at least two of you on it. Battlegrounds and arenas hide who's targeting what, so it doesn't show there."] = "在小队或团队中，当至少两人攻击同一敌人时，会在该敌人上方显示强调色双箭头，方便跟随集火目标。战场和竞技场会隐藏目标信息，因此不显示。"
L["Interrupt ready mark"] = "打断就绪标记"
L["Keep at most this many Soul Shards"] = "最多保留这么多灵魂碎片"
L["Keep at most this many Soul Shards in a raid"] = "在团队副本中最多保留这么多灵魂碎片"
L["Keeps the separate bar the same width as your main action bar. An upright bar keeps its own width."] = "让独立计量条与主动作条同宽。竖立时保留自身宽度。"
L["Later error"] = "较晚的错误"
L["Letters"] = "信件"
L["Levels beside names"] = "名称旁显示等级"
L["Mark the cheapest junk"] = "标记最便宜的垃圾"
L["Nudges the personal display's row of combo points sideways."] = "左右微调个人资源显示的连击点行。"
L["Nudges the personal display's row of combo points up or down. Docked cast and swing bars stay below it."] = "上下微调个人资源显示的连击点行。停靠的施法条和攻击计时条仍位于其下方。"
L["On the Training page, a weapon skill's tooltip names each weapon master's city and district, not just their name."] = "在训练页面，武器技能鼠标提示会显示每位武器大师所在的城市和区域，而不只是名字。"
L["Orgrimmar"] = "奥格瑞玛"
L["Personal pip height"] = "个人连击点高度"
L["Personal pip width"] = "个人连击点宽度"
L["Personal pips fill the width"] = "个人连击点填满宽度"
L["Personal pips left / right"] = "个人连击点 左/右"
L["Personal pips up / down"] = "个人连击点 上/下"
L["Pet happiness"] = "宠物快乐值"
L["Pets fill upward"] = "宠物条向上填充"
L["Plate size by threat"] = "按威胁调整姓名板大小"
L["Preview the sleeping bag timer"] = "预览睡袋计时器"
L["Remove Favorite"] = "取消收藏"
L["Right-click: stop tracking"] = "右键点击：停止追踪"
L["Same game"] = "同游戏"
L["Set Favorite"] = "设为收藏"
L["Shows it now; move to end it. Also /dui sleepingbag."] = "立即显示；移动即可结束。也可使用 /dui sleepingbag。"
L["Skill-up chance"] = "技能点几率"
L["Skill-up range"] = "技能点范围"
L["Sleeping bag timer"] = "睡袋计时器"
L["Spreads the combo point pips across the personal display. Turn it off to set the pips' own width."] = "让连击点圆点铺满个人资源显示。关闭后可单独设置圆点宽度。"
L["Stack size"] = "堆叠数量"
L["Stacks to %s"] = "堆叠至 %s"
L["Start corner"] = "起始角落"
L["The Military Ward"] = "军事区"
L["The War Quarter"] = "战争广场"
L["The corner the first button sits in. The buttons fill away from it, row by row (column by column on a vertical bar). Bottom left with 3 buttons a row puts 1, 2, 3 along the bottom, like a side-button mouse."] = "第一个按钮所在的角落。按钮从该角落向外逐行排列（垂直动作条则逐列排列）。左下角且每行 3 个时，1、2、3 会沿底部排列，类似侧键鼠标。"
L["The plate's size while the mob is about to switch targets."] = "怪物即将切换目标时的姓名板大小。"
L["The plate's size while the mob is attacking you."] = "怪物攻击你时的姓名板大小。"
L["The plate's size while the mob is in the fight but attacking someone else."] = "怪物处于战斗中但攻击别人时的姓名板大小。"
L["The same, while you're in a raid, where you may want more on hand. At 0 it never shows in a raid."] = "团队副本中的相同设置，你可能想保留更多碎片。设为 0 时在团队副本中从不显示。"
L["Threat size: about to switch"] = "威胁大小：即将切换"
L["Threat size: attacking you"] = "威胁大小：攻击你"
L["Threat size: not attacking you"] = "威胁大小：未攻击你"
L["Thunder Bluff"] = "雷霆崖"
L["Tick letters and the button under the list takes only those. Shift-click a letter to take everything in it."] = "勾选信件后，列表下方的按钮只收取这些信件。Shift+点击某封信可收取其中的全部内容。"
L["Tick letters to collect"] = "勾选要收取的信件"
L["Track Recipe"] = "追踪配方"
L["Trade District"] = "贸易区"
L["Undercity"] = "幽暗城"
L["Valley of Honor"] = "荣誉谷"
L["Warrior's Terrace"] = "战士区"
L["Well-Rested"] = "充分休息"
L["Where weapon masters stand"] = "武器大师的位置"
L["While you rest in a sleeping bag, a timer near the bottom of the screen counts down until Well-Rested is full (one stack a minute, three in all), so you can see it with your UI faded at the campfire."] = "在睡袋中休息时，屏幕下方会显示倒计时，直到“充分休息”叠满（每分钟一层，共三层），即使篝火旁界面淡出也能看到。"
L["While your interrupt is on cooldown, a thin line on an enemy target's or focus's cast bar shows where it comes back. No line: it's ready now, or it won't be back before the cast ends."] = "打断技能冷却时，敌方目标或焦点施法条上的细线会显示何时恢复。没有线表示现在已就绪，或在施法结束前不会恢复。"
L["While your interrupt is on cooldown, a thin line on an enemy's cast bar shows where it comes back. No line: it's ready now, or it won't be back before the cast ends."] = "打断技能冷却时，敌方施法条上的细线会显示何时恢复。没有线表示现在已就绪，或在施法结束前不会恢复。"
L["Who an enemy's spell is aimed at, in their class color, on the right of its cast bar. Spells with no one target (an area spell, a self heal) show none."] = "在敌方施法条右侧以职业颜色显示法术目标。没有单一目标的法术（范围法术、自我治疗）不显示。"
L["Yellow from %s, green from %s, gray from %s. Orange recipes always give a point; yellow ones usually, green ones sometimes, gray ones never."] = "从 %s 起为黄色，从 %s 起为绿色，从 %s 起为灰色。橙色配方必定给技能点；黄色通常给，绿色有时给，灰色从不给。"
L["You: %s"] = "你：%s"
L["[60] before a player's name, for anyone in your group, guild or friends list, found with /who, or you've targeted or moused over. Someone you haven't seen yet shows no level."] = "在玩家名前显示 [60]，适用于小队、公会或好友列表中的人、通过 /who 找到的人，以及你选中或鼠标悬停过的人。尚未见过的玩家不显示等级。"
L["the combo points"] = "连击点"
L["the party's cast bars"] = "小队施法条"
L["the raid tiles' health bars"] = "团队方块生命条"
L["the raid tiles' power bars"] = "团队方块能量条"
L["the swing timer"] = "攻击计时条"
L["your cast bar"] = "你的施法条"
L["your focus's cast bar"] = "你的焦点施法条"
L["your target's cast bar"] = "你的目标施法条"
L["Friendly target"] = "友方目标"
L["Enemy target"] = "敌方目标"
L["Friendly target page"] = "友方目标页"
L["Enemy target page"] = "敌方目标页"
L["Paging: this bar can show another page of buttons while you hold a key, or when your target is friendly or an enemy. Your stances and forms change it too, unless you switch that off below. Pick a spare page to fill it with spells of its own."] = "分页：按住某个键，或目标为友方或敌方时，此动作条可显示另一页按钮。姿态和形态也会切换它，除非在下方关闭该功能。请选择一个备用页面，用于放置它自己的法术。"
L["Paging: this bar can show another page of buttons while you're in a stance or form, while you hold a key, or when your target is friendly or an enemy. Pick a spare page to fill it with spells of its own."] = "分页：处于某个姿态或形态、按住某个键，或目标为友方或敌方时，此动作条可显示另一页按钮。请选择一个备用页面，用于放置它自己的法术。"
L[" Hidden (in combat, out of combat or always): gone, and its buttons can't be clicked."] = " 隐藏（战斗中、战斗外或始终）：动作条消失，其按钮无法点击。"
L["Shadowform page"] = "暗影形态页"
L["while your target is friendly"] = "目标为友方时"
L["while your target is one you can attack"] = "目标为可攻击的敌人时"
L["in Shadowform"] = "处于暗影形态时"
L["Which page of buttons this bar shows %s. Your keybinds cast what the bar shows. No change keeps the bar's own buttons."] = "此动作条在%s显示哪一页按钮。快捷键会施放动作条当前显示的内容。“不更改”会保留动作条自身的按钮。"
L[" A held key's page comes first, then this one, then your stance or form."] = " 按住按键对应的页面优先，其次是此页面，最后是姿态或形态。"
